import { _decorator, assetManager, AssetManager, AudioClip, AudioSource, Component, misc, Node, sys, warn } from "cc";
import { ggLogger } from "db://gg-hot-update/scripts/hotupdate/GGLogger";
import { common } from "../common/common";
import { globalErrorHandler } from "./GlobalErrorHandler";

const { ccclass, property } = _decorator;
type BUNDLE_TYPE = string | AssetManager.Bundle;
@ccclass
export class AudioManager extends Component {
    @property(AudioSource)
    bgAudio: AudioSource = null!;

    @property(AudioSource)
    effectAudio: AudioSource = null!;

    public static instance: AudioManager;

    private MUSIC_SWITCH: boolean = true;
    private SOUND_SWITCH: boolean = true;

    private musicName: string = "";
    private bundle: BUNDLE_TYPE = "";
    private num: number = 0;
    private audioSources: Map<string, AudioSource> = new Map();

    protected onLoad(): void {
        AudioManager.instance = this;
        this.init();
    }

    private init() {
        this.num = 0;
        this.MUSIC_SWITCH = this.getConfiguration(true);
        this.SOUND_SWITCH = this.getConfiguration(false);
        //ggLogger.log("初始化音乐开关", this.MUSIC_SWITCH);
        //ggLogger.log("初始化音效开关", this.SOUND_SWITCH);
        this.stopMusic();
        
        // 确保全局错误处理器已初始化
        globalErrorHandler;
    }

    public getConfiguration(isMusic: boolean): boolean {
        const key = isMusic ? common.MUSIC_SWITCH : common.SOUND_SWITCH;
        const state = sys.localStorage.getItem(key);
        return state === null || state === undefined || state === "true";
    }

    private async loadAudioClip(name: string, bundle: BUNDLE_TYPE): Promise<AudioClip | null> {
        if (!bundle) return null;
        if (typeof bundle === "string") {
            bundle = assetManager.getBundle(bundle);
            if (!bundle) {
                warn(`Bundle ${bundle} not found`);
                return null;
            }
        }
        return new Promise((resolve, reject) => {
            bundle.load(`res/audio/${name}`, AudioClip, (err, clip) => {
                if (err) {
                    warn("load audioClip failed: ", err);
                    reject(err);
                    return;
                }
                resolve(clip);
            });
        });
    }

    public async playMusic(name: string, bundle: BUNDLE_TYPE = "Lobby", loop: boolean = true, volume: number = 1) {
        this.bgAudio?.stop();
        this.musicName = name;
        this.bundle = bundle;
        this.setMusicVolume(volume);

        if (!this.MUSIC_SWITCH) return;
        if (name == "") return;
        let isVol = this.getConfiguration(true);
        if (isVol == null || isVol) this.setMusicVolume(1);

        try {
            const clip = await this.loadAudioClip(name, bundle);
            if (!clip) {
                ggLogger.log(`playMusic ${name} 不存在`);
                return;
            }

            this.setMusicVolume(volume);
            this.bgAudio.clip = clip;
            this.bgAudio.loop = loop;
            //屏蔽此处  不然设置背景声音大小失效
            // this.setMusicVolume(1);
            this.bgAudio.play();
        } catch (error) {
            ggLogger.log(`playMusic ${name} 加载失败:`, error);
        }
    }

    public stopMusic() {
        this.bgAudio?.stop();
    }

    public pauseMusic() {
        if (!this.MUSIC_SWITCH) return;
        this.bgAudio.pause();
    }

    public resumeMusic() {
        if (!this.MUSIC_SWITCH) return;
        if (!this.bgAudio.clip && this.musicName) {
            this.playMusic(this.musicName, this.bundle);
        } else {
            this.bgAudio.play();
        }
    }
    public pauseEffect(name: string) {
        if (!this.SOUND_SWITCH) return;
        const audio = this.audioSources.get(name);
        this.audioSources.forEach(audioSource => {
            if (audio == audioSource) {
                audioSource.pause();
            }
        });
    }

    public resumeEffect(name: string) {
        if (!this.SOUND_SWITCH) return;
        const audio = this.audioSources.get(name);
        this.audioSources.forEach(audioSource => {
            if (audio == audioSource) {
                audioSource.play();
            }
        });
    }

    public stopEffect(name: string) {
        const audioSource = this.audioSources.get(name);
        if (audioSource && audioSource.playing) {
            audioSource.stop();
            audioSource.node.destroy();
            this.audioSources.delete(name);
        }
    }

    // 获取音效资源
    public getEffectAudioSource(name: string) {
        const audioSource = this.audioSources.get(name);
        if (audioSource) {
            return audioSource;
        }
        return null;
    }

    public async playEffect(name: string, bundle: BUNDLE_TYPE = "Lobby", loop: boolean = false, volume: number = 1.0) {
        if (!this.SOUND_SWITCH || !name) return;
        try {
            const clip = await this.loadAudioClip(name, bundle);
            if (!clip) {
                ggLogger.log(`playEffect ${name} 不存在`);
                return;
            }
            let audioSource = this.audioSources.get(name);
            if (!audioSource) {
                const node = new Node(`AudioEffect_${name}`);
                audioSource = node.addComponent(AudioSource);
                this.audioSources.set(name, audioSource);
            } else {
                if (audioSource.playing) {
                    this.num++;
                    const node = new Node(`AudioEffect_${name}${this.num}`);
                    audioSource = node.addComponent(AudioSource);
                    this.audioSources.set(name, audioSource);
                }
            }

            this.setEffectVolume(volume);
            // ggLogger.log("playEffect：", audioSource.node.name);
            audioSource.loop = loop;
            audioSource.clip = clip;
            audioSource.play();
        } catch (error) {
            ggLogger.log(`playEffect ${name} 加载失败:`, error);
        }
    }

    public stopAll() {
        this.stopMusic();
        this.stopAllEffect();
    }

    public stopAllMusic() {
        this.stopAll();
        this.setMusicVolume(0);
        this.setEffectVolume(0);
    }

    public stopAllEffect() {
        this.num = 0;
        this.audioSources.forEach(audioSource => {
            if (audioSource.playing) {
                audioSource.stop();
            }
        });

        this.audioSources.clear();
    }

    public getEffectStatus(): boolean {
        return this.SOUND_SWITCH;
    }

    public getMusicStatus(): boolean {
        return this.MUSIC_SWITCH;
    }

    public setMusicVolume(volume: number) {
        if(this.bgAudio)
        {
        this.bgAudio.volume = misc.clampf(volume, 0, 1);
        }
    }

    public setEffectVolume(volume: number) {
        if(this.effectAudio)
        {
            this.effectAudio.volume = misc.clampf(volume, 0, 1);
        this.audioSources.forEach(audioSource => {
            audioSource.volume = misc.clampf(volume, 0, 1);
        });
        }
    }

    public getEffectVolume(): number {
        return this.effectAudio.volume;
    }

    public getMusicVolume(): number {
        return this.bgAudio.volume;
    }

    // 额外提供开关控制方法，避免直接修改状态变量
    public setMusicSwitch(enabled: boolean) {
        this.MUSIC_SWITCH = enabled;
        if (!enabled) {
            this.stopMusic();
        } else if (this.musicName) {
            let volume = this.getMusicVolume();
            this.playMusic(this.musicName, this.bundle, true, volume);
        }
        sys.localStorage.setItem(common.MUSIC_SWITCH, enabled.toString());
    }

    public setSoundSwitch(enabled: boolean) {
        this.SOUND_SWITCH = enabled;
        if (!enabled) {
            this.stopAllEffect();
        }
        sys.localStorage.setItem(common.SOUND_SWITCH, enabled.toString());
    }
}