import { config } from "../common/config";
import { i18n_t } from "../i18n/LanguageData";
import { Http, HttpClient, HttpPackage } from "../net/http/HttpClient";
import { tools } from "../tools/tools";
import { ui } from "../ui/ui";
import { BaseLogic } from './BaseLogic';
export class MoneyLogic extends BaseLogic {
    constructor() { super(); }
    /*获取充值商品列表
      resourceId 	资源标识：1充值商品，2礼包商品,3奖券商城,4道具商城
      version       版本号(时间戳格式)
      updateTime    最后更新时间
      productId     充值商品ID
      price         商品价格
      sortId        排序号，越大越排前
      productType
      purchaseId   内购ID
      goodsId      物品ID
      goodsNumber  物品数量
      officialGift 首充赠送数量
      isFirstPayDouble 首充翻倍 false：不翻倍 true：翻倍
    */
    requestGoodsList(callback?) {
        let pack = new HttpPackage();
        pack.path = config.api.Mall.goodslist;
        pack.header = [{ name: "Content-Type", value: "application/json" }, { name: "Token", value: tools.getToken() }];
        pack.responseType = "text";
        pack.type = Http.Type.GET;
        HttpClient.ins.setURL(2);
        HttpClient.ins.request(pack, (resp) => {
            resp = JSON.parse(resp);
            if (resp && resp["code"] == 200) {
                callback && callback(resp["data"]);
            }
        })
    }

    requestOrderRecord(obj) {
        return new Promise((resolve, reject) => {
            let pack = new HttpPackage();
            pack.path = config.api.Record.rechargeorders;
            pack.header = [{ name: "Content-Type", value: "application/json" }, { name: "Token", value: tools.getToken() }];
            pack.responseType = "text";
            pack.params = obj;
            pack.type = Http.Type.GET;
            HttpClient.ins.setURL(2);
            HttpClient.ins.request(pack, (resp) => {
                resp = JSON.parse(resp);
                if (resp && resp["code"] == 200) {
                    resolve(resp["data"]);
                } else {
                    ui.createTips(i18n_t("dycLan.networkError"));
                    resolve(null);
                }
            })
        })
    }

    requestPayH5(obj, callback?) {
        let pack = new HttpPackage();
        pack.path = config.api.Pay.h5;
        pack.header = [{ name: "Content-Type", value: "application/json" }, { name: "Token", value: tools.getToken() }];
        pack.responseType = "text";
        pack.params = obj;
        pack.type = Http.Type.GET;
        HttpClient.ins.setURL(2);
        HttpClient.ins.request(pack, (resp) => {
            resp = JSON.parse(resp);
            if (resp && resp["code"] == 200) {
                callback && callback(resp["data"]);
            }
        })
    }
}