import { Asset, director, resources } from "cc";
import { JSB } from "cc/env";
import { ggLogger } from "db://gg-hot-update/scripts/hotupdate/GGLogger";
import { common } from "../common/common";
import { config } from "../common/config";
import { enums } from "../common/enums";
import { PackageId } from "../common/PackageId";
import { ProtoMgr } from "../data/ProtoMgr";
import AdjustBridge from "../market/AdjustBridge";
import { Market } from "../market/Market";
import { Http, HttpClient, HttpPackage } from "../net/http/HttpClient";
import { OneSocket } from "../net/OneSocket";
import SocketBuffer from "../net/protocol/SocketBuffer";
import { tools } from "../tools/tools";
import { Validate } from "../tools/Validate";
import { BaseLogic } from "./BaseLogic";

/**登陆逻辑 */
export class LoginLogic extends BaseLogic {
    constructor() {
        super();
        //大厅逻辑
        director.on("onLobbyLogic", (msg) => {
            if (msg.type == 0) {
                this.onTokenLobby(msg.data);
            } else if (msg.type == 1) {
                this.loginSuccess(msg.data);
            } else if (msg.type == 2) {
                this.onGameList(msg.data);
            }
        }, this);
    }

    //加载证书
    onCacert() {
        resources.load('cacert/cacert', Asset, (err, asset) => {
            if (err) {
                ggLogger.error(err);
                return;
            }
            tools.wssCacertUrl = asset.nativeUrl;
        });
    }
    //先请求url拿到配置
    onDirectCon() {
        return new Promise(async (resolve, reject) => {
            let pack = new HttpPackage();
            pack.path = config.api.Direct.domain;
            pack.header = { name: "Content-Type", value: "application/json" };
            pack.responseType = "text";
            pack.type = Http.Type.GET;
            HttpClient.ins.setURL(3);
            HttpClient.ins.request(pack, (resp) => {
                resp = JSON.parse(resp);
                if (resp["code"] == 200) {
                    let pack2 = new HttpPackage();
                    pack2.isURL = false;
                    pack2.path = resp["data"]["APIServer"] + config.api.Direct.gate;
                    pack2.header = { name: "Content-Type", value: "application/json" };
                    pack2.responseType = "text";
                    pack2.type = Http.Type.GET;
                    HttpClient.ins.request(pack2, (resp2) => {
                        resp2 = JSON.parse(resp2);
                        ggLogger.log("gate===>", resp2);
                        if (resp2["code"] == 200) {
                            if (resp2["data"]) {
                                let obj = this.chaValue(resp2["data"]);
                                if (obj) {
                                    (<any>window).pConfig.ws_addr = obj["addr"];
                                    (<any>window).pConfig.ws_port = obj["port"];
                                }
                            }
                            resolve(true);
                        } else {
                            resolve(false);
                        }
                    });
                } else {
                    resolve(false);
                }
            });
        });
    }

    chaValue(arr) {
        interface Item {
            peopleNumber: number;
        }
        function findMinObject(arr: Item[], key: keyof Item = "peopleNumber"): Item | null {
            if (arr.length === 0) return null;
            let minItem = arr[0];
            for (let i = 1; i < arr.length; i++) {
                if (arr[i][key] < minItem[key]) {
                    minItem = arr[i];
                }
            }
            return minItem;
        }
        const minVal = findMinObject(arr);
        return minVal;
    }

    //登陆成功
    loginSuccess(data) {
        this.onSuccessData(data);
        if (common.USERNAME != "" && common.USERPASS != "") {
            tools.setAccount(common.USERNAME);
            tools.setPassword(common.USERPASS);
        }
        if (!common.ISHALLBACK) {//游戏数据列表
            let msg = new SocketBuffer(PackageId.MsgResponseGameList);
            let buf = OneSocket.getInstance().packData.pack(msg);
            this.sendData(PackageId.MsgRequstGameList, buf);
            director.emit("loadSuccess", { bResult: true, msg: data });
        }
    }

    onSuccessData(data) {
        common.TOKEN = data.Token;
        tools.setToken(data.Token);

        //ggLogger.log("succ====>", data);
        tools.myInfo.userAvataUrl = data.User.SystemAvatar;
        tools.myInfo.userGold = data.User.Gold;
        tools.myInfo.userName = data.User.Nickname;
        tools.myInfo.userID = data.User.UserId;
        tools.myInfo.gender = data.User.Gender ? data.User.Gender : 0;
        tools.myInfo.VipPoint = data.User.VipPoint ? data.User.VipPoint : 0;
        tools.myInfo.betScore = data.User.BetScore ? data.User.BetScore : 0;
        tools.myInfo.isReg = data.User.IsReg;
        tools.myInfo.channelId = data.User.ChannelId;
        tools.myInfo.loginCount = data.User.LoginCount;
        tools.myInfo.loginType = data.User.accountType;
        tools.myInfo.roomID = data.InRoomId ? data.InRoomId : "";

        if (JSB) AdjustBridge.getInstance().trackEvent("login_success");
        // ggLogger.log("登陆成功:", data);
    }

    //请求登陆数据初始化paymentTerms
    requestLoginInit() {
        let pack = new HttpPackage();
        pack.path = config.api.User.init;
        pack.header = [{ name: "Content-Type", value: "application/json" }, { name: "Token", value: tools.getToken() }];
        pack.responseType = "text";
        pack.type = Http.Type.GET;
        HttpClient.ins.setURL(2);
        HttpClient.ins.request(pack, (resp) => {
            resp = JSON.parse(resp);
            if (resp && resp["code"] == 200) {
                tools.loginData = resp["data"];
                tools.googleURL = tools.loginData["channelContact"];
                // ggLogger.log("登陆初始化<====>", tools.loginData);
            } else {
                tools.loginData = null;
            }
        })
    }

    onGameList(data) {
        //let hallConfig = data.Game;
        //ggLogger.log("游戏列表：");
    }

    /**直接跳游戏 */
    async loginToGame(type: number, token: any, gameID: number, way: number = 2, fun: Function = null) {
        this.loginVaildate();
        await OneSocket.getInstance().isValidateSucc();
        tools.setAccountType("direct");
        this.onTokenH5Game(token, gameID, way, fun);
    }

    /**登陆类型*/
    async loginLabby(type: number, accountStr: any = "", passwordStr: any = "", eType: number = 0, area: string = "") {
        this.loginVaildate();
        await OneSocket.getInstance().isValidateSucc();
        director.emit("hideNetNode");
        if (type == enums.USER_LOGIN.custom) {
            tools.setAccountType("custom");
            this.onVisitorLobby();
            return
        } else if (type == enums.USER_LOGIN.token) {
            this.onTokenLobby(eType);
            return
        } else if (type == enums.USER_LOGIN.Account) {
            common.USERNAME = accountStr;
            common.USERPASS = passwordStr;
            tools.setAccountType("Account");
            if (eType == 1) {
                this.onRegisterLobby(accountStr, passwordStr);
            } else {
                this.onLoginLobby(accountStr, passwordStr);
            }
            return
        } else if (type == enums.USER_LOGIN.telephone) {
            common.USERNAME = accountStr;
            common.USERPASS = passwordStr;
            tools.setAccountType("telephone");
            let str = area.replace(/\+/g, "") + accountStr;
            if (eType == 1) {
                this.onMobileRegisterLobby(str, passwordStr);
            } else {
                this.onMobileLoginLobby(str, passwordStr);
            }
            return
        }
    }


    /**先验证 然后再登陆*/
    async loginVaildate() {
        director.emit("showNetNode");
        let buf = await Validate.sendValidate();
        let data = ProtoMgr.getInstance().encodeLoginMgr("ReqVaidate", {
            Data: buf,
        });
        this.sendData(PackageId.MsgReqVaidate, data);
    }

    /**游客登陆*/
    onVisitorLobby() {
        //机器码固定
        let data = ProtoMgr.getInstance().encodeLobbyMgr("RequestTouristLogin", {
            MachineId: Market.getInstance().getDeviceCode(),
            PackageId: PackageId.PACKAGEID,
            SpreadId: 3,
            ChannelId: 4,
            FirebaseToken: config.firebaseToken,
            SpreadType: 6,
            AdjustAdId: config.adjustAppId, //Adjust广告Id
            GpsAdid: config.gpsAdid,// 谷歌广告Id
            Idfv: config.idfv, //苹果Id
        });
        this.sendData(PackageId.MsgRequestTouristLogin, data);
    }

    /**token h5直连登陆*/
    onTokenH5Game(token, gameID: number, way: number = 2, fun: Function = null) {
        if (!token) {
            ggLogger.error("===>token不存在");
            return;
        }
        //机器码固定
        let data = ProtoMgr.getInstance().encodeLobbyMgr("RequestTokenLoginH5", {
            Token: token,
            MachineId: Market.getInstance().getDeviceCode(),
            LoginWay: way,//0:新的登录 1:重连
            AdjustAdId: config.adjustAppId, //Adjust广告Id
            GpsAdid: config.gpsAdid,// 谷歌广告Id
            Idfv: config.idfv, //苹果Id
        });
        this.removeNetCallback(PackageId.MsgResLoginSuccess);
        this.sendData(PackageId.MsgRequestTokenLoginH5, data, PackageId.MsgResLoginSuccess, (obj) => {
            let res = ProtoMgr.getInstance().decodeLobbyMgr('ResLoginSuccess', obj.data);
            this.removeNetCallback(PackageId.MsgResLoginSuccess);
            if (res) {
                this.onSuccessData(res);
                let roomId = tools.myInfo.roomID;
                if (!roomId || roomId === "") {
                    roomId = 0;
                    ggLogger.log("重连时roomID为空，使用0让服务器分配新房间");
                }
                let data = ProtoMgr.getInstance().encodeLobbyFrameMgr("RequestEnterRoom", { GameId: gameID, ScreenId: 1, RoomId: roomId });
                this.removeNetCallback(PackageId.MsgResponseEnterTableSuccess);
                this.sendData(PackageId.MsgRequestEnterRoom, data, PackageId.MsgResponseEnterTableSuccess, (obj3) => {
                    let res2 = ProtoMgr.getInstance().decodeLobbyFrameMgr('ResponseEnterTableSuccess', obj3.data);
                    this.removeNetCallback(PackageId.MsgResponseEnterTableSuccess);
                    if (res2 && res2.EnterType == 1) {
                        tools.myInfo.ScreenId = res.ScreenId;
                        fun && fun(res2.GameId);
                    }
                });
            }
        });
    }


    /**token登陆*/
    onTokenGame(token, gameID: number, way: number = 2, fun: Function = null) {
        if (!token) {
            ggLogger.error("===>token不存在");
            return;
        }
        //机器码固定
        let data = ProtoMgr.getInstance().encodeLobbyMgr("RequestTokenLogin", {
            Token: token,
            MachineId: Market.getInstance().getDeviceCode(),
            LoginWay: way,//0:新的登录 1:重连
            AdjustAdId: config.adjustAppId, //Adjust广告Id
            GpsAdid: config.gpsAdid,// 谷歌广告Id
            Idfv: config.idfv, //苹果Id
        });
        this.removeNetCallback(PackageId.MsgResLoginSuccess);
        this.sendData(PackageId.MsgReqTokenLogin, data, PackageId.MsgResLoginSuccess, (obj) => {
            let res = ProtoMgr.getInstance().decodeLobbyMgr('ResLoginSuccess', obj.data);
            this.removeNetCallback(PackageId.MsgResLoginSuccess);
            if (res) {
                this.onSuccessData(res);
                let roomId = tools.myInfo.roomID;
                if (!roomId || roomId === "") {
                    roomId = 0;
                }
                let data = ProtoMgr.getInstance().encodeLobbyFrameMgr("RequestEnterRoom", { GameId: gameID, ScreenId: 1, RoomId: roomId });
                this.removeNetCallback(PackageId.MsgResponseEnterTableSuccess);
                this.sendData(PackageId.MsgRequestEnterRoom, data, PackageId.MsgResponseEnterTableSuccess, (obj3) => {
                    let res2 = ProtoMgr.getInstance().decodeLobbyFrameMgr('ResponseEnterTableSuccess', obj3.data);
                    this.removeNetCallback(PackageId.MsgResponseEnterTableSuccess);
                    if (res2 && res2.EnterType == 1) {
                        tools.myInfo.ScreenId = res.ScreenId;
                        fun && fun(res2.GameId);
                    }
                });
            }
        });
    }


    /**token登陆*/
    onTokenLobby(nk) {
        let token = tools.getToken();
        if (!token) token = common.TOKEN;

        if (!token) {
            ggLogger.error("===>token不存在");
            return;
        }
        //机器码固定
        let data = ProtoMgr.getInstance().encodeLobbyMgr("RequestTokenLogin", {
            Token: token,
            MachineId: Market.getInstance().getDeviceCode(),
            LoginWay: nk,//0:新的登录 1:重连
        });
        this.sendData(PackageId.MsgReqTokenLogin, data);
    }

    /**注册登陆*/
    onRegisterLobby(accountStr: any, passwordStr: any) {
        let data = ProtoMgr.getInstance().encodeLobbyMgr("RequestUserNameReg", {
            UserName: accountStr, //账号
            Password: passwordStr, //密码
            MachineId: Market.getInstance().getDeviceCode(),
            PackageId: PackageId.PACKAGEID,
            SpreadId: 4,
            FirebaseToken: config.firebaseToken,
            ChannelId: 6,
            AdjustAdId: config.adjustAppId, //Adjust广告Id
            GpsAdid: config.gpsAdid,// 谷歌广告Id
            Idfv: config.idfv, //苹果Id
        });
        this.sendData(PackageId.MsgRequestUserNameReg, data);
    }

    /**按钮登陆*/
    onLoginLobby(accountStr: any, passwordStr: any) {
        let data = ProtoMgr.getInstance().encodeLobbyMgr("RequestUserNameLogin", {
            UserName: accountStr, //账号
            Password: passwordStr, //密码
            MachineId: Market.getInstance().getDeviceCode(),
        });
        this.sendData(PackageId.MsgRequestUserNameLogin, data);
    }


    /**注册电话号码登陆*/
    onMobileRegisterLobby(accountStr: any, passwordStr: any) {
        let data = ProtoMgr.getInstance().encodeLobbyMgr("RequestMobileReg", {
            Phone: accountStr, //手机号 //手机号 格式：区号+手机号，例如：201012345678
            Password: passwordStr, //密码
            MachineId: Market.getInstance().getDeviceCode(),
            PackageId: PackageId.PACKAGEID,
            SpreadId: 4,
            ChannelId: 6,
            PhoneCode: 7,
            FirebaseToken: config.firebaseToken,
            SpreadType: 9,
            AdjustAdId: config.adjustAppId, //Adjust广告Id
            GpsAdid: config.gpsAdid,// 谷歌广告Id
            Idfv: config.idfv, //苹果Id
        });
        this.sendData(PackageId.MsgRequestMobileReg, data);
    }

    /**按钮电话号码登陆*/
    onMobileLoginLobby(accountStr: any, passwordStr: any) {
        let data = ProtoMgr.getInstance().encodeLobbyMgr("RequestMobileLogin", {
            Phone: accountStr, //电话号码
            Password: passwordStr, //密码
            MachineId: Market.getInstance().getDeviceCode(),
            FirebaseToken: config.firebaseToken,
            AdjustAdId: config.adjustAppId, //Adjust广告Id
            GpsAdid: config.gpsAdid,// 谷歌广告Id
            Idfv: config.idfv, //苹果Id
        });
        this.sendData(PackageId.MsgRequestMobileLogin, data);
    }
}