import { director, game, sys } from "cc";
import { ggLogger } from "db://gg-hot-update/scripts/hotupdate/GGLogger";
import { common } from "../common/common";
import { ErrorMsg } from "../common/ErrorMsg";
import { PackageId } from "../common/PackageId";
import { i18n_t } from "../i18n/LanguageData";
import { OneSocket } from "../net/OneSocket";
import SocketBuffer from "../net/protocol/SocketBuffer";
import { tools } from "../tools/tools";
import { ui } from "../ui/ui";
import { DataNotify } from "./DataNotify";
import MyInfo from "./MyInfo";
import { ProtoMgr } from "./ProtoMgr";

/**大厅管理类 */
export class LobbyManager {
    private static _instance: LobbyManager = null;
    public urlParams: any = {}; // URL参数对象

    constructor() {
        //清除多余的注册
        director.on("clearNetData", () => {
            this.clearNetData();
        }, this);

        //大厅消息
        director.on("LobbyMessage", (obj) => {
            this.onSocketMsg(obj);
        }, this);

        //判断房间重连是否存在
        director.on("roomNetChange", (isError) => {
            // ggLogger.log("=====>roomNetChange:", isError);
            if (isError) {
                if (tools.gameFrame) {
                    this.clearNetData();
                    director.emit("onRoomConnect");
                } else {
                    director.emit("clearGameNet");
                    this.onReconnect();
                }
            } else {
                if (!tools.gameFrame) {
                    director.emit("popTips", "errLan.dataError");
                }
            }
        }, this);
    }

    clear() {
        tools.myInfo = new MyInfo();
    }

    setMyInfoUserGold(userGold) {
        tools.myInfo.userGold = userGold;
    }

    close(code?: number, reason?: string) {
        OneSocket.getInstance().clearSocket();
    }

    isConnected(): boolean {
        return OneSocket.getInstance().isConnected();
    }

    sendData(requestId: PackageId, data: Uint8Array, responseId: PackageId = PackageId.NORESPONSEID, callbackFun = null) {
        let buf = null;
        if (data) {
            buf = OneSocket.getInstance().packData.pack(new SocketBuffer(requestId, data));
        } else {
            buf = OneSocket.getInstance().packData.pack(new SocketBuffer(requestId))
        }
        if (responseId != PackageId.NORESPONSEID) {
            OneSocket.getInstance().sendData(responseId, buf, callbackFun);
        } else {
            OneSocket.getInstance().sendData(requestId, buf, callbackFun);
        }
    }

    bindingNetCallback(mainID: number, callbackFun) {
        OneSocket.getInstance().bindingNetCallback(mainID, callbackFun);
    }

    removeNetCallback(mainID: number) {
        OneSocket.getInstance().removeNetCallback(mainID);
    }

    checkSocketConnect() { }

    async onReconnect() {
        director.emit("onLobbyLogic", { type: 0, data: 1 });
    }

    backLogin() {
        //退出时清理
        if (common.ISH5DIRECT) {
            tools.sendToUnity("ExitGame", {});
        } else {
            setTimeout(() => {
                ui.changeScene("Lobby", "LoginScene");
            }, 100);
        }
    }

    onSocketMsg(obj) {
        let msgID = obj["msgId"];
        // ggLogger.log(`onSocketMsg收到${msgID}号消息`);
        //大厅消息走进度条发的消息
        if (msgID == PackageId.MsgResponseTableUserList) {//已上桌玩家列表
            tools.userInGameInfo[PackageId.MsgResponseTableUserList] = obj.data;
        } else if (msgID == PackageId.MsgResponseGameStart) {//游戏开始消息
            tools.userInGameInfo[PackageId.MsgResponseGameStart] = obj.data;
            tools.userInGameInfo["time"] = new Date().getTime();
        } else if (msgID == PackageId.MsgResponseGameOver) {//游戏结束消息
            tools.userInGameInfo[PackageId.MsgResponseGameOver] = obj.data;
        } else if (msgID == PackageId.MsgResponseBet) {//玩家下注
            tools.userInGameInfo[PackageId.MsgResponseBet].push(obj.data);
        }

        if (msgID == PackageId.MsgCloseLink) {//2关闭连接
            ggLogger.log(`收到${msgID}号消息：直接关闭连接`, i18n_t("errLan.linkClose"));
            director.emit("hideNetNode");
            if (common.ISH5DIRECT) {
                tools.sendToUnity("ExitGame", {});
            }
        } else if (msgID == PackageId.MsgResHint) {//3提示消息
            let res = ProtoMgr.getInstance().decodeMsgMgr('ResHint', obj.data);
            ggLogger.log(`收到消息${msgID},返回Code:${res.Code}`);
            if (res) {
                if (res.Code == ErrorMsg.RoomUserAlreadyInRoom) {
                    ui.createBox(i18n_t("errLan.inGameing"), (code) => {
                        if (code == 2) {
                            this.clearNetData();
                        }
                    });
                } else if (res.Code == ErrorMsg.RoomEnterFail) {
                    ggLogger.log("进入游戏失败，清理roomID并尝试重新进入游戏");
                    ui.createBox(i18n_t("errLan.dataError"), (code) => {
                        if (code == 2) {
                            this.clearNetData();
                            setTimeout(() => {
                                this.onReconnect();
                            }, 100);
                        }
                    });
                } else if (res.Code == ErrorMsg.RoomNoStockLockHasBeenRequested) {
                    ui.createBox(i18n_t("errLan.noLock"));
                } else if (res.Code == ErrorMsg.RoomUserBetLimitReached) {
                    ui.createBox("Bet Limit Reached");
                } else if (res.Code == ErrorMsg.RoomGoldNotEnough || res.Code == ErrorMsg.RoomDoubleNotOpen || res.Code == ErrorMsg.RoomRageNotOpen) {
                    // ui.createBox(i18n_t("dycLan.moneyNoEnough"));
                } else {
                    ui.createBox(`${res.Code + "===>去做多语言"}`);
                }
                //添加提示 比如游戏中失败相关消息
                director.emit("msgResHint", res);
            }
        } else if (msgID == PackageId.MsgResponseUserBankrupt) {//用户破产
            // let res = ProtoMgr.getInstance().decodeLobbyFrameMgr('ResponseUserBankrupt', obj.data);
            ggLogger.log("用户破产==========>");
        } else if (msgID == PackageId.MsgResponsePaySuccess) {//充值成功
            let res = ProtoMgr.getInstance().decodeLobbyWebMgr('ResponsePaySuccess', obj.data);
            tools.myInfo.VipPoint = res.OrderPrice ? res.OrderPrice : 100;
            director.emit("userPaySuccess", res);
        } else if (msgID == PackageId.MsgResLoginSuccess) {//登成功
            let res = ProtoMgr.getInstance().decodeLobbyMgr('ResLoginSuccess', obj.data);
            if (res) {
                director.emit("onLobbyLogic", { type: 1, data: res });
                if (ui.backCurScene() == "LobbyScene") {
                    ggLogger.log("==================大厅重连成功============");
                    this.clearNetData();
                    director.emit("hideNetNode");
                }
            }
        } else if (msgID == PackageId.MsgResLoginFail) {//登失败
            let res = ProtoMgr.getInstance().decodeLobbyMgr('ResponseLoginFail', obj.data);
            if (res) {
                ggLogger.log(`收到消息${msgID}为登陆失败,返回Code:${res.Code}`);
                if (common.ISH5DIRECT) {
                    tools.sendToUnity("ExitGame", {});
                    return;
                }

                let msg = "";
                if (res.Code == ErrorMsg.RegFailUsernameIsExist) {
                    msg = i18n_t("errLan.registerExist");
                } else if (res.Code == ErrorMsg.LoginTokenFail) {
                    msg = i18n_t("errLan.noToken");
                    ui.createBox(msg, (code) => {
                        if (code == 2) {
                            if (sys.isNative) {
                                tools.setToken("");
                                game.restart();
                            } else {
                                if (common.ISH5DIRECT) {
                                    tools.sendToUnity("ExitGame", {});
                                } else {
                                    tools.setToken("");
                                    (<any>window).location.reload();
                                }
                            }
                        }
                    });
                    return
                } else if (res.Code == ErrorMsg.LoginFail) {
                    msg = i18n_t("errLan.loginStrKai");
                    if (common.ISH5DIRECT) {
                        tools.sendToUnity("ExitGame", {});
                    }
                } else if (res.Code == ErrorMsg.RegFailMobileCodeError) {
                    msg = i18n_t("errLan.failMobile");
                }
                if (msg != "") ui.createBox(msg);
            }
        } else if (msgID == PackageId.MsgResponseGameList) {//返回游戏列表
            let res = ProtoMgr.getInstance().decodeLobbyMgr('ResponseGameList', obj.data);
            if (res) director.emit("onLobbyLogic", { type: 2, data: res });
        } else if (msgID == PackageId.MsgResponseTableData) {//进入桌子信息
            let res = ProtoMgr.getInstance().decodeLobbyFrameMgr('ResponseTableData', obj.data);
            if (res) {
                tools.myInfo.IsAllowLookon = res.IsAllowLookon;
                tools.myInfo.MaxPeopleNumber = res.MaxPeopleNumber;
                tools.myInfo.MinPeopleNumber = res.MinPeopleNumber;
                tools.myInfo.SettlementTime = res.SettlementTime;
                tools.myInfo.ShowScoreTime = res.ShowScoreTime;
                tools.myInfo.TableId = res.TableId;
                tools.myInfo.roomID = res.RoomId;
            }
        } else if (msgID == PackageId.MsgResponseUserInfo) {//用户信息
            let res = ProtoMgr.getInstance().decodeLobbyFrameMgr('ResponseUserInfo', obj.data);
            if (res) {
                tools.myInfo.ChairId = res.ChairId;
                tools.myInfo.userGold = res.Gold;
                tools.myInfo.userName = res.Nickname;
                tools.myInfo.userID = res.UserId;
                tools.myInfo.UserState = res.UserState;
            }
        } else if (msgID == PackageId.MsgResponseEnterTableSuccess) {//进入游戏成功
            let res = ProtoMgr.getInstance().decodeLobbyFrameMgr('ResponseEnterTableSuccess', obj.data);
            // ggLogger.log("进入游戏成功", res);
            if (res && res.EnterType == 1) {
                tools.myInfo.ScreenId = res.ScreenId;
                director.emit("userInGame", res.GameId);
            }
        } else if (msgID == PackageId.MsgResponseWealth) {//金币刷新
            let res = ProtoMgr.getInstance().decodeComMgr('ResponseWealth', obj.data);
            if (res) {
                tools.myInfo.userGold = res.Gold;
                DataNotify.getInstance().onGoldChanged(res.Gold);
                director.emit("userGoldChange", res.Gold);
                director.emit("userUIChange");
            }
        } else if (msgID == PackageId.MsgResponseEnterScreenData) {//场景消息
            tools.screeninfo = obj.data;
        } else if (msgID == PackageId.MsgResponseTableUserList) {//已上桌玩家列表
            let data = ProtoMgr.getInstance().decodeLobbyFrameMgr('ResponseUserList', obj.data);
            if (data) {
                tools.myInfo.tableUserList = data;
            }
        } else if (msgID == PackageId.MsgResponseFishingUserInfo) {//捕鱼用户信息
            let res = ProtoMgr.getInstance().decodeLobbyFrameMgr('ResponseFishingUserInfo', obj.data);
            tools.userFishInfo.push(res);//增加用戶信息
            director.emit("userFishInfoChange", res);
            ggLogger.log("捕鱼用户信息", res);
        } else if (msgID == PackageId.MsgResponseManagePleaseOffline) {//被管理员请下线
            //let res = ProtoMgr.getInstance().decodeLoginMgr('ResponseManagePleaseOffline', obj.data);
            ggLogger.log("被管理员请下线");
            if (common.ISH5DIRECT) {
                tools.sendToUnity("ExitGame", {});
                return;
            }

            OneSocket.getInstance().setAutoReconnect(false);
            ui.createBox(i18n_t("errLan.pushOffline"), (code) => {
                if (common.ISH5DIRECT) {
                    common.ISH5CLOSE = true;
                    director.emit("showNetNode");
                } else {
                    this.backLogin();
                }
            });
        } else if (msgID == PackageId.MsgResponseOtherLoginPushedOffline) {//其他地方登录，被踢下线
            ggLogger.log(`收到${msgID},其他地方登录，被踢下线`);
            OneSocket.getInstance().setAutoReconnect(false);
            if (common.ISH5DIRECT) {
                tools.sendToUnity("ExitGame", {});
                return;
            }
            ui.createBox(i18n_t("errLan.pushOffline"), (code) => {
                if (code == 2) {//2表示ok
                    if (common.ISH5DIRECT) {
                        common.ISH5CLOSE = true;
                        director.emit("showNetNode");
                    } else {
                        this.backLogin();
                    }
                } else {//1表示cancal
                    OneSocket.getInstance().retryConnectManually();
                    setTimeout(() => {
                        OneSocket.getInstance().onReConnected();
                    }, 500)
                }
            }, 2);
        } else if (msgID == PackageId.MsgResponseLeaveRoom) {//离开房间
            //let res = ProtoMgr.getInstance().decodeLobbyFrameMgr("ResponseLeaveRoom", obj.data);
            this.clearNetData();
            tools.userFishInfo = [];
            director.emit("leaveRoom");
        } else if (msgID == PackageId.MsgResponseLevaveTable) {//离开桌子
            let res = ProtoMgr.getInstance().decodeLobbyFrameMgr("ResponseLeaveTable", obj.data);
            ggLogger.log("离开桌子", res);
            if (tools.userFishInfo && tools.userFishInfo.length > 0) {
                for (let i = tools.userFishInfo.length - 1; i >= 0; i--) {
                    const userInfo = tools.userFishInfo[i];
                    if (userInfo.UserId === res.UserId) {
                        tools.userFishInfo.splice(i, 1);
                        break;
                    }
                }
            }
            director.emit("leaveDesk", res);
        }
    }
    clearNetData() {
        tools.myInfo.roomID = "";
        this.removeNetCallback(PackageId.MsgReqTokenLogin);
        this.removeNetCallback(PackageId.MsgResLoginSuccess);
        this.removeNetCallback(PackageId.MsgRequestEnterRoom);
        this.removeNetCallback(PackageId.MsgRequestTokenLoginH5);
        this.removeNetCallback(PackageId.MsgResponseEnterTableSuccess);
    }

    static getInstance(): LobbyManager {
        if (null == this._instance) {
            this._instance = new LobbyManager();
        }
        return this._instance;
    }

    static destroyInstance() {
        if (this._instance) {
            delete this._instance;
            this._instance = null;
        }
    }
}