    static findInterval(arr, target) {
        const n = arr.length;
        if (n === 0) return -1;
        if (target < arr[0]) return -1;
        if (target >= arr[n - 1]) return n - 1;

        let left = 0, right = n - 1;
        while (left <= right) {
            const mid = Math.floor((left + right) / 2);
            if (arr[mid] <= target && target < arr[mid + 1]) {
                return mid;
            } else if (arr[mid] > target) {
                right = mid - 1;
            } else {
                left = mid + 1;
            }
        }
        return -1; // 理论上不会到这里
    }

