    // 只转成K 
    static moneyToShortToK(num: number, isRate: boolean = true): string {
        // num = 1000000.1;
        // num = -1000000.1;

        if (isRate) {
            num = num / tools.RATE;
        };

        let symbolStr: string = "";
        let absnum = Math.abs(num);
        let _unit = "";
        let _ibase = 1;
        if (absnum >= 1000) {
            _unit = "K";
            _ibase = 1000
        }

        if (num >= 0) {
            symbolStr = Math.floor(absnum / _ibase) + _unit;

        } else {
            symbolStr = "-" + Math.floor(absnum / _ibase) + _unit;

        };
        return symbolStr
    }


