    static formatGoldWithComma(num: number, isRate: boolean = true, istoFixed: boolean = true, comma = ","): string {
        let strNum: string = null;
        if (isRate) {
            num = num / tools.RATE;
        };

        if (istoFixed) {
            strNum = num.toFixed(tools.TO_FIXNUM);
        } else {
            strNum = String(num);
        };

        //分隔小数
        let [integerPart, decimalPart] = strNum.split('.');

        //整数千分位
        integerPart = integerPart.replace(/\B(?=(\d{3})+(?!\d))/g, comma);

        let outputstr: string = decimalPart ? `${integerPart}.${decimalPart}` : integerPart
        return outputstr;
    }

