    /*
    根据两个点获取角度
    */
    static getAngleFromTowPoints(beginP: Vec3, endP: Vec3, offect: number = 0) {
        let beginPos = beginP;
        let endPos = endP;
        let dp = new Vec3(endPos.x - beginPos.x, endPos.y - beginPos.y);
        if (0 == dp.x) {
            if (dp.y > 0) return 0 + offect;
            else return 180 + offect;
        }
        let v = dp.y / dp.x;
        let radian = Math.atan(v);
        let dt = 0;
        if (radian < 0) {
            if (dp.y < 0) dt = 2 * Math.PI - Math.abs(radian);
            else dt = Math.PI - Math.abs(radian);
        } else if (0 == radian) {
            if (dp.x < 0) dt = Math.PI - Math.abs(radian);
            else dt = 2 * Math.PI - Math.abs(radian);
        } else {
            if (dp.y < 0) dt = Math.PI + Math.abs(radian);
            else dt = Math.abs(radian);
        }
        dt = 2 * Math.PI - dt + Math.PI / 2;
        let angle = (dt * 180) / Math.PI;
        return angle + offect;
    }

    /*
    根据两个点获取距离
    */
    static getDistanceFromTowPoints(beginP: Vec3, endP: Vec3) {
        return Math.sqrt(Math.pow(endP.x - beginP.x, 2) + Math.pow(endP.y - beginP.y, 2));
    }


