    /**
    * label数值缓动变化
    * @param node 
    * @param startValue 初始值
    * @param targetValue 目标值
    * @param time 持续时间
    * @param callback 回调
    * @returns 
    */
    static tweenLabelNumber(node, startValue: number, targetValue: number, time: number = 0.2, callback?: Function, isToFixed: boolean = true) {
        let labelNode = this.getLabel(node);
        if (!isValid(labelNode)) {
            return;
        }
        let obj = { value: startValue };
        tween(obj)
            .tag(100)
            .to(time, { value: targetValue }, {
                progress: (start, end, current, ratio) => {
                    //
                    if (node instanceof Label) {
                        if (!isValid(node.node, true)) {
                            tween(obj).stop();
                            Tween.stopAllByTarget(obj);
                            return current;
                        }
                    } else {
                        if (!isValid(node, true)) {
                            tween(obj).stop();
                            Tween.stopAllByTarget(obj);
                            return current;
                        }
                    }
                    //
                    let n = (start + (end - start) * ratio);
                    if (isToFixed) {
                        labelNode.string = n.toFixed(2);
                    } else {
                        labelNode.string = Math.floor(n).toString();
                    }
                    return current;
                }
            })
            .call(() => {
                callback && callback();
            })
            .start();
        return obj;
    }

