    /*** 资源加载*/
    public static async loadAssetAsync<T extends Asset>(
        path: string,
        type: Constructor<T>,
        bundleName: string = "Lobby"
    ): Promise<T | null> {
        const bundle = assetManager.getBundle(bundleName);
        if (!bundle) {
            ggLogger.warn(`Bundle not found: ${bundleName}`);
            return null;
        }
        const cached = bundle.get(path, type);
        if (cached) return cached;
        return new Promise<T | null>((resolve) => {
            bundle.load(path, type, (err, asset) => {
                if (err) {
                    ggLogger.error(`Load failed: ${path} from ${bundleName}`, err);
                    resolve(null);
                } else {
                    resolve(asset as T);
                }
            });
        });
    }

    public static async addPrefab(path: string, parent: Node, bundleName: string = "Lobby", data?: any, onComplete?: (error: Error, node: Node) => void) {
        if (!parent) {
            ggLogger.log(`error  parent null`)
            return
        }
        function createNode(assets: Prefab): Node {
            let node = instantiate(assets)
            parent.addChild(node)
            let baseComponent = node.getComponent(BaseComponent)
            if (baseComponent) {
                baseComponent.onLoadAfter(data)
            }
            return node
        }
        let prefab = await tools.loadAssetAsync(path, Prefab, bundleName);
        if (prefab) {
            let node = createNode(prefab)
            onComplete && onComplete(null, node)
        } else {
            ggLogger.warn(`add ${path} error!`)
        }
    }


