    /*  二阶贝塞尔曲线 运动
    * @param target
    * @param {number} duration
    * @param {} c1 起点坐标
    * @param {} c2 控制点
    * @param {Vec3} to 终点坐标
    * @param opts
    * @returns {any}
    */
    static bezierTo(target: any, duration: number, c1: Vec2, c2: Vec2, to: Vec3, opts: any) {
        opts = opts || Object.create(null);
        /**
         * @desc 二阶贝塞尔
         * @param {number} t 当前百分比
         * @param {} p1 起点坐标
         * @param {} cp 控制点
         * @param {} p2 终点坐标
         * @returns {any}
         */
        let twoBezier = (t: number, p1: Vec2, cp: Vec2, p2: Vec3) => {
            let x = (1 - t) * (1 - t) * p1.x + 2 * t * (1 - t) * cp.x + t * t * p2.x;
            let y = (1 - t) * (1 - t) * p1.y + 2 * t * (1 - t) * cp.y + t * t * p2.y;
            return v3(x, y, 0);
        };
        opts.onUpdate = (arg: Vec3, ratio: number) => {
            target.position = twoBezier(ratio, c1, c2, to);
        };
        return tween(target).to(duration, {}, opts);
    }

    //停止节点对象绑定的缓动, 通常节点删除的时候会， 缓动会自动删除，也可以在特定时候主动停止缓动 
    public static stopTweenByNode(node: Node) { Tween.stopAllByTarget(node); }
    public static stopTween(t) { t.stop(); } // 停止特定缓动


    // 循环执行回调
    // delayTime 循环间隔时间， 秒
    // func 回调
    // node 绑定该缓动的节点, 绑定节点是为了方便停止 
    public static doLoopTween(delayTime: number, func, node: Node) {
        let t = tween(node).repeatForever(
            tween()
                .call(() => {
                    func();
                })
                .delay(delayTime)
        ).start();
        return t;
    }

    //延迟执行回调
    // delayTime 延迟时间， 秒
    // func 回调
    // node 绑定该缓动的节点, 绑定节点是为了方便停止 
    public static doDelayTween(delayTime: number, func, node: Node) {
        let t = tween(node)
            .delay(delayTime)
            .call(() => { func(); })
            .start();
        return t;
    }

