    static padZero(num) {
        return (num < 10 ? '0' : '') + num;
    }

    static formatTimestamp(timestamp: number, type: number = 0): string {
        const date = new Date(timestamp * 1000);
        const padZero = (num: number) => num < 10 ? '0' + num : num;
        const month = padZero(date.getMonth() + 1);
        const day = padZero(date.getDate());
        const year = date.getFullYear();

        const hours = padZero(date.getHours());
        const minutes = padZero(date.getMinutes());
        const seconds = padZero(date.getSeconds());
        if (type == 0) return `${day}/${month}/${year} ${hours}:${minutes}:${seconds}`;
        else return `${year}-${month}-${day}`;
    }


    // 计算当前时间到date的时间差，大于一天时显示多少天，小于一天时显示多少小时，小于一小时时显示多少分钟
    static transformDHMS(timestamp) {
        const now_time: number = Math.floor(Date.now() / 1000);
        const difference: number = timestamp - now_time;

        if (difference <= 0) {
            return -1;
        }

        let DHMS = {};
        DHMS["days"] = Math.floor(difference / (60 * 60 * 24));
        DHMS["hours"] = Math.floor((difference % (60 * 60 * 24)) / (60 * 60));
        DHMS["minutes"] = Math.floor((difference % (60 * 60)) / 60);
        DHMS["seconds"] = Math.floor((difference % (60 * 60)) / 60 / 60);
        return DHMS;
    }

    static formatSeconds(seconds: number): any {
        const days = Math.floor(seconds / (24 * 3600));
        seconds %= (24 * 3600);
        const hours = Math.floor(seconds / 3600);
        seconds %= 3600;
        const minutes = Math.floor(seconds / 60);
        const secs = seconds % 60;

        let dv = {
            "days": days,
            "hours": hours,
            "minutes": minutes,
            "secs": secs,
            "string": `${days}D: ${hours}H: ${minutes}M: ${secs}S`
        };
        return dv;
    }

    static getCurTime() {
        let date = new Date(Date.now());
        let Year = date.getFullYear();
        let Month = date.getMonth() + 1 < 10 ? "0" + (date.getMonth() + 1) : date.getMonth() + 1;
        let Day = date.getDate() < 10 ? "0" + date.getDate() : date.getDate();
        let Hour = date.getHours() < 10 ? "0" + date.getHours() : date.getHours();
        let Minute = date.getMinutes() < 10 ? "0" + date.getMinutes() : date.getMinutes();
        let Seconds = date.getSeconds() < 10 ? "0" + date.getSeconds() : date.getSeconds();
        let GMT = "" + Year + Month + Day + Hour + Minute + Seconds;
        return GMT;
    }

