    //获取URL参数配置
    static URLParams: any = null;
    static queryURLParams() {
        if (tools.URLParams == null) {
            let search: string = location.search;
            search = search.slice(1);
            //channel=19&agentID=617&directUID=16033261
            if (search.indexOf("channel=") == -1 && search.indexOf("agentID=") == -1 && search.indexOf("&") == -1) {
                search = tools.base64decode(search);
                // (<any>window).Base64.decode(search);
            }
            //解析
            let obj: any = {};
            let arr = search.split("&");
            for (let i = 0; i < arr.length; i++) {
                let arrNew = arr[i].split("=");
                obj[arrNew[0]] = arrNew[1];
            }
            tools.URLParams = obj;
        }
        return tools.URLParams;
    }


    static isUniWebView() {
        function hasUniWebViewBridge(): boolean {
            const win = window as any;

            // iOS 常见的 messageHandlers
            if (win.webkit && win.webkit.messageHandlers && win.webkit.messageHandlers.uniWebView) {
                return true;
            }

            // Android 常见的 Unity.call
            if (typeof win.Unity === 'object' && typeof win.Unity.call === 'function') {
                return true;
            }

            // 其他可能的桥接对象
            if (typeof win.uniwebview === 'object') {
                return true;
            }

            return false;
        }

        function isAlertOverridden(): boolean {
            const nativeAlert = window.alert.toString();
            return !nativeAlert.includes('[native code]');
        }

        function isConsoleLogOverridden(): boolean {
            const nativeLog = window.console.log.toString();
            return !nativeLog.includes('[native code]');
        }

        function detectUniWebViewByAPIOverride(): boolean {
            return isAlertOverridden() || isConsoleLogOverridden();
        }

        function isUniWebViewByUA(): boolean {
            const ua = window.navigator.userAgent.toLowerCase();
            return ua.includes('uniwebview') || ua.includes('wv') || ua.includes('webview');
        }

        common.ISUNIWEBVIEW = (hasUniWebViewBridge() || detectUniWebViewByAPIOverride() || isUniWebViewByUA())
    }

    static sendToUnity(action, data) {
        if (common.ISUNIWEBVIEW) {
            const query = new URLSearchParams(data).toString();
            location.href = `uniwebview://${action}?${query}`;
        } else {
            //ggLogger.warn('当前环境不支持 uniwebview 协议，跳转已取消');
        }
    }

    // 下载远程图片
    static downloadRemoteImageAndSave(url, userID, callback) {
        if (url == null || url == "") {
            return;
        }

        if (sys.os === sys.OS.ANDROID) {
            let dirpath = jsb.fileUtils.getWritablePath() + "avata/";
            let filepath = dirpath + userID + ".png";
            if (jsb.fileUtils.isFileExist(filepath)) {
                // 图片存在，直接加载
                this.loadImage(filepath, callback);
                return;
            }
            let self = this;
            var saveFile = function (data) {
                if (data) {
                    if (!jsb.fileUtils.isDirectoryExist(dirpath)) {
                        // 目录不存在，创建
                        jsb.fileUtils.createDirectory(dirpath);
                    }

                    if (jsb.fileUtils.writeDataToFile(new Uint8Array(data), filepath)) {
                        // 成功将下载下来的图片写入本地
                        self.loadImage(filepath, callback);
                    } else {
                        callback(null);
                    }
                } else {
                    callback(null);
                }
            };

            let xhr = new XMLHttpRequest();
            xhr.onreadystatechange = function () {
                if (xhr.readyState === 4) {
                    if (xhr.status === 200) {
                        saveFile(xhr.response);
                    } else {
                        saveFile(null);
                    }
                }
            }.bind(this);

            //responseType一定要在外面设置
            xhr.responseType = "arraybuffer";
            xhr.open("GET", url, true);
            xhr.send();
        }
    }


