import { assetManager, director, instantiate, isValid, Prefab, sys, tween, Widget } from "cc";
import { ggLogger } from "db://gg-hot-update/scripts/hotupdate/GGLogger";
import { i18n_t } from "../i18n/LanguageData";
import NoticeMsg from "../lobby/layoutLayer/Notice/NoticeMsg";
import { tools } from "../tools/tools";
import { LoadingLayer } from "./LoadingLayer";
import { MsgBox } from "./MsgBox";
import { MsgTips } from "./MsgTips";


export class ui {
    private static tipBoxPrefab = null;
    private static loadingLayerPrefab = null;
    private static msgTipsPrefab = null;
    private static NoticeTipsPrefab = null;
    constructor() {
        director.on("popTips", (msg) => {
            ui.createTips(i18n_t(msg));
        }, this);
    }

    static createTips(msgText: string, callback = null) {
        let bundle = assetManager.getBundle('Lobby');
        if (bundle) {
            bundle.load('res/prefab/tips', Prefab, (err, prefab) => {
                if (err) {
                    ggLogger.log('ui.createTips err = ', err);
                    return;
                }
                this.removeMsgTips();
                this.removeLoadingLayer();
                this.msgTipsPrefab = instantiate(prefab);
                tools.topLayer.addChild(this.msgTipsPrefab);
                this.msgTipsPrefab.getComponent(MsgTips).setMsg(msgText, callback);
            });
        }
    }

    static removeMsgTips() {
        if (this.msgTipsPrefab && this.msgTipsPrefab.isValid) {
            this.msgTipsPrefab.destroy();
            this.msgTipsPrefab = null;
        }
    }

    static createBox(msgText: string, clickCallback = null, btnType: number = 1, boxName?: string) {
        if (boxName == "gotoLoginScene") {
            let node = this.getBoxOfName("gotoLoginScene");
            if (node) {
                node.setSiblingIndex(node.parent.children.length - 1);
                return;
            }
        }
        let prefab = tools.topLayer.getChildByName("MsgBoxPrefab");
        let TipBoxPrefab = instantiate(prefab);
        TipBoxPrefab.active = false;

        tools.topLayer.addChild(TipBoxPrefab);
        TipBoxPrefab.name = boxName == null ? "MsgBox" : boxName;
        if (!isValid(TipBoxPrefab, true)) {
            return;
        }
        this.removeLoadingLayer();
        TipBoxPrefab.active = true;
        TipBoxPrefab.getComponent(MsgBox).setMsg(msgText, clickCallback, btnType);
        this.tipBoxPrefab = TipBoxPrefab;
    }

    /**大跑马灯进入 */
    static runBigIn() {
        director.emit("pmdBigInOut", false);
    }

    /**大跑马灯退出 */
    static runBigOut() {
        director.emit("pmdBigInOut", true);
    }

    static getBoxOfName(name: string) {
        let box = tools.topLayer.getChildByName(name);
        return box;
    }

    static createLoadingLayer(msgText: string = "", callback = null) {
        ui.removeLoadingLayer();
        if (ui.getBoxOfName("gotoLoginScene")) {
            return;
        }
        let node = tools.topLayer.getChildByName("LoadingLayer");
        node.getComponent(LoadingLayer).setMsg(msgText, callback);
    }

    static removeLoadingLayer() {
        let node = tools.topLayer.getChildByName("LoadingLayer");
        if (node) {
            node.getComponent(LoadingLayer).onDisable();
            node.active = false;
        }
    }

    static createNoticeTips(data, callback = null) {
        if (this.NoticeTipsPrefab && this.NoticeTipsPrefab.isValid) {
            return;
        }
        let bundle = assetManager.getBundle('Lobby');
        if (bundle) {
            bundle.load('res/prefab/Notice/NoticeMsg', Prefab, (err, prefab) => {
                if (err) {
                    ggLogger.log('ui.createNoticeTips err = ', err);
                    return;
                }
                let NoticeTipsPrefab = instantiate(prefab);
                tools.topLayer.addChild(NoticeTipsPrefab);
                NoticeTipsPrefab.getComponent(NoticeMsg).setData(data, callback);
                this.NoticeTipsPrefab = NoticeTipsPrefab;
            });
        }
    }

    static removeNoticeTipsLayer() {
        if (this.NoticeTipsPrefab && this.NoticeTipsPrefab.isValid) {
            this.NoticeTipsPrefab.destroy();
            this.NoticeTipsPrefab = null;
        }
    }

    static getCloseUITip(node) {
        let bundle = assetManager.getBundle('Lobby');
        if (bundle) {
            bundle.load('res/prefab/CloseUITip/CloseUITip', Prefab, (err, prefab) => {
                if (node != null && isValid(node, true)) {
                    if (err) {
                        ggLogger.log('ui.getCloseUITip err = ', err);
                        return;
                    }
                    let gettingLayerPrefab = instantiate(prefab);
                    node.addChild(gettingLayerPrefab);
                }
            });
        }
    }

    static isShowNetworkError: boolean = false;
    static showNetworkError() {
        if (ui.getBoxOfName("gotoLoginScene")) {
            return;
        }
        if (ui.isShowNetworkError) {
            return;
        }
        ui.isShowNetworkError = true;
        ui.createBox(i18n_t("dycLan.networkError"), (code) => {
            director.emit("networkError");
        }, 1, "gotoLoginScene");
    }

    /**改变声场景*/
    static changeScene(bundleName, sceneName, callback?) {
        // ggLogger.log("changeScene: " + bundleName + "  " + sceneName);
        const currentSceneName = director.getScene().name;
        if (sys.isBrowser && sceneName == currentSceneName) {
            (<any>window).location.reload();
            return;
        }
        this.gotoChangeScene(bundleName, sceneName, () => {
            if (bundleName == "Lobby" && (sceneName == "LobbyScene" || sceneName == "LoginScene")) {
                director.emit("changeScene", "V");
            }
            callback && callback();
        });
    }

    static backCurScene() {
        const currentSceneName = director.getScene().name;
        return currentSceneName;
    }

    /**获取当前场景中的 LoadingLayer 节点并设置消息*/
    static gotoChangeScene(bundleName: string, sceneName: string, callback?: Function) {
        // 获取当前场景名称
        const currentSceneName = director.getScene().name;
        if (currentSceneName === sceneName) {
            if (sceneName == "LoginScene") {
                director.emit("userkuan");
            }
            ggLogger.log(`当前已在场景 ${sceneName} 中，无需切换。`);
            return;
        }

        // 获取指定的资源包
        const bundle = assetManager.getBundle(bundleName);
        if (bundle) {
            // 加载目标场景
            bundle.loadScene(sceneName, (err, sceneAsset) => {
                if (err) {
                    ggLogger.error(`加载场景 ${sceneName} 时出错：`, err);
                    return;
                }
                this.jumpChangeScene();
                director.runScene(sceneAsset, () => {
                    if (callback) callback();
                });
            });
        } else {
            ggLogger.error(`未找到名为 ${bundleName} 的资源包。`);
        }
    }
    // 延迟设置屏幕方向，避免立即切换造成闪烁
    static jumpChangeScene(time = 0.15) {
        if (tools.topLayer) {
            let hMask = tools.topLayer.getChildByName("hMask");
            if (hMask) {
                hMask.active = true;
                hMask.opacity = 255;
                hMask.getComponent(Widget).updateAlignment();
                tween(hMask)
                    .delay(time)
                    .to(0.3, { opacity: 0 })
                    .call(() => {
                        hMask.active = false;
                    })
                    .start();
            }
        }
    }
}