import { AssetManager, assetManager, AudioClip, director, EventTouch, instantiate, Node, Prefab, view } from "cc";
import { ggLogger } from "db://gg-hot-update/scripts/hotupdate/GGLogger";
import { common } from "../common/common";
import { config } from "../common/config";
import { GameManager } from "../data/GameManager";
import { i18n_t } from "../i18n/LanguageData";
import { LanguageMerger } from "../i18n/LanguageMerger";
import { DepositLayer } from "../lobby/layoutLayer/Deposit/DepositLayer";
import { Market } from "../market/Market";
import { tools } from "../tools/tools";
import { BaseUI } from "../ui/BaseUI";
import { ui } from "../ui/ui";

/**游戏ui界面基类 */
export abstract class GameView extends BaseUI {
    protected abstract gameLogic;
    protected uiInfo = null;
    public _areaNoteList = {};
    protected gamePath: string = "Lobby";
    protected gameBundle: AssetManager.Bundle = null;
    protected _bInBackground = false;
    public isInGame: boolean = true;//表示在游戏中
    public languageMerger: LanguageMerger = null; // 语言合并器
    self = this;
    init(uiInfo) {
        if (uiInfo.noteInfo) {
            for (let i = 1; i <= uiInfo.noteInfo.areaCount; i++) {
                this._areaNoteList[i] = [];
            }
        }
        this.uiInfo = uiInfo;
        if (uiInfo.gamePath) {
            this.gamePath = uiInfo.gamePath;
            this.gameBundle = assetManager.getBundle(this.gamePath);
        }

        this.isInGame = true;
        tools.GAME_TYPE = common.GAME_TYPE.GAME;
    }

    start() {
        super.start();
    }

    audioList: any[] = [];
    asBundle: AssetManager.Bundle = null;
    update(dt: number): void {
        if (this.asBundle != null && this.audioList && this.audioList.length > 0) {
            let item = this.audioList.shift();
            if (item && item.path) {
                this.asBundle.load(item.path, AudioClip, (err, clip) => {
                    if (err) {
                        ggLogger.warn("asBundle.load: " + item.path + " | " + err);
                    }
                });
            }
        }
    }

    updateConScale(bg: Node, baseWidth: number = 375, baseHeight: number = 525) {
        const visibleSize = view.getVisibleSize();
        const scaleX = visibleSize.width / baseWidth;
        const scaleY = visibleSize.height / baseHeight;
        const scale = Math.min(scaleX, scaleY);
        bg.setScale(scale, scale, 1);
    }

    onLoad() {
        super.onLoad();
        director.on("onGameHideEvent", this.onGameHideEvent, this);
        director.on("onGameShowEvent", this.onGameShowEvent, this);
        director.on("userGoldChange", this.onGoldChanged, this);
        director.on("userFishInfoChange", this.onEnterFishNewUser, this);
        director.on("leaveRoom", this.onLeaveRoom, this);
        director.on("leaveDesk", this.onLeaveDesk, this);
        director.on("sendNetClose", this.onNetClose, this);
        director.on("userUIChange", this.onUserUIChange, this);
        let gameID = GameManager.getInstance().getGameID();
        let data = config.ClientGameRegistList[gameID];
        let bundleName = data.gamePath;
        assetManager.loadBundle(bundleName, (err, bundle) => {
        if (err) {
            ggLogger.log('加载loadLobbyBundle资源失败:', err);
        } else {
            this.asBundle = assetManager.getBundle(bundleName);
            this.audioList = [];
            this.asBundle.getDirWithPath("res/audio", AudioClip, this.audioList);
        }
        });
    }

    onGameHideEvent() {
        this._bInBackground = true;
    }

    onGameShowEvent() {
        this._bInBackground = false;
        this.gameLogic.onGameShow();
    }

    onExitBtnClick(event: EventTouch, csStr: string) {
        //this.playBtnClickEffect();
        this.gameLogic.sendUserUp();
    }

    backLobby(result, msg = "") {
        //退出时清理
        this.unscheduleAllCallbacks();
        this.gameLogic.roomFrame.clear();
        ui.changeScene("Lobby", "LobbyScene", () => {
            if ("" != msg) {
                ui.createBox(msg)
            }
        });
    }

    backLogin(result, msg = "") {
        //退出时清理
        if (common.ISH5DIRECT) {
            tools.sendToUnity("ExitGame", {});
        } else {
            this.unscheduleAllCallbacks();
            this.gameLogic.roomFrame.clear();
            ui.changeScene("Lobby", "LoginScene", () => {
                if ("" != msg) {
                    ui.createBox(msg);
                }
            });
        }
    }

    onDestroy() {
        this.unscheduleAllCallbacks();
        director.off("onGameHideEvent", this.onGameHideEvent, this);
        director.off("onGameShowEvent", this.onGameShowEvent, this);
        director.off("userGoldChange", this.onGoldChanged, this);
        director.off("leaveRoom", this.onLeaveRoom, this);
        director.off("leaveDesk", this.onLeaveDesk, this);
        director.off("sendNetClose", this.onNetClose, this);
        director.off("userUIChange", this.onUserUIChange, this);
        this.gameLogic.removeGameMsgCallback();
        super.onDestroy();

        this.asBundle.releaseAll();
        assetManager.removeBundle(this.asBundle);
        this.onExit();
    }
    onGoldChanged(userGold) { };
    onUserUIChange() { };
    onEnterFishNewUser(info) { };
    onExit(): void { }
    onNetClose(): void { }
    onMsgNoBack() {
        this.onMsgTs(i18n_t("dycLan.betNoBack"));
    }

    onTips(msg: string) {
        ui.createTips(msg);
    }

    onBox(msg: string, backFun: Function = null) {
        ui.createBox(msg, (code) => {
            backFun && backFun(code);
        }, 2);
    }

    onMoneyNotEnough() {
        ui.createBox(i18n_t("dycLan.moneyNoEnough"), (code) => {
            if (code == 2) {//2表示ok,1表示取消
                if (common.ISH5DIRECT) {
                    tools.sendToUnity("OpenShop", {});
                } else {
                    this.onBtnShopClick(null);
                }
            }
        }, 2);
    }

    onMsgTs(msg: string) {
        ui.createTips(msg);
    }

    onLeaveRoom() {
        ggLogger.log("游戏退出onLeaveRoom", this.isInGame);
        if (this.isInGame) {
            this.onExit();
            this.isInGame = false;
            if (common.ISH5DIRECT) {
                tools.sendToUnity("ExitGame", {});
            } else {
                this.backLobby(null);
            }
        }
    }

    onLeaveDesk(data) { }

    //加载预制体
    addLayer(name: string, parent, callback = null, bundleName: string = "Lobby") {
        try {
            if (!name || name === "" || !parent || !parent.isValid) {
                console.error("Invalid parameters for addLayer");
                return null;
            }

            const canvas = director.getScene()?.getChildByName("Canvas");
            if (canvas?.getChildByName(name)) {
                ggLogger.log("=======已经存在了==", name);
                return;
            }

            let bundle = assetManager.getBundle(bundleName);
            if (!bundle) {
                console.error("Bundle not found:", bundleName);
                return null;
            }

            let path = "res/prefab/" + name;
            let prefabAsset = bundle.get(name, Prefab);

            if (prefabAsset) {
                let layer = instantiate(prefabAsset);
                if (layer && layer.isValid) {
                    layer.name = name;
                    layer.parent = parent;
                    if (callback && typeof callback === 'function') {
                        callback(layer);
                    }
                }
            } else {
                bundle.load(path, Prefab, (err, prefab) => {
                    if (err) {
                        ggLogger.error("Gameview.addLayer err = ", err);
                        return;
                    }
                    if (prefab && prefab.isValid) {
                        let layer = instantiate(prefab);
                        if (layer && layer.isValid) {
                            layer.parent = parent;
                            if (callback && typeof callback === 'function') {
                                callback(layer);
                            }
                        }
                    }
                });
            }
        } catch (error) {
            console.error("Error in addLayer:", error);
        }
    }

    playBtnClickEffect(name: string = "button1", bundle: string = "Lobby") {
        super.playBtnClickEffect(name, bundle);
    }


    onBtnShopClick(e?: EventTouch) {
        try {
            this.playBtnClickEffect();

            const canvas = director.getScene()?.getChildByName("Canvas");
            if (!canvas) {
                console.error("Canvas not found in current scene");
                return;
            }

            const market = Market.getInstance();
            if (!market) {
                console.error("Market instance not available");
                return;
            }
            ui.jumpChangeScene();
            if ("H" === market.getOrientation()) {
                market.setOrientation("V");
                this.addLayer("Deposit/DepositLayer", canvas, (layer) => {
                    if (layer && layer.isValid) {
                        const depositComp = layer.getComponent(DepositLayer);
                        if (depositComp && depositComp.init) {
                            depositComp.init("H");
                        } else {
                            console.error("DepositLayer component or init method not found");
                        }
                    }
                });
            } else {
                this.addLayer("Deposit/DepositLayer", canvas, (layer) => {
                    if (layer && layer.isValid) {
                        const depositComp = layer.getComponent(DepositLayer);
                        if (depositComp && depositComp.init) {
                            depositComp.init();
                        } else {
                            console.error("DepositLayer component or init method not found");
                        }
                    }
                });
            }
        } catch (error) {
            console.error("Error in onBtnShopClick:", error);
        }
    }


}