import { Node,tween,UIOpacity,_decorator, Animation, BoxCollider2D, Collider2D, Component, Contact2DType, IPhysics2DContact, Label, RigidBody2D, size, Sprite, UITransform, Vec3 } from "cc";
import { PlinkoCirclePlayer } from "./PlinkoCirclePlayer";
import { GameTempCore } from "./PlinkoCore";
import { PoolType } from "./PlinkoPoolManager";

const { ccclass, property } = _decorator;

@ccclass('PlinkoRewardItem')
export class PlinkoRewardItem extends Component {

    //0-3
    public rowType: number = 0;
    //spriteFrame id [0-7]
    public spriteFrameID: number = 0;
    public multiple: number = 0;
    public index:number = 0;

    private rigidBody: RigidBody2D | null = null;

    onEnable() {
        this.hideAllParticleNode();
        this.initRigidBody(true);
    }

    onDisable() {
        this.hideAllParticleNode();
        this.initRigidBody(false);
    }

    //  设置倍率
    setMultiple(multiple: number) {
        this.multiple = multiple;
    }

    public setIndex(ind:number)
    {
        this.index = ind;
    }
    // 设置大小
    setItemWith(rowType: number) {
        this.rowType = rowType;
        let itemWith = GameTempCore.slotConfig.rewardWiths[this.rowType];
        let itemHeight = GameTempCore.slotConfig.rewardHeights[this.rowType];
        this.node.getComponent(UITransform).width = itemWith;

        let LabelNode = this.node.getChildByName("Label");
        LabelNode.getComponent(Label).fontSize = GameTempCore.slotConfig.rewardLabelFont[this.rowType];

        let colliders = this.node.getComponents(Collider2D);
        for (let collider of colliders) {
            if (collider instanceof BoxCollider2D) {
                collider.size = size(itemWith - 5, itemHeight - 5);   // 宽高
                collider.apply();
            }
        }

        let orginaleWith = GameTempCore.slotConfig.rewardWiths[0];
        let scale = itemWith / orginaleWith;
        this.setAllParticleNodeSize(scale);
    }

    // 设置颜色
    setSpriteFrame(spriteFrameID: number) {
        this.spriteFrameID = spriteFrameID;
        //let sprite = this.node.getComponent(Sprite);
        //sprite.spriteFrame = GameTempCore.slotMgr.GameMainCmp.itemSpritFrameList[this.spriteFrameID];
    }

    initRigidBody(enable: boolean) {
        this.rigidBody = this.node.getComponent(RigidBody2D);
        if (this.rigidBody) {
            this.rigidBody.enabled = enable;
        }
        let colliders = this.node.getComponents(Collider2D);
        for (let collider of colliders) {
            collider.enabled = enable;
            /*if (!enable) {
                collider.off(Contact2DType.BEGIN_CONTACT, this.onBeginContact, this);
            } else {
                collider.on(Contact2DType.BEGIN_CONTACT, this.onBeginContact, this);
            }*/
        }
    }

    //特效节点隐藏
    hideAllParticleNode() {
        let children = this.node.children;
        if (children && children.length > 0) {
            children.forEach((child) => {
                if (child.name.includes("down")) {
                    child.active = false;
                }
            })
        }
    }

    // 特效进行缩放
    setAllParticleNodeSize(scale: number) {
        let children = this.node.children;
        if (children && children.length > 0) {
            children.forEach((child) => {
                if (child.name.includes("down")) {
                    child.scale = new Vec3(scale, scale, scale);
                }
            })
        }
    }

    //碰撞检测
    public onBeginContact(other: Node) {
        let animation = this.node.getComponent(Animation);
        GameTempCore.playAnimationFromStart(animation, "reward_start");

        let otherColliderName = other.name;

        if (otherColliderName.includes("PlinkoCirclePlayer")) {

            let cmp = other.getComponent(PlinkoCirclePlayer)
            if (cmp) {
                if (this.index != cmp.targetId) {
                    console.log("appear error id = ", cmp.targetId, "reward tag = ", this.index)
                    // ui.createTips(`appear error id ${cmp.targetId},reward tag =${tag}`);
                }
                let data = {
                    historyData: cmp.getTargetServerData(),
                }
                GameTempCore.slotMgr.gm.emit(GameTempCore.slotConfig.eventNames.updateHistory, data);

                this.hideAllParticleNode();
                let rewardParticleName = "light";
                let rewardParticle = this.node.getChildByName(rewardParticleName);
                rewardParticle.active = true;
                let bgOpacity = rewardParticle.getComponent(UIOpacity)
                bgOpacity.opacity = 255;
                tween(bgOpacity).delay(0.5).to(0.3, { opacity: 0 }).start();

                GameTempCore.slotMgr.gm.emit(GameTempCore.slotConfig.eventNames.highMultipleWin, this.multiple);
            }
        }

    }
}