import { _decorator, Component, EventTouch, Node } from 'cc';
import UIButtonBase from '../../Lobby/src/component/UIButtonBase';
import { GameTempCore } from './PlinkoCore';

const { ccclass, property } = _decorator;

@ccclass('GameTempRule')
export class GameTempRule extends Component {

    protected onLoad(): void {
        this.getNodes();
    }

    private getNodes() {
        if (!this.node || !this.node.isValid) return;

    }

    protected onEnable(): void {
        if (!this.node || !this.node.isValid) return;
        this.node.on(Node.EventType.TOUCH_END, this.onButtonClick, this);

    }

    protected onDisable(): void {
        this.node.off(Node.EventType.TOUCH_END, this.onButtonClick);
    }

    protected onButtonClick(event: EventTouch) {
        let target: Node = event.target;
        let button = target.getComponent(UIButtonBase);
        if (!button || !button.canTouch) return;
        switch (target.name) {
            case "button_back":
                this.onClickCloseView();
                break;
            default:
                break;
        }
    };

    onClickCloseView() {
        GameTempCore.slotMgr.GameMainCmp.hidRuleLayer();
    }
}
