/**
 * 查找子节点以及子节点组件
 * @param rootNode 根节点
 * @param targetPath 目标节点得路径（xxx/yyy/zzz）
 * @param type 查找得组件类型
 */
export function findChild<T extends Component>(rootNode: Node, targetPath: string, type?: { prototype: T }): any {
    let targetComponent: T = null;
    if (rootNode == null) {
        ggLogger.log(">>>>参数不能为空");
        return;
    }

    let targetNode: Node = null;

    let nextRoot = rootNode;
    let paths: string[] = [];
    if (targetPath != null && targetPath != "") {
        paths = targetPath.split("/");
    }

    for (let index = 0; index < paths.length; index++) {
        const path = paths[index];
        if (nextRoot == null) {
            ggLogger.log(rootNode.name, "节点下没有该节点：", path);
            break;
        }
        nextRoot = nextRoot.getChildByName(path);
    }
    targetNode = nextRoot;
    if (targetNode == null) {
        ggLogger.log(rootNode.name, "节点下没有该节点：", targetPath);

    }
    if (targetNode != null) {
        if (type != null) {
            // 确保 type 是组件类的构造函数
            targetComponent = targetNode.getComponent(type as any);
            if (targetComponent == null) {
                ggLogger.log(rootNode.name, "/", targetPath, ">>>>>没有获取到组件", type)
            }
            return targetComponent;
        } else {
            return targetNode;
        }
    } else {
        ggLogger.log(rootNode.name, "节点下没有该节点：", targetPath);
    }
}



//点击阻止，delay时间单位为秒
export function clickblock(delay: number = 0.5) {
    return function (target, methodName: string, descriptor: PropertyDescriptor) {
        var key = `${methodName}__clickBlock`;
        var fn = descriptor.value;
        fn[key] = false;
        descriptor.value = function (...args: any[]) {
            if (fn[key]) {
                ggLogger.log(`[装饰器][ClickBlock]阻止了${methodName}`);
                return;
            }
            fn[key] = true;
            setTimeout(() => {
                fn[key] = false;
            }, delay * 1000);
            fn.apply(this, args);
        };
    }
}

