    /** 监听一次性事件 */
    public once(type: string, callback: Function, target: any) {
        if (!this.eventMap[type]) {
            this.eventMap[type] = [];
        }
        const exists = this.eventMap[type].some(
            listener => listener.callback === callback && listener.target === target
        );
        if (exists) return;
        this.eventMap[type].push({ callback, target, once: true });
    }

    public on(type: any, callback: any, target: any) {
        if (this.eventMap[type] === undefined) {
            this.eventMap[type] = [];
        }
        this.eventMap[type].push({ callback: callback, target: target });
    }

    public emit(type: any, parameter = null) {
        var array = this.eventMap[type];
        if (array === undefined) return;

        for (var i = 0; i < array.length; i++) {
            var element = array[i];
            if (element) {
                element.target.isValid && element.target.node.active && element.callback.call(element.target, parameter);
            } else {
                array.splice(i, 1);
            }
        }
    }

    public off(type: any, context) {
        let observers = this.eventMap[type];
        if (!observers) { return; }
        let length = observers.length;
        for (let i = 0; i < length; i++) {
            const observer = observers[i];
            if (observer.target == context) {
                observers.splice(i, 1);
                break;
            }
        }
        if (observers.length == 0) {
            delete this.eventMap[type];
        }
    }

