    /**
      * 检查并设置Spine动画，避免设置不存在的动画导致错误
      * @param skeleton Spine组件
      * @param animName 动画名称
      * @param loop 是否循环
      * @returns 是否设置成功
      */
    public setSpineAnimationWithCheck(skeleton: sp.Skeleton, animName: string, loop: boolean): boolean {
        try {
            if (skeleton && skeleton.findAnimation && typeof skeleton.findAnimation === 'function') {
                const animation = skeleton.findAnimation(animName);
                if (animation) {
                    skeleton.setAnimation(0, animName, loop);
                    return true;
                } else {
                    return false;
                }
            }
            skeleton.setAnimation(0, animName, loop);
            return true;
        } catch (error) {
            return false;
        }
    }

    /**播放Spine动画 */
    public playSpine(spine: sp.Skeleton, anim: string, loop: boolean, complete?: () => void, speed: number = 1) {
        if (!spine || !anim) return;
        spine.setCompleteListener(null);
        spine.timeScale = speed;
        spine.setAnimation(0, anim, loop);
        if (complete) {
            spine.setCompleteListener(() => {
                spine.setCompleteListener(null);
                complete();
            });
        }
    }
    /**播放粒子动画 */
    public playParticleSystemSpeed(fxParent: Node, speed: number = 1) {
        if (!fxParent) return;
        let upts = fxParent.getComponent(ParticleSystem);
        if (upts) {
            upts.simulationSpeed = speed;
            fxParent.active = true;
            if (fxParent.active) {
                upts.stop();
                upts.clear();
                upts.play();
            }
        }
        fxParent.children.forEach(child => {
            let ps = child.getComponent(ParticleSystem);
            if (ps) {
                child.active = true;
                ps.simulationSpeed = speed;
                if (child.active) {
                    ps.stop();
                    ps.clear();
                    ps.play();
                }
            }
        })
    }

    /**播放粒子动画 */
    public stopParticleSystemSpeed(fxParent: Node, speed: number = 1) {
        if (!fxParent) return;
        let upts = fxParent.getComponent(ParticleSystem);
        if (upts) {
            upts.simulationSpeed = speed;
            if (fxParent.active) {
                upts.stop();
                upts.clear();
            }
        }
        fxParent.children.forEach(child => {
            let ps = child.getComponent(ParticleSystem);
            if (ps) {
                ps.simulationSpeed = speed;
                if (child.active) {
                    ps.stop();
                    ps.clear();
                }
            }
        })
    }

    /**播放时间轴动画 */
    public async playAnimationToIn(animation: Animation, name?: string, complete?: Function, speed: number = 1) {
        if (!animation) return;
        const state = animation.getState(name);
        if (state) {
            state.speed = speed;
            state.stop();
            state.time = 0;
            state.sample();
        }
        animation.once(Animation.EventType.FINISHED, () => {
            complete && complete();
        });

        if (name)
            animation.play(name);
        else
            animation.play();
    }



