    /**
     * 
     * 数字增长动效
     * @param label 组件
     * @param curnum  增加的值
     * @param time  动效时间
     * @param length  保留小数后几位
     * @param fun  回调
     * @returns 
     */
    public NumberAnim(label: Label, curnum, time: number = 1, length: number = 2, fun = null, handie = null) {
        return new Promise((resolve, reject) => {
            let obj: any = {}
            obj.num = 0
            obj.vule = Number(label.string) | 0
            let istofixed = true
            let s = curnum.toString()
            let rs = s.indexOf('.');
            if (rs == -1) {
                istofixed = false
            } else {
                istofixed = true
            }
            this.numbertween = tween(obj)
                .to(time, { num: Number(curnum) }, {
                    progress: (start, end, current, t) => {
                        let vule = 0
                        if (istofixed) {
                            vule = (obj.vule + (start + (end - start) * t)).toFixed(length)
                        } else {
                            vule = Math.floor(obj.vule + (start + (end - start) * t))
                        }
                        if (label) {
                            label.string = vule + ""
                        }
                        fun && fun(Number((start + (end - start) * t)).toFixed(length))
                        return current;
                    }
                })
                .call(() => {
                    resolve(0)
                })
                .start()

            handie && handie(this.numbertween)
        })
    }

