    /**得到两点距离 */
    public distance(vec1: Vec2, vec2: Vec2): number {
        let pos = v2(vec1.x - vec2.x, vec1.y - vec2.y);
        return Math.round(Math.sqrt(pos.x * pos.x + pos.y * pos.y))
    }

    /**
     * 去重
     * @param arr 数组
     */
    public onDuplicate(arr) {
        let newarr = []
        for (let k = 0; k < arr.length; k++) {
            if (newarr.indexOf(arr[k]) == -1) {
                newarr.push(arr[k])
            }
        }
        return newarr
    }

    /**
    * 保留小数点几位数, 自动补零, 四舍五入
    * @param num: 数值
    * @param digit: 小数点后位数
    * @returns string
    */
    public myFixed(num: number, digit: number) {
        let f = num;
        let s = f.toString();
        let rs = s.indexOf('.');

        if (digit != null) {
            if (rs < 0) {
                rs = s.length;
                s += '.';
            }
            let arr = s.split(".")
            if (digit == 0) {
                s = arr[0];
            } else if (digit < arr[1].length) {
                let c = arr[0] + "." + arr[1].substring(0, digit);
                s = c
            } else {
                while (s.length <= rs + digit) {
                    s += '0';
                }
            }
        } else {
            return s;
        }
        return s;

    }

