    public findClosestValue(input: number, arr: Array<number> = [1, 5, 10, 50, 100]): number {
        const target = input / 10000;
        let closest = arr[0];
        let minDiff = Math.abs(target - closest);

        for (let i = 1; i < arr.length; i++) {
            const diff = Math.abs(target - arr[i]);
            if (diff < minDiff) {
                minDiff = diff;
                closest = arr[i];
            }
        }
        let goID = 0
        arr.forEach((nk, i) => {
            if (closest == nk) goID = i;
        })
        return goID + 1;
    }



