import { _decorator, EventTouch, Label, Tween, Vec3 } from "cc";
import { tools } from "../../../tools/tools";
import { Popup } from "../../../ui/Popup";

const { ccclass, property } = _decorator;

@ccclass
export default class NotceLayer extends Popup {
    @property(Label)
    private Label_Text: Label = null;

    private _callback: Function = null;
    setData(str, callback: Function = null) {
        this.Label_Text.string = `₦${tools.gradingNumber3(str)}`;
        this._callback = callback;
    }

    onCloseBtnClickX(event: EventTouch) {
        event.propagationStopped = true;
        this.isEnd = true;
        if (this.msgBg) {
            new Tween(this.msgBg)
                .to(0.3, { scale: new Vec3(0, 0, 0) })
                .call(() => {
                    this._callback && this._callback();
                    this.node.destroy();
                })
                .start();
        }
    }
}
