    private onRowSelected(toggleIndex: number) {
        const newRow = GameTempCore.slotConfig.rowList[toggleIndex - 1];
        // 行号没变，什么都不做
        if (this.slotMgr.gameRow === newRow) return;
        this.slotMgr.setGameRow(newRow);
        this.updateRowToggleUI(toggleIndex);
        this.PlayEffect_clickButton();
    }
    private updateRowToggleUI(selectIndex: number) {
        this.rowToggles.forEach(toggle => {
            const idx = Number(toggle.node.name.replace(/\D/g, ''));
            const isChecked = idx === selectIndex;
            toggle.isChecked = isChecked;
            const labelNode = toggle.node.getChildByName("Label");
            if (labelNode) {
                this.uiComp.setGrayNode(labelNode, !isChecked);
            }
        });
    }
    setGameRow(toggleIdx: number) {
        if (!this.isGameValid()) return;
        const toggles = this.rowToggles;
        if (!toggles.length) return;
        let targetToggle: Toggle = null;
        for (let i = 0; i < toggles.length; i++) {
            const toggle = toggles[i];
            const idx = Number(toggle.node.name.replace(/\D/g, ''));
            const shouldCheck = idx === toggleIdx;
            // 状态没变就不 set（超级关键）
            if (toggle.isChecked !== shouldCheck) {
                toggle.isChecked = shouldCheck;
            }
            const labelNode = toggle.node.getChildByName("Label");
            if (labelNode) {
                this.uiComp.setGrayNode(labelNode, !shouldCheck);
            }
            if (shouldCheck) {
                targetToggle = toggle;
            }
        }
        // 行号真的变化才通知 slotMgr
        const newRow = GameTempCore.slotConfig.rowList[toggleIdx - 1];
        if (this.slotMgr.gameRow !== newRow) {
            ggLogger.log("setGameRow:", newRow);
            this.slotMgr.setGameRow(newRow);
        }
    }
