    private pileGeneratedRow = new Set<string>();
    public async setBallView() {
        if (!this.isGameValid()) return;

        const ballView = find("ballView", this.uiComp.node);
        const targetRowName = `row${this.slotMgr.gameRow}`;

        let targetPileGroup: Node | null = null;

        for (const row of ballView.children) {
            const isTarget = row.name === targetRowName;
            row.active = isTarget;

            const pileGroup = row.getChildByName("PileGroup");
            if (!pileGroup) continue;

            pileGroup.active = isTarget;
            if (isTarget) targetPileGroup = pileGroup;
        }

        if (!targetPileGroup) return;

        this.updateBallViewMultiple();

        if (!this.pileGeneratedRow.has(targetRowName)) {
            await this.generatePileAsync(targetPileGroup);
            this.pileGeneratedRow.add(targetRowName);
        } else {
            //  动画保持
            targetPileGroup.setScale(0.9, 0.9, 0.9);
            tween(targetPileGroup)
                .to(0.15, { scale: Vec3.ONE }, { easing: 'backOut' })
                .start();
        }
    }
    private async generatePileAsync(pileGroup: Node) {
        //const BATCH = 2; // 每帧最多生成 6 个
        let batchCount = 0;

        for (let colIndex = 0; colIndex < pileGroup.children.length; colIndex++) {
            let col = pileGroup.children[colIndex];
            const count = Number(col.name);
            for (let i = 0; i < col.children.length; i++) {
                let pile = col.children[i];
                let cmp = pile.getComponent(PlinkoPile);
                if (!cmp) cmp = pile.addComponent(PlinkoPile);

                // 初始化但不启物理
                cmp.initPile(this.slotMgr.gameRow,colIndex,i);
                cmp.enablePilePhysics(true);

                /*batchCount++;
                if (batchCount >= BATCH) {
                    batchCount = 0;
                    await GameTempCore.sleep(0);
                }*/
            }
        }
        //  所有生成完成后，再统一开物理
         pileGroup.children.forEach(col => {
             col.children.forEach(pile => {
                 pile.getComponent(PlinkoPile)?.enablePilePhysics(true);
             });
        });
    }

