    public showHistoryView() {
        return;
        if (!this.isGameValid()) return;

        const historyView = find("historyView", this.uiComp.node);
        const layoutNode = historyView.getChildByName("layout");
        const children = layoutNode.children;
        children.forEach(child => {
            this.uiComp.stopTweenByNode(child);
            child.scale = new Vec3(1, 1, 1);
        })

        const historyData = this.slotMgr.historyData;
        const length = historyData.length;

        // 容器显隐
        historyView.active = length > 0;

        // 没数据 -> 清空显示
        if (length <= 0) {
            children.forEach(child => child.active = false);
            return;
        }

        const spriteFrameList = GameTempCore.slotConfig.rewardItemTable[`${this.slotMgr.gameRow}`];
        // ===== 计算当前要显示的数据索引 =====
        const dataIndex = Math.min(length, this.slotMgr.historyMax) - 1;
        const data = historyData[dataIndex];

        // ===== 计算要使用的 UI Item =====
        const childIndex = length < this.slotMgr.historyMax ? this.slotMgr.historyMax - 1 : dataIndex;
        const child = children[childIndex];

        // ===== 渲染 =====
        this.renderHistoryItem(child, data, spriteFrameList);

        layoutNode.getComponent(Layout)?.updateLayout();
    }

    private renderHistoryItem(child: Node, data: any, spriteFrameList: number[]) {
        const scale1 = child.active ? 1 : 0;
        const scale2 = child.active ? 0 : 1;

        child.scale = new Vec3(scale1, scale1, scale1)
        child.active = true;

        // 停掉旧动画
        this.uiComp.stopTweenByNode(child);
        child.setSiblingIndex(0);
        // 入场动画
        tween(child)
            // .to(
            //     0.05,
            //     { scale: new Vec3(scale2, scale2, scale2) },
            //     { easing: 'quadOut' }
            // )
            // .delay(0.05)
            // .call(() => {
            //     child.setSiblingIndex(0);
            // })
            // 慢慢启动 → 加速到略大
            .to(
                0.05,
                { scale: new Vec3(1.2, 1.2, 1.2) },
                { easing: 'quadIn' }           // 慢 → 快
            )
            // 回弹缩回
            .to(
                0.05,
                { scale: new Vec3(1, 1, 1) },
                { easing: 'quadOut' }
            )
            .start();

        // ===== 取数据 =====
        const score = data.CommonAwardScore ?? 0;
        const mulInfo = data.Mul;
        const multipleIndex = mulInfo.Index - 1;
        // const multiple = this.slotMgr.formatValue(mulInfo.Value);
        let multipleTable = GameTempCore.slotConfig.multipleTable[`${this.slotMgr.gameRow}`][`${this.slotMgr.difficultLevel}`];
        const multiple = this.slotMgr.formatValue(multipleTable[multipleIndex]);

        // ===== 刷文字 =====
        const winMoneyLabel = child.getChildByName("winMoney")?.getComponent(Label);
        const multipleLabel = child.getChildByName("multiple")?.getComponent(Label);
        winMoneyLabel && (winMoneyLabel.string = this.slotMgr.setMoneyFormat(score));
        multipleLabel && (multipleLabel.string = `${multiple}x`);

        // ===== 刷图片 =====
        const sprite = child.getComponent(Sprite);
        const frameIndex = spriteFrameList[multipleIndex];
        //const spriteFrame = GameTempCore.slotMgr.GameMainCmp.itemSpritFrameList[frameIndex];
        //if (sprite && spriteFrame) {
            //sprite.spriteFrame = spriteFrame;
        //}
    }
