    //掉落下面的倍数音效 
    async PlayerEffect_dropToMultipleBoard(index: number) {
        if (index<0 || index>10) return;
        let name = GameTempCore.slotConfig.soundEffectTable[index];
        let volume = GameTempCore.slotConfig.volume[index];
        if (this.playSoundEffect) {
            this.slotMgr.playEffect(`plinko_${name}`, false, volume);
            this.playSoundEffect = false;
            if (index>3 && index<7) {
                await GameTempCore.sleep(0.5);
            } else {
                await GameTempCore.sleep(1);
            }
            this.lastWinSoundName = name;
            this.playSoundEffect = true;
        }
    }
