/*

描述（Describe）: 定时器管理类
*/
import HashMap from "./HashMap";
import { Singleton } from "./Singleton";

enum TIME_DESTORY {
    DESTORY = 0,
    ALWAY = 1,  //一直执行
    COUNT = 2,  //执行指定的次数
};

class TimeCallBack {
    private _type: TIME_DESTORY;
    private _key: number = 0;
    private _callBack: Function;
    private _args: any;
    private _speed: number;
    private _length: number;
    private _beginTime: number;
    private _endTime: number;
    private _count: number;
    private count: number;
    constructor(k: number, length: number, speed: number, callback: Function, args: any, td: TIME_DESTORY, count: number = 0) {
        this._type = td;
        this._key = k;
        this._callBack = callback;
        this._args = args;
        this._speed = speed;
        if (this._speed <= 0) this._speed = 1;
        this._length = (length / this._speed) * 1000;
        this._beginTime = (new Date()).getTime();
        this._endTime = this._beginTime + this._length;
        this._count = 0;
        this.count = count;
    }

    get speed() {
        return this._speed;
    }

    set speed(value) {
        let old = this._speed;
        this._speed = value;
        let scale = this._speed / old;
        let surplus1 = this.surplusTime;
        let surplus2 = surplus1 / scale;
        this._endTime += (surplus2 - surplus1);
    }

    //剩余时间（毫秒）
    get surplusTime() {
        return (this._endTime - (new Date()).getTime());
    }

    update() {
        if (this.surplusTime <= 0) {
            if (this._callBack != null) {
                ++this._count;
                this._callBack(this._args);
            }

            if (this._type == TIME_DESTORY.ALWAY) {
                this._beginTime = (new Date()).getTime();
                this._endTime = this._beginTime + this._length;
                return false;
            }
            else if (this._type == TIME_DESTORY.COUNT && this._count < this.count) {// this._args[0]) {
                this._beginTime = (new Date()).getTime();
                this._endTime = this._beginTime + this._length;
                return false;
            }
            return true;
        }
        return false;
    }
}

export default class TimerManager extends Singleton<TimerManager>() {
    private _timeCallBack: HashMap<number, TimeCallBack> = new HashMap();	//计时器数组
    private _freeTimeKey: number[] = [];			//空闲的计时器ID
    private _delCallBack: number[] = [];			//要删除的计时器数组 下一帧统一删除
    private _validKey = 100;
    private getFreeKey() {
        return this._validKey++;
    }

    /**
     * 执行一次
     * @param length 时间
     * @param callBack  回调
     * @param args 参数
     * @returns 
     */
    public addTimeCallBack(length: number, callBack: Function, args?: any) {
        let Key = this.getFreeKey();
        this._timeCallBack.add(Key, new TimeCallBack(Key, length, 1, callBack, args, TIME_DESTORY.DESTORY));
        return Key;
    }

    /**
     * 一直执行
     * @param length  时间
     * @param callBack  回调
     * @param args 参数
     * @returns 
     */
    public addAlwayTimeCallBack(length: number, callBack: Function, args?: any) {
        let Key = this.getFreeKey();
        this._timeCallBack.add(Key, new TimeCallBack(Key, length, 1, callBack, args, TIME_DESTORY.ALWAY));
        return Key;
    }

    /**
     * 执行指定的次数
    * @param length 时间
     * @param callBack  回调
     * @param args 参数
    * @param count 次数
     * @returns 
     */
    public addCountTimeCallBack(length: number, count: number = 1, callBack: Function, args?: any) {
        let Key = this.getFreeKey();
        this._timeCallBack.add(Key, new TimeCallBack(Key, length, 1, callBack, args, TIME_DESTORY.COUNT, count));
        return Key;
    }
    /**移除计时器 */
    public removeTimeCallBack(Key: number) {
        if (this._timeCallBack.has(Key)) {
            this._delCallBack.push(Key);
        }
    }
    public update(deltaTime: number) {
        for (let i = 0; i < this._delCallBack.length; ++i) {
            if (this._timeCallBack.has(this._delCallBack[i])) {
                this._timeCallBack.remove(this._delCallBack[i]);
                this._freeTimeKey.push(this._delCallBack[i]);
            }
        }
        this._delCallBack.length = 0;
        let endKey: number[] = [];
        this._timeCallBack.forEach((k, v: TimeCallBack) => {
            if (v.update()) {
                endKey.push(k);
            }
        })

        for (let i = 0; i < endKey.length; ++i) {
            this.removeTimeCallBack(endKey[i]);
        }
    }
}

