import { config } from "../common/config";
/**记录游戏名字和id */
export class GameManager {
    private static _instance: GameManager = null;
    private _gameID: number = 1138;
    private _gameName: string = "";
    private _sceneName: string = "";

    setGameID(gameID: number) {
        this._gameID = gameID;
    }
    getGameID(): number {
        return this._gameID;
    }

    setGameName(gameName: string) {
        this._gameName = gameName;
    }
    getGameName(): string {
        return this._gameName;
    }

    setSceneName(gameID: number) {
        this.setGameID(gameID);
        this.setGameName(config.ClientGameRegistList[gameID].gamePath);
        this._sceneName = config.ClientGameRegistList[gameID].gamePath + "_Scene";
    }

    getSceneName(): string {
        return this._sceneName;
    }

    static getInstance(): GameManager {
        if (null == this._instance) {
            this._instance = new GameManager();
        }
        return this._instance;
    }

    static destroyInstance() {
        if (this._instance) {
            delete this._instance;
            this._instance = null;
        }
    }
}