import { _decorator, Component, instantiate, Node, NodePool } from 'cc';
import { GameTempCore } from './PlinkoCore';

const { ccclass, property } = _decorator;

// 对象池类型
export enum PoolType {
    CirclePlayer,
    Pile
}

@ccclass('PlinkoPoolManager')
export default class PlinkoPoolManager extends Component {

    // 对象池集合
    public pools: { [key in PoolType]?: NodePool } = {};
    public static Instance: PlinkoPoolManager | null = null;

    protected onLoad(): void {
        PlinkoPoolManager.Instance = this;
    }

    //  取对象
    public spawn(poolType: PoolType): Node | null {
        let node: Node | null = null;
        if (!this.pools) return;

        let pool = this.pools[poolType];
        if (pool && pool.size() > 0) {
            node = pool.get();
            node.active = true;
        } else {

            switch (poolType) {
                case PoolType.CirclePlayer:
                    if (GameTempCore.slotMgr.GameMainCmp) {
                        let circlePlayer = GameTempCore.slotMgr.GameMainCmp.circlePlayer;
                        if (!circlePlayer) return null;
                        node = instantiate(circlePlayer);
                    } else {
                        return null;
                    }
                    break;
                case PoolType.Pile:
                    if (GameTempCore.slotMgr.GameMainCmp) {
                        let pilePrefab = GameTempCore.slotMgr.GameMainCmp.pilePrefab;
                        if (!pilePrefab) return null;
                        // console.log("pile instantiate");
                        node = instantiate(pilePrefab);
                    } else {
                        return null;
                    }
                    break;
            }
            //  延迟创建对象池（与你原逻辑一致）
            if (!this.pools[poolType]) {
                this.pools[poolType] = new NodePool();
            }
        }
        return node;
    }

    // 回收对象
    public recycle(node: Node, poolType: PoolType): void {
        if (!this.pools) return;
        let pool = this.pools[poolType];
        if (!pool) {
            pool = this.pools[poolType] = new NodePool();
        }
        this.scheduleOnce(() => {
            if (this.pools) {
                //node.active = false;
                pool.put(node);
            }
            // console.log("pool size ", pool.size());
        }, 0);
    }

    // 回收对象
    public recycleImmediate(node: Node, poolType: PoolType): void {
        if (!this.pools) return;
        let pool = this.pools[poolType];
        if (!pool) {
            pool = this.pools[poolType] = new NodePool();
        }
        if (this.pools) {
            node.active = false;
            pool.put(node);
            // console.log("pool pile size ", pool.size());
        }
    }

    //获取对象池大小
    public getPoolSize(poolType: PoolType) {
        if (!this.pools) return;
        let pool = this.pools[poolType];
        if (!pool) {
            return 0;
        }
        return pool.size();
    }
}
