    /**贝塞尔运动 */
    public bezierMove(
        node: Node,
        duration: number,
        startPos: Vec3,
        endPos: Vec3,
        endFun: Function = null
    ) {

        if (!node || !startPos || !endPos) {
            // console.error('参数无效', { node, startPos, endPos });
            return;
        }

        // 自动计算 rotation
        const dx = endPos.x - startPos.x;
        const dy = endPos.y - startPos.y;
        let rotation = 1; // 默认向上抛物线

        if (dx >= 0 && dy <= 0) {
            // 右下运动
            rotation = 1;
        } else if (dx >= 0 && dy > 0) {
            // 右上运动
            rotation = -1;
        } else if (dx < 0 && dy <= 0) {
            // 左下运动
            rotation = -1;
        } else if (dx < 0 && dy > 0) {
            // 左上运动
            rotation = 1;
        }

        // 判断x轴范围是否小于阈值，不做抛物线，走直线
        if (Math.abs(dx) <= 30) {
            tween(node)
                .to(duration, { position: v3(endPos.x, endPos.y, 0) }, {
                    easing: easing.cubicIn,
                    onUpdate: () => { },
                })
                .call(() => endFun && endFun())
                .start();
            return;
        }

        // 计算贝塞尔控制点，实现抛物线弧度
        const midX = (startPos.x + endPos.x) / 2 + 100 * rotation;
        const midY = (startPos.y + endPos.y) / 2 + 150;
        const controlPoint = v3(midX, midY, 0);

        let obj = { progress: 0 };
        tween(obj)
            .to(duration, { progress: 1 }, {
                onUpdate: ({ progress }) => {
                    // easing 先慢后快
                    let t = easing.cubicIn(progress);
                    // 二次贝塞尔曲线公式
                    let x =
                        (1 - t) * (1 - t) * startPos.x +
                        2 * (1 - t) * t * controlPoint.x +
                        t * t * endPos.x;

                    let y =
                        (1 - t) * (1 - t) * startPos.y +
                        2 * (1 - t) * t * controlPoint.y +
                        t * t * endPos.y;

                    node.setPosition(x, y, 0);
                }
            })
            .call(() => {
                endFun && endFun();
            })
            .start();
    }

    loopScaleAnimation(target: Node, scale: number = 1.1, time: number = 1) {
        if (!this.isGameValid() || !target) return;
        this.stopTweenByNode(target);
        tween(target)
            .to(time, { scale: new Vec3(scale, scale, scale) }, { easing: easing.sineInOut })
            .to(time, { scale: Vec3.ONE }, { easing: easing.sineInOut })
            .union()
            .repeatForever()
            .start();
    }

    tweenScaleByTimeAnimation(target: Node, scale: number = 1.1, time: number = 1, delayTime: number = 0.2) {
        if (!this.isGameValid() || !target) return;
        this.stopTweenByNode(target);
        tween(target)
            .to(delayTime, { scale: v3(scale, scale, scale) })
            .to(delayTime, { scale: Vec3.ONE })
            .union()
            .repeat(time)
            .start();
    }

    /*** 深拷贝*/
    deepClone(obj, hash = new WeakMap()) {
        if (obj === null || typeof obj !== 'object') return obj;
        if (hash.has(obj)) return hash.get(obj);

        let clone = Array.isArray(obj) ? [] : {};
        hash.set(obj, clone);
        for (let key in obj) {
            if (obj.hasOwnProperty(key)) {
                clone[key] = this.deepClone(obj[key], hash);
            }
        }
        return clone;
    }

    /*** 是否有效*/
    public isVaild(target_: any) {
        if (target_ == undefined || target_ == null) {
            return false;
        }
        if (Array.isArray(target_)) {
            return target_.length > 0;
        } else {
            let keys = Object.keys(target_);
            let isVaild = keys.length > 0;
            return isVaild;
        }
    }

