import { PackageId } from "../common/PackageId";
import { LobbyManager } from "../data/LobbyManager";
import { OneSocket } from "../net/OneSocket";
import SocketBuffer from "../net/protocol/SocketBuffer";
import { tools } from "../tools/tools";

/**基本逻辑 大部分数据都在LobbyManager中 */
export class BaseLogic {
    constructor() { }
    // 获取用户密码
    getUserPsw() {
        return tools.myInfo.userPsw;
    }
    // 获取用户ID
    getUserID() {
        return tools.myInfo.userID;
    }
    // 获取用户名称
    getUserName() {
        return tools.myInfo.userName;
    }

    // 获取性别
    getGender() {
        return tools.myInfo.gender;
    }

    // 获取用户金币
    getUserGold() {
        return tools.myInfo.userGold;
    }

    // 获取账户类型
    getAccountType() {
        let accountType = tools.myInfo.accountType;
        if (accountType == null) {
            accountType = tools.myInfo.accountType = tools.getAccountType();
        }
        return accountType;
    }
    // 获取URL参数
    getUserAvataID() {
        return tools.myInfo.userAvataUrl;
    }

    // 获取URL参数
    getUrlParams() {
        return LobbyManager.getInstance().urlParams;
    }

    // 请求用户金币
    requestWealth() {
        let msg = new SocketBuffer(PackageId.MsgResponseWealth);
        let buf = OneSocket.getInstance().packData.pack(msg);
        LobbyManager.getInstance().sendData(PackageId.MsgRequestWealth, buf);
    }

    // 发送数据
    sendData(requestId: PackageId, data: any, responseId: PackageId = PackageId.NORESPONSEID, callbackFun = null) {
        LobbyManager.getInstance().sendData(requestId, data, responseId, callbackFun);
    }

    // 绑定网络回调
    bindingNetCallback(mainID: number, callbackFun) {
        LobbyManager.getInstance().bindingNetCallback(mainID, callbackFun);
    }

    // 移除网络回调
    removeNetCallback(mainID: number) {
        LobbyManager.getInstance().removeNetCallback(mainID);
    }

    // 关闭Socket连接
    closeSocket() {
        LobbyManager.getInstance().close();
    }
}
