import { sys } from "cc";
import { DEBUG } from "cc/env";

let PLATFORM_NAME = "_TP8";

let ORDER_SOURCE_VALUE = "web";

if (sys.isBrowser) {
    if (DEBUG) {
        ORDER_SOURCE_VALUE = "DEV";
    }
    if ((<any>window).location.hostname.indexOf("192.168.1") != -1) {
        ORDER_SOURCE_VALUE = "DEV";
    }
    if ((location.origin == 'http://dl.googlebrz.com' && location.pathname == '/test/web/index.html')) {
        ORDER_SOURCE_VALUE = "DEV";
    }
}

