import { _decorator, assetManager, Button, director, instantiate, Node, Prefab, UIOpacity, Vec3 } from 'cc';
const { ccclass, property } = _decorator;

import { DataNotify } from "../data/DataNotify";
import { Market } from "../market/Market";
import { tools } from "../tools/tools";
import { BaseUI } from "./BaseUI";
import { Popup } from './Popup';
import { ui } from "./ui";
import { EventTouch } from 'cc';

export abstract class LobbyBaseLayer extends BaseUI {
    @property(Node)
    private background: Node | null = null!;
    @property(Node)
    public mainLayout: Node | null = null!;

    @property({ tooltip: "是否播放弹出音效" })
    private isPlayShowEffect = false;

    @property({ tooltip: "是否停止点击背景关闭窗口" })
    public isStopTouchClose = false;

    public static UIMAP = new Map<string, Node>();
    //public static LastUIName:string[] = [];
    public uiname: string = "uiName";
    onLoad() {
        this.uiname = this.name;

        if (LobbyBaseLayer.UIMAP.has(this.uiname)) {
            let uinode = LobbyBaseLayer.UIMAP.get(this.uiname);
            uinode.destroy();
        }

        LobbyBaseLayer.UIMAP.set(this.uiname, this.node);

        super.onLoad();

        DataNotify.getInstance().addListener(this);

        if (this.background) {
            this.background!.getComponent(UIOpacity)!.opacity = 200;
        }

        if (this.mainLayout) {
            this.mainLayout!.getComponent(UIOpacity)!.opacity = 0;
            this.mainLayout!.scale = new Vec3(0, 0, 0);
            tools.openLayerAction(this.mainLayout);
        }


        if (!this.isStopTouchClose && this.background) {
            let btn = this.background.getComponent(Button);
            if (btn == null) {
                btn = this.background.addComponent(Button);
            }
            btn.node.off("click", this.onCloseBtnClick, this);
            this.scheduleOnce(() => {
                btn.node.once("click", this.onCloseBtnClick, this);
            }, 1);
            if (Market.getInstance().getOrientation() == "V") {
                //显示 点击屏幕关闭窗
                ui.getCloseUITip(this.node);
            }
        }

    }

    onCloseBtnClick() {
        this.playBtnClickEffect();
        if (this.background) {
            this.background.getComponent(UIOpacity)!.opacity = 0;
        }
        if (this.mainLayout) {
            tools.closeLayerAction(this.mainLayout, () => {
                this.node.destroy();
            });
        } else {
            this.node.destroy();
        }
    }

    onServiceBtnClick(event: EventTouch) {
        this.playBtnClickEffect();
        tools.clickManager(event.target);
        this.addLayer("Service/ServiceLayer", director.getScene().getChildByName("Canvas"));
    }

    //钻石发生改变（房卡）
    onCardChanged(userCard) { }
    //金币发生改变
    onGoldChanged(userGold) { }
    //银行钱发生变化
    onBankChanged(userBank) { }
    //名字发生变化
    onNameChanged(userName) { }
    //性别发生变化
    onSexChanged(sex) { }
    //头像发生变化
    onAvataChanged(userAvataID) { }
    //返利发生变化
    onRebateChanged(userRebate) { }
    //积分发生改变
    onScoreChanged(userScore) { }
    //经验发生改变
    onExperienceChanged(userExperience) { }
    OnMapChanged(mapName) { }
    OnSignStatusChanged(bEnableSign) { }
    //更新邮件
    updateMailList() { }
    //语言改变
    onLanguageChange(languageType) { }
    //代理
    onAgentChanged(data) { }
    //签到
    onDailyChanged(userSign) { }
    //充值
    onSpecialOfferChargedChanged(specialOfferCharged) { }
    onWithdrawRecordChange(list) { }
    onWithdrawBindListChange(list) { }
    onFreeWithdrawLimitChange(GiftCredit, Credit) { }
    onWithdrawCoinChange(msg) { }
    onBonusInfoChanged(msg) { }
    onPrizeStatusChanged(leftTotalTimes, leftFreeTimes) { }
    onShopAdderDataChanged() { }

    onDestroy() {
        LobbyBaseLayer.UIMAP.delete(this.uiname);
        DataNotify.getInstance().removeListener(this);
        super.onDestroy();
    }
    
    //加载预制体
    addLayer(name: string, parent, callback = null) {
        if (!name || name == "" || !parent) {
            if (callback) callback(null);
            return;
        }
        let bundle = assetManager.getBundle("Lobby");
        if (bundle) {
            let path = "res/prefab/" + name;
            let ass = bundle.get(path, Prefab);
            if (ass) {
                let layer = instantiate(ass);
                layer.parent = parent;
                if (callback) callback(layer);
            } else {
                bundle.load("res/prefab/" + name, Prefab, (err, prefab) => {
                    if (err) {
                        if (callback) callback(null);
                        return;
                    }
                    let layer = instantiate(prefab);
                    layer.parent = parent;
                    if (callback) callback(layer);
                });
            }
        } else {
            if (callback) callback(null);
        }
    }

    //加载弹窗预制体
    createPopUp(name: string, callback = null) {
        if (!name || name == "") {
            if (callback) callback(null);
            return;
        }
        let bundle = assetManager.getBundle("Lobby");
        if (bundle) {
            let path = "res/prefab/" + name;
            let ass = bundle.get(path, Prefab);
            if (ass) {
                let layer = instantiate(ass);
                layer.parent = tools.topLayer;
                layer.getComponent(Popup).onPopUp(callback);
                if (callback) callback(layer);
            } else {
                bundle.load("res/prefab/" + name, Prefab, (err, prefab) => {
                    if (err) {
                        if (callback) callback(null);
                        return;
                    }
                    let layer = instantiate(prefab);
                    layer.parent = tools.topLayer;
                    layer.getComponent(Popup).onPopUp(callback);
                    if (callback) callback(layer);
                });
            }
        } else {
            if (callback) callback(null);
        }
    }

    playBtnClickEffect(name: string = "button1") {
        super.playBtnClickEffect(name, "Lobby");
    }
}