import { ggLogger } from "db://gg-hot-update/scripts/hotupdate/GGLogger";

/**定义Socket消息包 */
export default class SocketBuffer {

    private msgId: number;//消息ID
    private userId: number;//用户ID
    private userConnId: number;//user连接ID
    private encryptType: number;//加密类型
    private checkCode: number;//校验码
    private dataLen: number;//消息长度
    private data: Uint8Array;//消息数据

    constructor(msgId: number = 0, data: Uint8Array = new Uint8Array(0), encryptType: number = 2, userID: number = 0, userConnId: number = 0, checkCode: number = 0) {
        this.msgId = msgId;
        this.userId = userID;
        this.userConnId = userConnId;
        this.encryptType = encryptType;
        this.checkCode = checkCode;
        this.dataLen = data.length;
        this.data = data;
    }

    getMsgId(): number {
        return this.msgId;
    }

    getUserId(): number {
        return this.userId;
    }

    getMsgLen(): number {
        return this.dataLen;
    }

    getUserConnId(): number {
        return this.userConnId;
    }

    getEncryptType(): number {
        return this.encryptType;
    }

    getCheckCode(): number {
        return this.checkCode;
    }

    getData(): Uint8Array {
        return this.data;
    }

    setMsgId(id: number): void {
        this.msgId = id;
    }

    setMsgLen(len: number): void {
        this.dataLen = len;
    }

    setEncryptType(encryptType: number): void {
        this.encryptType = encryptType;
    }

    setCheckCode(checkCode: number): void {
        this.checkCode = checkCode;
    }

    setData(data: Uint8Array): void {
        if (!data) {
            ggLogger.error("SocketBuffer.setData: 传入 null，已忽略");
            return;
        }
        this.data = data;
        this.dataLen = data.length;
    }

    setUserId(userId: number): void {
        this.userId = userId;
    }

    setUserConnId(connId: number): void {
        this.userConnId = connId;
    }
}