import { ggLogger } from "db://gg-hot-update/scripts/hotupdate/GGLogger";
import { ComPbData } from "./ComPbData";
import { LobbyFrameData } from "./LobbyFrameData";
import { LobbyMsgData } from "./LobbyMsgData";
import { LobbyPbData } from "./LobbyPbData";
import { LoginPbData } from "./LoginPbData";
import { WebPbData } from "./WebPbData";

/**proto协议转化管理 */
export class ProtoMgr {
    private static _instance: ProtoMgr = null!;

    public static getInstance(): ProtoMgr {
        if (this._instance === null) {
            this._instance = new ProtoMgr();
        }
        return this._instance;
    }

    public static destroyInstance(): void {
        if (this._instance) {
            delete this._instance;
            this._instance = null;
        }
    }

    //大厅房间协议
    public encodeLobbyWebMgr(msgName, msgBody = {}): Uint8Array {
        let rs = WebPbData.getInstance().getLobbyPb().root.lookupType(msgName);
        let msg = rs.create(msgBody);
        let buf = rs.encode(msg).finish();
        return buf;
    }

    public decodeLobbyWebMgr(msgName, msgBuf: Uint8Array): any {
        let rs = WebPbData.getInstance().getLobbyPb().root.lookupType(msgName);
        try {
            return rs.decode(msgBuf);
        } catch (error) {
            ggLogger.log("解析失败:", msgName, rs);
            return null;
        }
    }


    //大厅房间协议
    public encodeLobbyFrameMgr(msgName, msgBody = {}): Uint8Array {
        let rs = LobbyFrameData.getInstance().getLobbyPb().root.lookupType(msgName);
        let msg = rs.create(msgBody);
        let buf = rs.encode(msg).finish();
        return buf;
    }

    public decodeLobbyFrameMgr(msgName, msgBuf: Uint8Array): any {
        let rs = LobbyFrameData.getInstance().getLobbyPb().root.lookupType(msgName);
        try {
            return rs.decode(msgBuf);
        } catch (error) {
            ggLogger.log("解析失败:", msgName, rs);
            return null;
        }
    }

    //大厅房间协议
    public encodeComMgr(msgName, msgBody = {}): Uint8Array {
        let rs = ComPbData.getInstance().getLobbyPb().root.lookupType(msgName);
        let msg = rs.create(msgBody);
        let buf = rs.encode(msg).finish();
        return buf;
    }

    public decodeComMgr(msgName, msgBuf: Uint8Array): any {
        let rs = ComPbData.getInstance().getLobbyPb().root.lookupType(msgName);
        try {
            return rs.decode(msgBuf);
        } catch (error) {
            ggLogger.log("解析失败:", msgName, rs);
            return null;
        }
    }

    //大厅协议
    public encodeLobbyMgr(msgName, msgBody = {}): Uint8Array {
        let rs = LobbyPbData.getInstance().getLobbyPb().root.lookupType(msgName);
        let msg = rs.create(msgBody);
        let buf = rs.encode(msg).finish();
        return buf;
    }

    public decodeLobbyMgr(msgName, msgBuf: Uint8Array): any {
        let rs = LobbyPbData.getInstance().getLobbyPb().root.lookupType(msgName);
        try {
            return rs.decode(msgBuf);
        } catch (error) {
            ggLogger.log("解析失败:", msgName, rs);
            return null;
        }
    }

    //提示协议
    public encodeMsgMgr(msgName, msgBody = {}): Uint8Array {
        let rs = LobbyMsgData.getInstance().getLobbyPb().root.lookupType(msgName);
        let msg = rs.create(msgBody);
        let buf = rs.encode(msg).finish();
        return buf;
    }

    public decodeMsgMgr(msgName, msgBuf: Uint8Array): any {
        let rs = LobbyMsgData.getInstance().getLobbyPb().root.lookupType(msgName);
        try {
            return rs.decode(msgBuf);
        } catch (error) {
            ggLogger.log("解析失败:", msgName, rs);
            return null;
        }
    }

    //登录协议
    public encodeLoginMgr(msgName, msgBody = {}): Uint8Array {
        let rs = LoginPbData.getInstance().getLoginPb().root.lookupType(msgName);
        let msg = rs.create(msgBody);
        let buf = rs.encode(msg).finish();
        return buf;
    }

    public decodeLoginMgr(msgName, msgBuf: Uint8Array): any {
        let rs = LoginPbData.getInstance().getLoginPb().root.lookupType(msgName);
        try {
            return rs.decode(msgBuf);
        } catch (error) {
            ggLogger.log("解析失败:", msgName, rs);
            return null;
        }
    }

    public create(pb, msgName, msgBody): Object {
        if (!pb?.root) {
            ggLogger.log("create failed: protobuf root is null", msgName, pb);
            return null;
        }
        let rs = pb.root.lookupType(msgName);
        let msg = rs.create(msgBody);
        return msg;
    }

    public encodeMgr(pb, msgName, msgBody): Uint8Array {
        if (!pb?.root) {
            ggLogger.log("encode failed: protobuf root is null", msgName, pb);
            return new Uint8Array();
        }
        let rs = pb.root.lookupType(msgName);
        let msg = rs.create(msgBody);
        let buf = rs.encode(msg).finish();
        // ggLogger.log('buf == ', buf);
        return buf;
    }

    public decodeMgr(pb, msgName, msgBuf: Uint8Array): any {
        if (!pb?.root) {
            ggLogger.log("decode failed: protobuf root is null", msgName, pb);
            return null;
        }
        try {
            let rs = pb.root.lookupType(msgName);
            let msg = rs.decode(msgBuf);
            // ggLogger.log('msg == ', msg);
            return msg;
        } catch (error) {
            ggLogger.log("解析失败:", msgName, error);
            return null;
        }
    }
}
