import { _decorator, CircleCollider2D, Collider2D, Component, Contact2DType, IPhysics2DContact, Node, RigidBody2D, Sprite, SpriteFrame, UITransform, Vec2, Vec3 } from 'cc';
import { ColorType, GameTempCore } from './PlinkoCore';
import { PoolType } from './PlinkoPoolManager';
import { MotionTrail } from '../../Lobby/src/cmd/MotionTrail';

const { ccclass, property } = _decorator;

@ccclass('PlinkoCirclePlayer')
export class PlinkoCirclePlayer extends Component {

    @property(SpriteFrame) yellowCircle: SpriteFrame = null;
    @property(SpriteFrame) orangeCircle: SpriteFrame = null;
    @property(SpriteFrame) redCircle: SpriteFrame = null;

    private arrived = false;
    public targetNode: Node = null;
    public targetId = 0;
    public colorType: ColorType = ColorType.none;
    private sprite: Sprite = null;
    private startPointPosition: Vec3 = null;
    private rowSize: number = 8;
    private serverData: any = null;
    private readonly HIT_DISTANCE = 2;
    private readonly ERROR_Y = -1000;
    private readonly ATTRACT_START_OFFSET_Y = 50;
    private readonly MAX_SPEED = 15;
    private readonly MIN_SPEED = 5;
    private readonly STEER = 0.08;

    private curRoad:number[][] = [];
    private curPoint:number = 0;
    private isFirstBall:boolean = false;

    protected onLoad(): void {
        //this.sprite = this.node.getComponent(Sprite);
    }

    onEnable() {
        this.arrived = false;
        this.curPoint = 0;
    }

    onDisable() {

    }

    public setIsFirstBall(isFirst:boolean) {
        this.isFirstBall = isFirst;
    }

    // -------------------------
    // 基础数据设置
    // -------------------------
    public setTargetId(id: number) {
        this.targetId = id;
        this.curPoint = 0;
        this.arrived = false;
        this.curRoad = GameTempCore.GetRoad(id);
        if(this.curRoad==undefined)
        {
            this.node.active = true;
        }

        //this.node.active = this.curRoad!=undefined;
    }

    public isLastOrStart() {
        let slotMgr = GameTempCore.slotMgr;
        let multiple = slotMgr.rowType + 1;
        let specialIds = [
            0, 1, 2, 3,
            slotMgr.gameRow - 3, slotMgr.gameRow - 2, slotMgr.gameRow - 1, slotMgr.gameRow,
        ];
        return specialIds.indexOf(this.targetId) > -1;
    }

    public setTargetServerData(data: any) {
        this.serverData = data;
    }

    public getTargetServerData() {
        return this.serverData;
    }

    public setTargetNode(target: Node) {
        this.targetNode = target;
    }

    public setStartPointPosition(position: Vec3) {
        this.startPointPosition = position
    }

    // -------------------------
    // 业务逻辑
    // -------------------------
    public setInfo(type: ColorType) {
        //this.changeColor(type);
        this.colorType = type;
    }

    public setSize(size: number) {

    }


    public changeColor(colorType: ColorType) {
        if (!this.sprite) return;

        switch (colorType) {
            case ColorType.orange:
                this.sprite.spriteFrame = this.orangeCircle;
                break;
            case ColorType.yellow:
                this.sprite.spriteFrame = this.yellowCircle;
                break;
            case ColorType.red:
                this.sprite.spriteFrame = this.redCircle;
                break;
        }
    }

    update(dt: number) {
        if (this.arrived || !this.targetNode || !this.curRoad) return;
        this.attractToTarget();
    }

    private attractToTarget() {
        //  命中
        if (this.curRoad.length <= this.curPoint) {
            this.arrive();
            return;
        }
        const info = this.curRoad[this.curPoint++];
        if(info[1]<-135)
        {
            this.arrive();
            return;
        }
    
        
        this.node.setPosition(info[0],info[1],0);
        //this.node.eulerAngles = new Vec3(info[2],info[3],0);
        
        if(info[4]!=undefined && info[5]!=undefined)
        {
            GameTempCore.slotMgr.GameMainCmp.gameProcess.playPileLight(-info[4],-info[5]);

            if(this.isFirstBall)
            {
    
                const trailNode = this.node.getChildByName('trail');
                    if (trailNode) {
                        trailNode.active = false;
                        const motionTrail = trailNode.getComponent(MotionTrail);
                        if (motionTrail) {
                            const tryEnableTrail = () => {
                                if (!trailNode.isValid || !this.node.isValid) return;
                                if (!motionTrail.spriteFrame || !motionTrail.spriteFrame.texture) {
                                    this.scheduleOnce(tryEnableTrail, 0);
                                    return;
                                }
                                trailNode.active = true;
                                motionTrail.enabled = true;
                                motionTrail.isActive = true;
                                motionTrail.ensureRenderData();
                                motionTrail.refresh();
                            };
                            this.scheduleOnce(tryEnableTrail, 0);
        
                        }
                    }
            }
        }
    }

    // 判定到达了
    arrive() {
        this.arrived = true;
        GameTempCore.slotMgr.GameMainCmp.gameProcess.SetRewardPerform(this.targetId, this.node);

        let data = {
            destoryNode: this.node,
            poolType: PoolType.CirclePlayer
        }
        GameTempCore.slotMgr.GameMainCmp.spawnRewardAndScroll(this.targetId);
        GameTempCore.slotMgr.gm.emit(GameTempCore.slotConfig.eventNames.DestroyCirclePlayer, data);
    }

    // 出现错误
    appearError() {
        this.arrived = true;
        let data = {
            destoryNode: this.node,
            poolType: PoolType.CirclePlayer
        }
        GameTempCore.slotMgr.gm.emit(GameTempCore.slotConfig.eventNames.DestroyCirclePlayer, data);
    }
}
