import { DEBUG } from "cc/env";
import { ggLogger } from "db://gg-hot-update/scripts/hotupdate/GGLogger";
import { config } from "../../common/config";

/**
 * @description Http相关枚举定义
 */
export namespace Http {
    /**@description http错误类型 */
    export enum ErrorType {
        /**@description 错误的Url地地址*/
        UrlError,
        /**@description 请求超时 */
        TimeOut,
        /**@description 请求错误 */
        RequestError,
    }

    /**@description http 请求类型 */
    export enum Type {
        POST = "POST",
        GET = "GET",
        PUT = "PUT",
    }
    /**@description http 错误 */
    export interface Error {
        type: ErrorType;
        reason: any;
    }
}

/**
 * @description http 请求包
 */
export class HttpPackage {
    public isURL: boolean = true;//不走拼接
    public path: string = "";
    public type: Http.Type = Http.Type.POST;
    public buffer: any = null;
    public header: { name: string; value: string }[] | { name: string; value: string } | { [key: string]: string } | null = null;
    public responseType: XMLHttpRequestResponseType = "arraybuffer";
    public timeout: number = 10000;
    public async: boolean = true;

    private _params: Object = null!;
    /**
     * @description 传入的请求参数会拼在data.url
     * @example params = { a : 10 , b : 20 }
     * 最终的url 为data.url?&a=10&b=20
     */
    public set params(value: Object) {
        this._params = value;
    }
    public get params() {
        return this._params;
    }
    /**
     * @description 发送请求包
     * @param cb
     * @param errorcb
     */
    public send(cb?: (data: any) => void, errorcb?: (errorData: Http.Error) => void) {
        HttpClient.ins.request(this, cb, errorcb);
    }
}

export class HttpClient {
    private static _instance: HttpClient;

    public static get ins() {
        if (!this._instance) {
            this._instance = new HttpClient();
        }
        return this._instance;
    }

    private _url: string = null;
    public setURL(num = 1) {
        if (num == 1) {
            this._url = `${"http://"}${config.http.addr}${":"}${config.http.port}`;
        } else if (num == 2) {
            this._url = `${"http://"}${config.http.addr2}${":"}${config.http.port2}`;
        } else if (num == 3) {
            this._url = `${config.http.dirConn}`;
        }
    }
    protected convertParams(url: string, params: Object): string {
        if (params == null || params == undefined) {
            return url;
        }
        let result = "&";
        if (url.indexOf("?") < 0) {
            result = "?";
        }
        let keys = Object.keys(params);
        for (let i = 0; i < keys.length; i++) {
            if (i == 0) {
                result += `${keys[i]}=${(<any>params)[keys[i]]}`;
            } else {
                result += `&${keys[i]}=${(<any>params)[keys[i]]}`;
            }
        }
        result = url + result;
        return result;
    }

    protected convertData(data: any) {
        return data;
    }

    request(httpPackage: HttpPackage, cb?: (data: any) => void, errorcb?: (errorData: Http.Error) => void) {
        let url = (httpPackage.isURL) ? this._url : httpPackage.path;
        if (!url) {
            if (DEBUG) {
                ggLogger.error(`reuqest url error`);
            }
            if (errorcb) errorcb({ type: Http.ErrorType.UrlError, reason: "错误的Url地址" });
            if (cb) cb(null);
            return;
        }
        let xhr = new XMLHttpRequest();
        xhr.onreadystatechange = function () {
            if (xhr.readyState === 4) {
                if (xhr.status >= 200 && xhr.status < 300) {
                    if (xhr.responseType == "arraybuffer" || xhr.responseType == "blob") {
                        let response = null;
                        if (xhr.responseType == "arraybuffer") {
                            response = new Uint8Array(xhr.response);
                        } else {
                            let reader = new FileReader();
                            reader.onloadend = function () {
                                // 读取完成后获得结果数据
                                response = new Uint8Array(this.result as ArrayBuffer);
                            };
                            // 开始读取文件内容并转换为ArrayBuffer
                            reader.readAsArrayBuffer(xhr.response);
                        }
                        if (cb) cb(response);
                    } else {
                        if (cb) cb(xhr.responseText);
                    }
                } else {
                    let reason = `Request error, error status:${xhr.status}`;
                    ggLogger.error(`request error status : ${xhr.status} url : ${url} `);
                    if (errorcb) errorcb({ type: Http.ErrorType.RequestError, reason: reason });
                    if (cb) cb(null);
                }
            }
        };

        xhr.responseType = httpPackage.responseType;
        xhr.timeout = httpPackage.timeout;
        xhr.ontimeout = () => {
            xhr.abort(); //网络超时，断开连接
            if (DEBUG) ggLogger.warn(`request timeout : ${url}`);
            if (errorcb) errorcb({ type: Http.ErrorType.TimeOut, reason: "Connection timed out" });
            if (cb) cb(null);
        };

        xhr.onerror = () => {
            ggLogger.error(`request error : ${url} `);
            if (errorcb) errorcb({ type: Http.ErrorType.RequestError, reason: "Request error" });
            if (cb) cb(null);
        };

        url = httpPackage.isURL ? (url += httpPackage.path) : url;
        url = this.convertParams(url, httpPackage.params);
        // if (DEBUG) ggLogger.log(`[send http request] url : ${url} request type : ${httpPackage.type} , responseType : ${xhr.responseType}`);
        
        if (httpPackage.type === Http.Type.POST) {
            xhr.open(Http.Type.POST, url, httpPackage.async);
            this.setHeaders(xhr, httpPackage.header);
            xhr.send(this.convertData(httpPackage.buffer));
        } else if (httpPackage.type === Http.Type.PUT) {
            xhr.open(Http.Type.PUT, url, httpPackage.async);
            this.setHeaders(xhr, httpPackage.header);
            xhr.send(this.convertData(httpPackage.buffer));
        } else {
            xhr.open(Http.Type.GET, url, httpPackage.async);
            this.setHeaders(xhr, httpPackage.header);
            // GET 请求也可以发送 body（虽然不标准，但某些 API 需要）
            if (httpPackage.buffer) {
                xhr.send(this.convertData(httpPackage.buffer));
            } else {
                xhr.send();
            }
        }
    }

    /**
     * 设置请求头
     */
    private setHeaders(xhr: XMLHttpRequest, headers: any) {
        if (headers) {
            if (headers instanceof Array) {
                headers.forEach((header) => {
                    xhr.setRequestHeader(header.name, header.value);
                });
            } else if (typeof headers === 'object') {
                // 支持对象格式的 headers
                Object.keys(headers).forEach(key => {
                    xhr.setRequestHeader(key, headers[key]);
                });
            } else {
                let header: { name: string; value: string } = headers;
                xhr.setRequestHeader(header.name, header.value);
            }
        } else {
            xhr.setRequestHeader("Content-Type", "text/plain;charset=UTF-8");
        }
    }
}
