import { director, sys } from 'cc';
import { common } from '../common/common';
export let i18n_language = 'en';
export let i18n_ready: boolean = false;

/**
 * 初始化
 * @param language 
 */
export function i18n_init(language: string) {
    i18n_ready = true;
    i18n_language = language;
    sys.localStorage.setItem(common.LANGUAGES, language);
}

export function reverseRTL(text: string): string {
    return text;
}
/**
 * 翻译数据
 * @param key 
 */
export function i18n_t(key: string) {
    const win: any = window;
    if (!win.languages) {
        return "";
    }
    const searcher = key.split('.');
    let data = win.languages[i18n_language];
    for (let i = 0; i < searcher.length; i++) {
        if (!data || typeof data !== 'object') {
            return "";
        }
        const currentKey = searcher[i];
        if (!(currentKey in data)) {
            return "";
        }
        const nextData = data[currentKey];
        if (nextData === null || nextData === undefined) {
            return "";
        }
        data = nextData;
    }

    return data;
}

export function i18n_updateSceneRenderers() { // very costly iterations
    const rootNodes = director.getScene()!.children;
    // walk all nodes with localize label and update
    const allLocalizedLabels: any[] = [];
    for (let i = 0; i < rootNodes.length; ++i) {
        let labels = rootNodes[i].getComponentsInChildren('LocalizedLabel');
        Array.prototype.push.apply(allLocalizedLabels, labels);
    }
    for (let i = 0; i < allLocalizedLabels.length; ++i) {
        let label = allLocalizedLabels[i];
        if (!label.node.active) continue;
        label.updateLabel();
    }
    // walk all nodes with localize sprite and update
    const allLocalizedSprites: any[] = [];
    for (let i = 0; i < rootNodes.length; ++i) {
        let sprites = rootNodes[i].getComponentsInChildren('LocalizedSprite');
        Array.prototype.push.apply(allLocalizedSprites, sprites);
    }
    for (let i = 0; i < allLocalizedSprites.length; ++i) {
        let sprite = allLocalizedSprites[i];
        if (!sprite.node.active) continue;
        sprite.updateSprite();
    }
}

// 供插件查询当前语言使用
const win = window as any;
win._languageData = {
    get language() {
        return i18n_language;
    },
    init(lang: string) {
        i18n_init(lang);
    },
    updateSceneRenderers() {
        i18n_updateSceneRenderers();
    },
};