import { _decorator, CircleCollider2D, Collider2D, Component, Contact2DType, IPhysics2DContact, Node, RigidBody2D, Sprite, SpriteFrame, UITransform, Vec2, Vec3 } from 'cc';
import { ColorType, GameTempCore } from './PlinkoCore';
import { PoolType } from './PlinkoPoolManager';
import { PlinkoPile } from "./PlinkoPile";
import { PlinkoRewardItem } from "./PlinkoRewardItem";

const { ccclass, property } = _decorator;

@ccclass('VirtualBall')
export class VirtualBall extends Component {

    private arrived = false;
    public targetId = 0;
    public colorType: ColorType = ColorType.none;
    private rigidBody: RigidBody2D | null = null;
    private startPointPosition: Vec3 = null;
    private rowSize: number = 8;
    private serverData: any = null;
    private readonly HIT_DISTANCE = 2;
    private readonly ERROR_Y = -1000;
    private readonly ATTRACT_START_OFFSET_Y = 50;
    private readonly MAX_SPEED = 15;
    private readonly MIN_SPEED = 5;
    private readonly STEER = 0.08;
    private BakeRoad: number[][] = [];
    private frameIndex: number = -1;
    //记录位置和旋转
    public ReordPos() {
        this.frameIndex++;
        let pos = this.node.position;
        this.BakeRoad[this.frameIndex] = [
            pos.x, pos.y,
            this.node.eulerAngles.x, this.node.eulerAngles.y,
        ];
        if (pos.y < -165) {
            this.arrive();
        }
    }

    protected onLoad(): void {
        //this.sprite = this.node.getComponent(Sprite);
    }

    initRigidBody(enable: boolean) {
        if (enable) {
            this.BakeRoad = [];
            this.frameIndex = -1;
        }
        this.rigidBody = this.node.getComponent(RigidBody2D);
        if (this.rigidBody) {
            this.rigidBody.enabled = enable;
            if (!enable) this.rigidBody.linearVelocity = new Vec2(0, 0);
        }
        let colliders = this.node.getComponents(Collider2D);
        for (let collider of colliders) {
            collider.enabled = enable;
            if (!enable) {
                collider.off(Contact2DType.BEGIN_CONTACT, this.onBeginContact, this);
            } else {
                collider.on(Contact2DType.BEGIN_CONTACT, this.onBeginContact, this);
            }
        }
    }

    onEnable() {
        this.initRigidBody(true);
        this.arrived = false;
    }

    onDisable() {
        this.initRigidBody(false);
    }

    // -------------------------
    // 基础数据设置
    // -------------------------
    public setTargetId(id: number) {
        this.targetId = id;
    }

    public isLastOrStart() {
        let slotMgr = GameTempCore.slotMgr;
        let multiple = slotMgr.rowType + 1;
        let specialIds = [
            0, 1, 2, 3,
            slotMgr.gameRow - 3, slotMgr.gameRow - 2, slotMgr.gameRow - 1, slotMgr.gameRow,
        ];
        return specialIds.indexOf(this.targetId) > -1;
    }

    public setTargetServerData(data: any) {
        this.serverData = data;
    }

    public getTargetServerData() {
        return this.serverData;
    }

    public setTargetNode(target: Node) {

    }

    public setStartPointPosition(position: Vec3) {
        this.startPointPosition = position
    }

    // -------------------------
    // 业务逻辑
    // -------------------------
    public setInfo(type: ColorType) {
        this.colorType = type;
    }

    public setSize(size: number) {
        this.rowSize = size;

        const rowType = GameTempCore.slotConfig.rowList.indexOf(size);
        const radius = GameTempCore.slotConfig.circlePlayerRadus[rowType] * 0.5;

        //this.node.getComponent(UITransform)!.setContentSize(radius * 2, radius * 2);

        const restitutionMap = [
            0.25,
            this.isLastOrStart() ? 0.9 : 0.9,
            this.isLastOrStart() ? 0.75 : 0.9,
            this.isLastOrStart() ? 0.6 : 0.8,
        ];

        this.node.getComponents(CircleCollider2D).forEach(collider => {
            //collider.radius = radius - 2;
            collider.restitution = restitutionMap[rowType] ?? 0.8;
            collider.apply();
        });
    }

    update(dt: number) {
        if (this.arrived || !this.rigidBody) return;
        this.ReordPos();
    }

    //碰撞监测
    onBeginContact(self: Collider2D, other: Collider2D, contact: IPhysics2DContact) {
        //this.node.getComponent(CircleCollider2D).restitution = Math.random() * 0.1 + 0.15;
        //self.friction = Math.random() * 0.2 + 0.2;
        if (other.node.name.includes("reward")) {
            let index = other.getComponent(PlinkoRewardItem).index;
            if (GameTempCore.DynamicRoad[index].length < GameTempCore.DynamicPoolCount[index]) {
                GameTempCore.DynamicRoad[index].push(this.BakeRoad);
            }

            //本地存储
            /*if (GameTempCore.AllRoad[index].length < GameTempCore.DynamicPoolCount[index]) {
                GameTempCore.AllRoad[index].push(this.BakeRoad);
            }
            if (GameTempCore.IsStoreFull() && !GameTempCore.IsSaveLocal) {
                GameTempCore.IsSaveLocal = true;
                GameTempCore.saveLocal("plinko_road", GameTempCore.AllRoad, 1);
            }*/
            // 延迟到下一帧再执行，避免在physics回调中修改rigidbody状态
            this.arrived = true;
            this.scheduleOnce(() => {
                this.arrive();
            }, 0);
            return;
        };
        if (other.node.name.includes("Pile")) {
            let pile = other.node.getComponent(PlinkoPile);
            this.BakeRoad[this.frameIndex].push(-pile.colIndex);
            this.BakeRoad[this.frameIndex].push(-pile.rowIndex);
        }
    }

    // 判定到达了
    arrive() {
        this.arrived = true;
        this.node.active = false;
    }
}
