import { _decorator, Component, Label, tween } from "cc";
const { ccclass, property } = _decorator

@ccclass
export class LoadingLayer extends Component {
    @property(Label)
    lbTips: Label = null!;

    setMsg(msgText: string, callback = null) {
        this.lbTips.string = "";
        if ("" != msgText && msgText) {
            //this.lbTips.string = msgText;
        }
        this.node.active = true;
        tween(this.node).stop();
        tween(this.node)
            .delay(10)
            .call((() => {
                if (callback) { callback(); }
                this.node.active = false;
            }).bind(this))
            .start();
    }

    public onDisable(): void {
        tween(this.node).stop();
    }
}