
import { director, macro, ResolutionPolicy, screen, sys, view, Widget } from 'cc';
import { ggLogger } from 'db://gg-hot-update/scripts/hotupdate/GGLogger';
import { common } from '../common/common';
import { i18n_t } from "../i18n/LanguageData";
import { tools } from '../tools/tools';
import { ui } from '../ui/ui';

declare const jsb: any;

/**app市场 */
export class Market {
    private static _instance: Market = null;
    public className = 'com/cocos/game/AppActivity';
    private orientation = "H";

    public gameID: number = 0;
    public channel: string = "";
    public agentID: number = 0;
    public directUID: number = 0;
    public origin: string = null;

    constructor() {
        window["Market"] = this;

        director.on("changeScene", (args) => {
            const currentOrientation = this.getOrientation();
            let isChange = currentOrientation != args;
            if (isChange) {
                setTimeout(() => {
                    this.setOrientation(args);
                }, 280);
            }
        }, this);
    }

    static getInstance(): Market {
        if (null == this._instance) {
            this._instance = new Market();
        }
        return this._instance;
    }

    static destroyInstance() {
        if (this._instance) {
            delete this._instance;
            this._instance = null;
        }
    }
    getDeviceCode() {
        if (sys.localStorage.getItem(common.MACHINE_KEY)) {
            return sys.localStorage.getItem(common.MACHINE_KEY);
        }
        if (sys.os === sys.OS.ANDROID && sys.isNative) {
            let ref = tools.toMd5To32();
            tools.setMachineId(ref);
            return ref;
        } else if (sys.isNative && (sys.os == sys.OS.IOS || sys.os == sys.OS.OSX)) {
            let ref = tools.toMd5To32();
            tools.setMachineId(ref);
            return ref;
        } else if (sys.os === sys.OS.WINDOWS) {
            let ref = tools.toMd5To32();
            tools.setMachineId(ref);
            return ref;
        } else if (sys.isBrowser) {
            let ref = tools.toMd5To32();
            tools.setMachineId(ref);
            return ref;
        }
    }

    initUrlParam() {
        if (sys.isBrowser) {
            let obj = tools.queryURLParams();
            common.TOKEN = obj["token"] || "";
            this.gameID = obj["gameId"] || "";
            ggLogger.log("链接参数", obj);
            //19-67标识是测试的渠道
            this.channel = obj["channel"] || "19";
            this.agentID = Number(obj["agentID"]) || 67;
            this.directUID = Number(obj["directUID"]) || 0;
        }
    }

    getOrientation() {
        return this.orientation;
    }

    public onSendMain(data) {
        window.parent.postMessage(data, '*');
    }

    //V H
    setOrientation(dir, w = 375, h = 525) {
        this.orientation = dir;
        if (sys.isBrowser) this.onSendMain({ type: "orientationChange", isLandscape: dir });
        let hMask = null;
        if (tools.topLayer) hMask = tools.topLayer.getChildByName("hMask");
        let frameWidth = screen.windowSize.width / screen.devicePixelRatio;
        let frameHeight = screen.windowSize.height / screen.devicePixelRatio;
        if (dir == 'V') {
            view.setOrientation(macro.ORIENTATION_PORTRAIT);
            if (frameWidth > frameHeight) view.setFrameSize(frameHeight, frameWidth);
            view.setDesignResolutionSize(w, h, ResolutionPolicy.FIXED_WIDTH);
        } else {
            view.setOrientation(macro.ORIENTATION_LANDSCAPE);
            if (frameHeight > frameWidth) view.setFrameSize(frameHeight, frameWidth);
            view.setDesignResolutionSize(w, h, ResolutionPolicy.FIXED_HEIGHT);
        }
        if (hMask && hMask.active) hMask.getComponent(Widget).updateAlignment();

        if (sys.os === sys.OS.ANDROID && sys.isNative) {
            let methodName = 'setOrientation';
            let sigs = "(Ljava/lang/String;)V";
            jsb.reflection.callStaticMethod(this.className, methodName, sigs, dir);
        } else if (sys.isNative && (sys.os == sys.OS.IOS || sys.os == sys.OS.OSX)) {
            if (typeof jsb !== 'undefined' && jsb.reflection) {
                jsb.reflection.callStaticMethod("AppDelegate", "setOrientation:", dir);
            }
        }
    }

    copyText(str: string) {
        if (sys.os === sys.OS.ANDROID && sys.isNative) {
            ui.createTips(i18n_t("dycLan.copyClipBoardShare"));
            let methodName = 'copyToClipboard';
            let sigs = "(Ljava/lang/String;)V";
            jsb.reflection.callStaticMethod(this.className, methodName, sigs, str);
        } else if (sys.isNative && (sys.os == sys.OS.IOS || sys.os == sys.OS.OSX)) {
            ui.createTips(i18n_t("dycLan.copyClipBoardShare"));
            if (typeof jsb !== 'undefined' && jsb.reflection) {
                jsb.reflection.callStaticMethod("AppDelegate", "copyToClipboard:", str);
            }
        } else {
            if (navigator.clipboard && window.isSecureContext) {// navigator clipboard 向剪贴板写文本
                navigator.clipboard.writeText(str)
                ui.createTips(i18n_t("dycLan.copyClipBoardShare"));
            } else {
                let textArea = document.createElement("textarea");
                const DomInfo = document.getElementById('company-bank-info')
                textArea.value = str;
                textArea.style.position = "absolute";
                textArea.style.opacity = "0";
                textArea.style.left = "-999999px";
                textArea.style.top = "-999999px";
                document.body.appendChild(textArea);
                textArea.focus();
                textArea.select();
                new Promise<void>((res, rej) => {                    // 执行复制命令并移除文本框
                    document.execCommand('copy') ? res() : rej();
                    textArea.remove();
                    ui.createTips(i18n_t("dycLan.copyClipBoardShare"));
                });
            }
        }
    }

    /**
     * 自动获取剪贴板内容
     * @returns Promise<string> 剪贴板文本内容，失败返回空字符串
     */
    async pasteText(): Promise<string> {
        try {
            if (sys.os === sys.OS.ANDROID && sys.isNative) {// Android 原生平台
                let methodName = 'getClipboardText';
                let sigs = "()Ljava/lang/String;";
                let result = jsb.reflection.callStaticMethod(this.className, methodName, sigs);
                return result || '';
            } else if (sys.isNative && (sys.os == sys.OS.IOS || sys.os == sys.OS.OSX)) { // iOS 原生平台
                if (typeof jsb !== 'undefined' && jsb.reflection) {
                    let result = jsb.reflection.callStaticMethod("AppDelegate", "getClipboardText");
                    return result || '';
                }
            } else if (sys.isBrowser) {// Web 平台
                if (navigator.clipboard && window.isSecureContext) {
                    const text = await navigator.clipboard.readText();
                    return text || '';
                } else {
                    console.warn('剪贴板读取需要用户交互或 HTTPS 环境');
                    return '';
                }
            }
            return '';
        } catch (error) {
            console.error('读取剪贴板失败:', error);
            return '';
        }
    }

    /**
     * 带提示的粘贴文本（自动显示提示）
     */
    async pasteTextWithTip(): Promise<string> {
        const text = await this.pasteText();
        ui.createTips(`${text}`);
        return text;
    }

    //打开网页
    openURL(url) {
        if (sys.os === sys.OS.ANDROID && sys.isNative) {
            let methodName = 'openUrl';
            let sigs = "(Ljava/lang/String;)V";
            jsb.reflection.callStaticMethod(this.className, methodName, sigs, url);
        } else if (sys.isNative && (sys.os == sys.OS.IOS || sys.os == sys.OS.OSX)) {
            if (typeof jsb !== 'undefined' && jsb.reflection) {
                jsb.reflection.callStaticMethod("AppDelegate", "openUrl:", url);
            }
        }
    }

    /**
     * 启用屏幕常亮
     */
    public enableKeepScreenOn(isKeepScreen: boolean = true): void {
        if (sys.os === sys.OS.ANDROID && sys.isNative) {
            jsb.reflection.callStaticMethod(
                this.className,
                "setKeepScreenOn",
                "(Z)V",
                isKeepScreen
            );
        } else if (sys.isNative && (sys.os == sys.OS.IOS || sys.os == sys.OS.OSX)) {
            if (typeof jsb !== 'undefined' && jsb.reflection) {
                jsb.reflection.callStaticMethod("AppDelegate", "setKeepScreenOn:", isKeepScreen);
            }
        }
    }

    /**
     * 震动
     * @param milliseconds 震动时长（毫秒）
     */
    public vibrate(milliseconds: number = 500): void {
        if (sys.os === sys.OS.ANDROID && sys.isNative) {
            jsb.reflection.callStaticMethod(
                this.className,
                "vibrateDevice",
                "(I)V",
                milliseconds
            );
        } else if (sys.isNative && (sys.os == sys.OS.IOS || sys.os == sys.OS.OSX)) {
            if (typeof jsb !== 'undefined' && jsb.reflection) {
                jsb.reflection.callStaticMethod("AppDelegate", "vibrateDevice:", milliseconds);
            }
        } else if (sys.isBrowser) {// Web平台的震动API
            if (navigator.vibrate) {
                navigator.vibrate(milliseconds);
            }
        }
    }
}