import { _decorator, Color, director, EventTouch, Label, Node, Sprite, sys, UIOpacity } from 'cc';
import { Hotconfig } from 'db://assets/LogoScene/hotupdate/Hotconfig';
import { UIPath } from '../../../cmd/UIPath';
import { common } from '../../../common/common';
import { MoneyLogic } from '../../../logic/MoneyLogic';
import { Market } from '../../../market/Market';
import { AudioManager } from '../../../tools/AudioManager';
import { lodash } from '../../../tools/lodash';
import { tools } from '../../../tools/tools';
import { LobbyBaseLayer } from '../../../ui/LobbyBaseLayer';
import { ui } from '../../../ui/ui';
const { ccclass, property } = _decorator;

@ccclass
export class DepositSceneUI extends UIPath {
    myInfo: Node | null = null;
    GoldLabel: Node | null = null;
    ui_dagou: Node | null = null;
    amount: Node | null = null;
    channls: Node | null = null;
    payNd: Node | null = null;
    firstNd: Node | null = null;
}

@ccclass('DepositLayer')
export class DepositLayer extends LobbyBaseLayer {
    mUI: DepositSceneUI;

    private goldLb: Label = null;
    private goodsId: number = 0;
    private channlsId: number = 0;
    private curPayData: any = null;
    private curPayArr: any = null;
    private isGou: boolean = true;
    private _moneyLogic: MoneyLogic = new MoneyLogic();
    private payList: any = null;
    private curDir: string = "V";
    private isMusic: boolean = false;
    private isSound: boolean = false;
    onLoad() {
        super.onLoad();
        //初始化UI对象
        this.mUI = new DepositSceneUI().analyse(this.node);
        this.goldLb = this.mUI.GoldLabel.getComponent(Label);

        //商品列表
        if (!tools.goodsList) {
            this._moneyLogic.requestGoodsList((data) => {
                data.content.sort((a, b) => a.price - b.price);
                tools.goodsList = { version: data.version, resourceId: data.resourceId, content: data.content };
                this.uiInit(this.goodsId);
            });
        } else {
            this.uiInit(this.goodsId);
        }
        if (tools.loginData && tools.loginData.paymentTerms) {
            tools.loginData.paymentTerms.sort((a, b) => a.paymentId - b.paymentId);
            this.payList = lodash.groupByToArray(tools.loginData.paymentTerms, 'paymentShowName');
        }

        director.on("userPaySuccess", this.onGoldChangedX, this);
        if (tools.GAME_TYPE == common.GAME_TYPE.GAME) {
            let isMusic = sys.localStorage.getItem(common.MUSIC_SWITCH);
            this.isMusic = (isMusic == "false") ? false : true;
            let isSound = sys.localStorage.getItem(common.SOUND_SWITCH);
            this.isSound = (isSound == "false") ? false : true;

            AudioManager.instance?.setSoundSwitch(false);
            AudioManager.instance?.setMusicSwitch(false);
        }
        this.onGoldChanged(tools.myInfo.userGold);
    }

    onGoldChanged(userGold) {
        this.goldLb.string = tools.convertCentsToYuan(userGold);
    }

    uiInit(idx) {
        if (tools.myInfo.VipPoint > 0) {
            this.mUI.firstNd.active = false;
            this.tsActive(false);
        } else {
            this.mUI.firstNd.active = true;
        }

        tools.goodsList.content.forEach((ele, i) => {
            let good = this.mUI.amount.getChildByName(`btn${i + 1}`);
            let ts = good.getChildByName("ts");
            good.getChildByName("txt").getComponent(Label).string = `₦${tools.gradingNumber3(ele.price)}`;
            ts.getChildByName("tsTxt").getComponent(Label).string = `+${tools.gradingNumber3(ele.officialGift)}`;

            if (i == idx) {
                good.getChildByName("di2").active = true;
                good.getChildByName("di1").getComponent(Sprite).color = new Color(106, 160, 11);
                good.getChildByName("txt").getComponent(Label).color = new Color(255, 252, 205);
                ts.getChildByName("sp").getComponent(Sprite).color = new Color(235, 55, 176);
                ts.getChildByName("tsTxt").getComponent(Label).color = new Color(255, 252, 205);
            } else {
                good.getChildByName("di2").active = false;
                good.getChildByName("di1").getComponent(Sprite).color = new Color(11, 71, 65);
                good.getChildByName("txt").getComponent(Label).color = new Color(255, 232, 81);
                ts.getChildByName("sp").getComponent(Sprite).color = new Color(247, 163, 30);
                ts.getChildByName("tsTxt").getComponent(Label).color = new Color(131, 14, 27);
            }
        });
    }

    uiPayInit(data) {
        let nk = 1;
        for (const key in data) {
            if (Object.prototype.hasOwnProperty.call(data, key)) {
                if (nk <= 3) {
                    let btn = this.mUI.channls.getChildByName(`btn${nk}`);
                    btn.getChildByName("txt").getComponent(Label).string = `${key}`;
                }
                nk++;
            }
        }
        this.changePayType(this.channlsId);
    }

    changePayType(nk) {
        if (!this.payList) return;

        this.mUI.channls.children.forEach((cell, i) => {
            if (nk == i) {
                cell.getChildByName("di2").active = true;
                cell.getChildByName("txt").getComponent(Label).color = new Color(255, 232, 81);
            } else {
                cell.getChildByName("di2").active = false;
                cell.getChildByName("txt").getComponent(Label).color = new Color(255, 252, 205);
            }
        })
        this.curPayArr = this.payList[this.mUI.channls.getChildByName(`btn${nk + 1}`).getChildByName("txt").getComponent(Label).string];
        this.mUI.payNd.children.forEach(item => {
            item.active = false;
        })
        this.curPayArr.forEach((pay, i) => {
            let pCell = this.mUI.payNd.getChildByName(pay.termsName);
            if (pCell) {
                pCell.active = true;
                if (i == 0) {
                    pCell.getChildByName("di2").active = true;
                    pCell.getComponent(UIOpacity).opacity = 255;
                    this.curPayData = pay;
                } else {
                    pCell.getChildByName("di2").active = false;
                    pCell.getComponent(UIOpacity).opacity = 200;
                }
            }
        })
    }

    tsActive(isB) {
        tools.goodsList.content.forEach((ele, i) => {
            let good = this.mUI.amount.getChildByName(`btn${i + 1}`);
            let ts = good.getChildByName("ts");
            ts.active = isB;
        });
    }

    init(dir = "V") {
        this.curDir = dir;
        this.channlsId = 0;
        this.goldLb.string = tools.convertCentsToYuan(tools.myInfo.userGold);
        this.onGoldChanged(tools.myInfo.userGold);
        this.mUI.ui_dagou.active = true;
        this.isGou = true;
        this.uiPayInit(this.payList);
    }

    onGoldChangedX(data) {
        if (this.goldLb && this.goldLb.string) {
            ui.createNoticeTips(data.OrderPrice, () => {
                this.goldLb.string = tools.convertCentsToYuan(tools.myInfo.userGold);
            })
        }
    }

    onChannels(event, nk) {
        if (event.target.getChildByName("di2").active) return;
        if (event != null) tools.clickManager(event.target);
        this.channlsId = nk - 1;
        this.changePayType(this.channlsId);
    }

    onPayImg(event, nk) {
        if (event.target.getChildByName("di2").active) return;
        if (event != null) tools.clickManager(event.target);
        let nm = event.target.name;
        this.mUI.payNd.children.forEach(cell => {
            if (cell.active) {
                if (nm == cell.name) {
                    cell.getChildByName("di2").active = true;
                    cell.getComponent(UIOpacity).opacity = 255;
                    this.curPayArr.forEach(ele => {
                        if (ele.termsName == nm) this.curPayData = ele;
                    });
                } else {
                    cell.getChildByName("di2").active = false;
                    cell.getComponent(UIOpacity).opacity = 200;
                }
            }
        })
    }

    onPayWay(event) {
        if (event != null) tools.clickManager(event.target);
        let obj = {
            pid: tools.goodsList.content[this.goodsId]["productId"],
            termsId: this.curPayData["termsId"],
            paymentId: this.curPayData["paymentId"],
            hasFirstPayGift: this.isGou ? 1 : 0,
            payPhone: 1234
        };
        this._moneyLogic.requestPayH5(obj, (data) => {
            let orderId = data.orderId;
            if (Hotconfig.hot.isSkipHotUpdate) {
                window.open(`${data.payUrl}`, '_blank');
            } else {
                Market.getInstance().openURL(`${data.payUrl}`);
            }
        });
    }

    onGoodsClick(event, nk) {
        if (event != null) tools.clickManager(event.target);
        this.goodsId = nk - 1;
        this.uiInit(this.goodsId);
    }

    onRecordList(event) {
        if (event != null) tools.clickManager(event.target);
        this.createPopUp("Deposit/DepositList");
    }

    onGuoClick(event) {
        if (event != null) tools.clickManager(event.target);
        this.mUI.ui_dagou.active = !this.mUI.ui_dagou.active;
        this.isGou = this.mUI.ui_dagou.active;
        this.tsActive(this.mUI.ui_dagou.active);
    }


    onEarJi(event: EventTouch) {
        if (event != null) tools.clickManager(event.target);
        if (Hotconfig.hot.isSkipHotUpdate) {
            window.open(tools.googleURL.siteUrl, '_blank');
        } else {
            Market.getInstance().openURL(tools.googleURL.siteUrl);
        }
    }


    onCloseClick(event: EventTouch) {
        if (this.curDir == "H") Market.getInstance().setOrientation("H");
        if (tools.GAME_TYPE == common.GAME_TYPE.GAME) {
            AudioManager.instance?.setSoundSwitch(this.isSound);
            AudioManager.instance?.setMusicSwitch(this.isMusic);
        }
        event.propagationStopped = true;
        director.off("userPaySuccess", this.onGoldChangedX, this);
        this.node.destroy();
    }
}