
import { Component, Node } from "cc";
import { ggLogger } from "db://gg-hot-update/scripts/hotupdate/GGLogger";

//分析UI的后代节点路径
export class UIPath {
    //分析组件子结构
    analyse(scene: Node) {
        //ggLogger.time("AA:--------------");
        let keys = {};
        for (const key in this) {
            if (Object.prototype.hasOwnProperty.call(this, key)) {
                keys['' + key] = true;
            }
        }
        this.traverseNodeTreePath(true, scene, null, (path: string, name: string) => {
            //ggLogger.log("1:",name, path);
            if (keys[name]) {
                //ggLogger.log("2:",name, path);
                if (!this[name]) {
                    this[name] = scene.getChildByPath(path);
                    // if(DEBUG){
                    //ggLogger.log("3", name, path, this[name]);
                    // }
                } else {
                    ggLogger.error("有重复的指定的node.name: ", path);
                }
            }
        });
        //ggLogger.timeEnd("AA:--------------");
        return this;
    }

    traverseNodeTreePath(open: boolean, node, path = null, cb) {
        if (path == null) {
            path = '';
        } else {
            path = path + "/" + node.name;
        }
        cb(path, node.name);
        //
        let baseCom = node.getComponent(Component)
        if (open || !baseCom || baseCom && !baseCom.isRoot) {
            for (let child of node.children) {
                this.traverseNodeTreePath(false, child, path, cb);
            }
        }
    }
}
