import { director } from "cc";
import { JSB } from "cc/env";
import { config } from "../../common/config";
import { PackageId } from "../../common/PackageId";
import { tools } from "../../tools/tools";
import { BaseSocket } from "../BaseSocket";
import { ISocket } from "../ISocket";
import SocketBuffer from "../protocol/SocketBuffer";
import SocketPack from "../protocol/SocketPack";

const HEARTBEAT_INTERVAL = 6000;
const HEARTBEAT_TIMEOUT = (HEARTBEAT_INTERVAL + 4000) * 2;

export class Socket implements ISocket {
    private _ws: WebSocket = null;
    private _connected = false;
    private _delegate: BaseSocket;
    private _socketName: string;
    private _noRecvTime = 0;
    private _heartbeatTimer: any = null;
    private _reconnectTimeout: any = null;
    private _heartbeatPacket = new SocketPack().pack(new SocketBuffer(PackageId.MsgHeartbeat));
    private _lastUrl: string = "";

    // 重连相关
    private _reconnectAttempts = 0;
    private _maxReconnectAttempts = 5;
    private _reconnectDelay = 5000;
    private _autoReconnect = true;
    private _manuallyClosed = false;

    constructor(delegate: BaseSocket, socketName: string) {
        this._delegate = delegate;
        this._socketName = socketName;
    }

    connect(wsProtocol: string, ip: string, port: number) {
        this._lastUrl = `${wsProtocol}://${ip}:${port}`;
        this._manuallyClosed = false;
        this.connectByUrl(this._lastUrl);
    }

    private connectByUrl(url: string) {
        if (this._ws) {
            this._ws.onopen = null;
            this._ws.onmessage = null;
            this._ws.onerror = null;
            this._ws.onclose = null;
            this._ws.close();
            this._ws = null;
        }

        this.cleanup();
        this._delegate.log(this._socketName, `正在连接到 ${url}`, 'log');

        if (JSB && config.ws.head == "wss") {//挂载证书
            this._ws = new (<any>(WebSocket))(url, [], tools.wssCacertUrl);
        } else {
            this._ws = new WebSocket(url);
        }
        
        this._ws.binaryType = "arraybuffer";

        this._ws.onopen = (event) => this.onConnected(event);
        this._ws.onmessage = (event) => this.onMessage(event.data);
        this._ws.onerror = (event) => this.onError(event);
        this._ws.onclose = (event) => this.onClosed(event);
    }

    onConnected(event: Event) {
        this._delegate.log(this._socketName, '连接成功', 'log');
        if (this._reconnectAttempts > 0) {
            this._reconnectAttempts = 0;
            setTimeout(() => {
                this._delegate.onReConnected();
            }, 100)
        }
        this._connected = true;
        this._noRecvTime = 0;
        this._delegate.onConnected();
        setTimeout(() => {
            this.startHeartbeat();
        }, 300)
    }

    onMessage(data: any) {
        this._noRecvTime = 0;
        this._delegate.onMessage(data);
    }

    onError(event: Event) {
        this._delegate.log(this._socketName, 'WebSocket 发生错误', 'error');
        this._connected = false;
        this._delegate.onError();
    }

    onClosed(event?: CloseEvent) {
        this._delegate.log(this._socketName, `WebSocket关闭：${event.code}, ${event.reason}`, 'warn');
        this._connected = false;
        this.cleanup();
        
        const currentSceneName = director.getScene().name;
        if (currentSceneName == "LoginScene") {//在登陆界面不要重连
            this._delegate.onNoReConnected();
            return;
        }

        director.emit("showNetNode");
        director.emit("sendNetClose");
        // 通知业务层关闭
        this._delegate.onClosed();
        if (!this._manuallyClosed && this._autoReconnect && this._reconnectAttempts < this._maxReconnectAttempts) {
            this._reconnectAttempts++;
            this._delegate.log(this._socketName, `第 ${this._reconnectAttempts} 次尝试重连，${this._reconnectDelay} 毫秒后`, 'log');
            this._reconnectTimeout = setTimeout(() => {
                this.connectByUrl(this._lastUrl);
            }, this._reconnectDelay);
        }
    }

    send(data: any) {
        if (!this._ws) return;
        if (this._ws.readyState === WebSocket.OPEN) {
            this._ws.send(data);
        } else {
            this._delegate.log(this._socketName, `发送失败：WebSocket 未处于打开状态`, 'warn');
        }
    }

    close(code: number = 1000, reason: string = "manually close") {
        this._manuallyClosed = true;
        if (this._ws) {
            this._ws.onmessage = null;
            this._ws.close(code, reason);
        }
        this.cleanup();
    }

    isConnected(): boolean {
        if (this._ws) {
            return this._ws.readyState == WebSocket.OPEN;
        }
        return false;
    }

    startHeartbeat() {
        this.stopHeartbeat(); // 避免重复定时器
        this._heartbeatTimer = setTimeout(() => this.scheduleHeartbeat(), HEARTBEAT_INTERVAL);
    }

    private scheduleHeartbeat() {
        if (!this._ws || this._ws.readyState !== WebSocket.OPEN || !this._autoReconnect) return;

        this.send(this._heartbeatPacket);
        this._noRecvTime += HEARTBEAT_INTERVAL;

        if (this._noRecvTime >= HEARTBEAT_TIMEOUT) {
            this._delegate.log(this._socketName, '心跳超时，准备关闭连接', 'warn');
            this.close();
            this.onClosed();
            return;
        }

        this.startHeartbeat();
    }

    private stopHeartbeat() {
        if (this._heartbeatTimer) {
            clearTimeout(this._heartbeatTimer);
            this._heartbeatTimer = null;
        }
    }

    private cleanup() {
        this.stopHeartbeat();

        if (this._reconnectTimeout) {
            clearTimeout(this._reconnectTimeout);
            this._reconnectTimeout = null;
        }

        if (this._ws) {
            this._ws.onopen = null;
            this._ws.onmessage = null;
            this._ws.onerror = null;
            this._ws.onclose = null;
        }
    }

    public retryConnectManually() {
        this._delegate.log(this._socketName, '手动重连中...', 'log');
        if (this._lastUrl) {
            this._autoReconnect = true;
            this._reconnectAttempts = 0;
            this._manuallyClosed = false;
            this.connectByUrl(this._lastUrl);
        }
    }

    public setAutoReconnect(enabled: boolean) {
        this._autoReconnect = enabled;
    }
}
