import { _decorator, assetManager, Component, EventTouch, instantiate, Node, Prefab, Tween, Vec3 } from 'cc';
import { tools } from '../tools/tools';
const { ccclass, property } = _decorator;

@ccclass('Popup')
export class Popup extends Component {
    @property(Node)
    public msgBg: Node | null = null;

    public backFun: Function = null;
    public isEnd: boolean = false;
    onPopUp(_backFun: Function = null) {
        if (this.msgBg) {
            this.msgBg.setScale(new Vec3(0, 0, 0));
            new Tween(this.msgBg)
                .to(0.3, { scale: new Vec3(1, 1, 1) }, { easing: 'backOut' })
                .call(() => {
                    this.backFun = _backFun;
                })
                .start();
        }
    }

    onCloseBtnClick(event: EventTouch) {
        event.propagationStopped = true;
        this.isEnd = true;
        if (this.msgBg) {
            new Tween(this.msgBg)
                .to(0.3, { scale: new Vec3(0, 0, 0) })
                .call(() => {
                    this.node.destroy();
                })
                .start();
        }
    }

    //加载预制体
    addLayer(name: string, parent, callback = null, isProg: boolean = false) {
        if (!name || name == "" || !parent) {
            if (callback) callback(null);
            return;
        }
        let bundle = assetManager.getBundle("Lobby");
        if (bundle) {
            let path = "res/prefab/" + name;
            let ass = bundle.get(path, Prefab);
            if (ass) {
                let layer = instantiate(ass);
                layer.parent = parent;
                if (callback) callback(layer);
            } else {
                bundle.load("res/prefab/" + name, Prefab, (err, prefab) => {
                    if (err) {
                        if (callback) callback(null);
                        return;
                    }
                    let layer = instantiate(prefab);
                    layer.parent = parent;
                    if (callback) callback(layer);
                });
            }
        } else {
            if (callback) callback(null);
        }
    }

    //加载弹窗预制体
    createPopUp(name: string, callback = null) {
        if (!name || name == "") {
            if (callback) callback(null);
            return;
        }
        let bundle = assetManager.getBundle("Lobby");
        if (bundle) {
            let path = "res/prefab/" + name;
            let ass = bundle.get(path, Prefab);
            if (ass) {
                let layer = instantiate(ass);
                layer.parent = tools.topLayer;
                layer.getComponent(Popup).onPopUp(callback);
                if (callback) callback(layer);
            } else {
                bundle.load("res/prefab/" + name, Prefab, (err, prefab) => {
                    if (err) {
                        if (callback) callback(null);
                        return;
                    }
                    let layer = instantiate(prefab);
                    layer.parent = tools.topLayer;
                    layer.getComponent(Popup).onPopUp(callback);
                    if (callback) callback(layer);
                });
            }
        } else {
            if (callback) callback(null);
        }
    }

    onClose(event: EventTouch=null) {
        if (this.msgBg) {
            new Tween(this.msgBg)
                .to(0.3, { scale: new Vec3(0, 0, 0) })
                .call(() => {
                    this.node.active = false;
                })
                .start();
        }
    }
}
