import { _decorator, Color, color, director, EditBox, EventKeyboard, Graphics, Input, input, KeyCode, Node, UIOpacity, UITransform, Vec2 } from 'cc';
import { ggLogger } from 'db://gg-hot-update/scripts/hotupdate/GGLogger';

const { ccclass } = _decorator;

@ccclass('CMDManager')
export class CMDManager {
    private static cmds: { [key: string]: any } = {};
    private static isAddListener: boolean = false;
    private static editNode: Node | null = null;
    private static editLabel: EditBox | null = null;

    /** 是否允许使用CMD */
    public static Initialize() {
        input.on(Input.EventType.KEY_DOWN, this.onKeyDown, this);
    }

    public static AddCMD(cmd: string, fun: Function, target?: any): void {
        this.cmds[cmd] = { fun: fun, target: target };
        if (this.isAddListener) return;
        this.isAddListener = true;
    }

    private static onKeyDown(evt: EventKeyboard): void {
        if (evt.keyCode === KeyCode.TAB) {
            if (this.editNode === null || this.editNode.parent === null) {
                if (this.editNode === null) {
                    this.createCMDEdit();
                } else {
                    this.editNode.getComponent(Graphics).color = color(Math.random() * 255, Math.random() * 255, Math.random() * 255);
                    director.getScene().getChildByName("Canvas").addChild(this.editNode);
                    this.editLabel.setFocus();
                }
            }
        }
    }

    private static createCMDEdit(): void {
        // 创建一个新的节点作为 EditBox 的容器
        const labelNode = new Node();
        labelNode.addComponent(UITransform);
        labelNode.addComponent(UIOpacity);
        this.editLabel = labelNode.addComponent(EditBox);

        // 创建一个新的 Graphics 节点用于绘制背景
        const graphics = new Node().addComponent(Graphics);
        this.editNode = graphics.node;
        this.editNode.addComponent(UITransform);
        this.editNode.name = "CMDEdit";
        this.editNode.addComponent(UIOpacity);
        // 设置背景颜色
        graphics.clear();
        graphics.fillColor = new Color(
            Math.random() * 255,
            Math.random() * 255,
            Math.random() * 255,
            255
        );
        const size = new Vec2(350, 200);
        graphics.fillRect(-size.x * 0.5, -size.y * 0.5, size.x, size.y);
        this.editNode.getComponent(UITransform).setContentSize(size.x, size.y);
        this.editNode.getComponent(UIOpacity).opacity = 125;

        // 设置 EditBox 的尺寸
        labelNode.getComponent(UITransform).setContentSize(250, 45);
        this.editNode.addChild(labelNode);
        labelNode.getComponent(UIOpacity).opacity = 255;

        // 设置 EditBox 的属性
        if (this.editLabel.textLabel) {
            this.editLabel.textLabel.fontSize = 40;
            this.editLabel.textLabel.color = Color.WHITE;
        }
        this.editLabel.maxLength = 50;
        this.editLabel.placeholder = ' ';
        this.editLabel.inputMode = EditBox.InputMode.SINGLE_LINE;

        // 添加 'editing-return' 事件监听
        labelNode.on('editing-return', this.onEditEnter, this);

        // 将 editNode 添加到场景的 Canvas 节点下
        const canvas = director.getScene()?.getChildByName('Canvas');
        if (canvas) {
            canvas.addChild(this.editNode);
        } else {
            ggLogger.error('Canvas 节点未找到');
        }

        // 设置焦点
        setTimeout(() => this.editLabel.setFocus(), 10);
    }

    private static onEditEnter(evt?: any): void {
        this.onExcuteCMD();
    }

    private static onExcuteCMD(): void {
        if (this.editLabel) {
            const str = this.editLabel.string.trim();
            this.editLabel.string = "";
            if (this.editNode?.parent) {
                this.editNode.removeFromParent();
            }
            if (str.length === 0) return;
            const sArr = str.split(",");
            const cmd = sArr.shift();
            if (cmd) {
                this.Excect(cmd, sArr);
            }
        }
    }

    public static Excect(cmd: string, args: any[]): void {
        const o = this.cmds[cmd];
        if (o == null) return;
        const fun: Function = o.fun;
        while (fun.length !== args.length) {
            if (args.length > fun.length) args.pop();
            if (args.length < fun.length) args.push(null);
        }
        fun.apply(o.target, args);
    }
}