// declare const protobuf:any;
/**登祟pb信息 */
export class LoginPbData {
    public static _instance: LoginPbData = null!;

    private pb = null!;

    constructor() { }

    public static getInstance(): LoginPbData {
        if (this._instance === null) {
            this._instance = new LoginPbData();
        }
        return this._instance;
    }

    public static destroyInstance(): void {
        if (this._instance) {
            delete this._instance;
            this._instance = null;
        }
    }

    public setLoginPb(pb) {
        this.pb = pb;
    }

    public getLoginPb() {
        return this.pb;
    }
}
