import { tools } from "../tools/tools";

/**数据通知*/
export class DataNotify {
    private static _instance: DataNotify = null;
    private _uiList = [];

    addListener(ui) {
        for (let i = 0; i < this._uiList.length; i++) {
            if (ui === this._uiList[i]) {
                return;
            }
        }
        this._uiList.push(ui);
    }

    removeListener(ui) {
        for (let i = 0; i < this._uiList.length; i++) {
            if (ui === this._uiList[i]) {
                this._uiList.splice(i, 1);
                break;
            }
        }
    }

    //金币发生改变
    onGoldChanged(userGold) {
        tools.myInfo.userGold = userGold;
        for (let i = 0; i < this._uiList.length; i++) {
            this._uiList[i].onGoldChanged(userGold);
        }
    }

    //银行钱发生变化
    onBankChanged(userBank) {
        tools.myInfo.userBank = userBank;
        for (let i = 0; i < this._uiList.length; i++) {
            this._uiList[i].onBankChanged(userBank);
        }
    }

    //名字发生变化
    onNameChanged(userName) {
        tools.myInfo.userName = userName;
        for (let i = 0; i < this._uiList.length; i++) {
            this._uiList[i].onNameChanged(userName);
        }
    }

    onAvataChanged(path) {
        tools.myInfo.userAvataUrl = path;
        for (let i = 0; i < this._uiList.length; i++) {
            this._uiList[i].onAvataChanged(path);
        }
    }

    //语言
    onLanguageChange(languageType) {
        for (let i = 0; i < this._uiList.length; i++) {
            this._uiList[i].onLanguageChange(languageType);
        }
    }

    //代理
    onAgentChanged(data) {
        for (let i = 0; i < this._uiList.length; i++) {
            this._uiList[i].onAgentChanged(data);
        }
    }

    onTurntableChange(turnTableData) {
        for (let i = 0; i < this._uiList.length; i++) {
            this._uiList[i].onTurntableChange(turnTableData);
        }
    }

    onWithdrawRecordChange(list) {
        for (let i = 0; i < this._uiList.length; i++) {
            this._uiList[i].onWithdrawRecordChange(list);
        }
    }

    onWithdrawBindListChange() {
        for (let i = 0; i < this._uiList.length; i++) {
            this._uiList[i].onWithdrawBindListChange();
        }
    }

    onFreeWithdrawLimitChange(GiftCredit, Credit) {
        for (let i = 0; i < this._uiList.length; i++) {
            this._uiList[i].onFreeWithdrawLimitChange(GiftCredit, Credit);
        }
    }

    onWithdrawCoinChange(msg) {
        for (let i = 0; i < this._uiList.length; i++) {
            this._uiList[i].onWithdrawCoinChange(msg);
        }
    }

    onBonusInfoChanged(msg) {
        for (let i = 0; i < this._uiList.length; i++) {
            this._uiList[i].onBonusInfoChanged(msg);
        }
    }

    static getInstance(): DataNotify {
        if (null == this._instance) {
            this._instance = new DataNotify();
        }
        return this._instance;
    }
    static destroyInstance() {
        if (this._instance) {
            delete this._instance;
            this._instance = null;
        }
    }
}
