import { _decorator, Component, Label, Node, tween, UITransform, Vec3 } from 'cc';

const { ccclass, property } = _decorator;

@ccclass('MsgTips')
export class MsgTips extends Component {
    @property(Node)
    private Layout_Bg: Node | null = null;

    @property(Node)
    private tipsBg: Node | null = null;

    @property(Label)
    private Label_Text: Label | null = null;

    onLoad() {
        if (this.tipsBg) {
            this.tipsBg.active = false;
        }
    }

    setMsg(msgText: string, callback: Function | null = null) {
        if (!this.Label_Text || !this.tipsBg) return;

        // 直接赋值，无需 getComponent
        this.Label_Text.string = msgText;

        // 适配 Label 宽度
        this.tipsBg.getComponent(UITransform).width = this.Label_Text.getComponent(UITransform).width;

        // 显示背景
        this.tipsBg.active = true;

        if (this.Layout_Bg) {
            tween(this.Layout_Bg)
                .by(0.3, { position: new Vec3(0, 30, 0) })
                .delay(2.2)
                .call(() => {
                    if (callback) callback();
                    this.node.destroy();
                })
                .start();
        }
    }
}
