import { director } from "cc";
import { ggLogger } from "db://gg-hot-update/scripts/hotupdate/GGLogger";
import { GameFrame } from "../base/GameFrame";
import { common } from "../common/common";
import { PackageId } from "../common/PackageId";
import { BaseLogic } from "../logic/BaseLogic";
import { LoginLogic } from "../logic/LoginLogic";
import { OneSocket } from "../net/OneSocket";
import { tools } from "../tools/tools";
import { GameManager } from "./GameManager";
import { LobbyManager } from "./LobbyManager";

/**房间管理器 */
export class RoomManager {
    private static _instance: RoomManager = null;
    private _lobbyLogic: BaseLogic = new BaseLogic();
    public _loginLogic: LoginLogic = new LoginLogic();
    private _gameFrame: GameFrame = null;
    private _roomInfo = null;
    public myInfo: any = {};

    constructor() {
        //房间重连及消息处理
        director.on("onRoomConnect", () => {
            director.emit("clearNetData");
            this.onReconnect();
        }, this);
    }

    appointFrame(gameFrame: GameFrame) {
        tools.gameFrame = gameFrame;
        this._gameFrame = gameFrame;
    }

    getGameFrame(): GameFrame {
        return this._gameFrame;
    }

    getRoomInfo() {
        return this._roomInfo;
    }

    clear() {
        this._gameFrame = null;
        this._roomInfo = null;
        this.myInfo = {};
    }

    close(code?: number, reason?: string) {
        OneSocket.getInstance().close(code, reason);
    }

    isConnected(): boolean {
        return OneSocket.getInstance().isConnected();
    }

    sendData(requestId: PackageId, data: Uint8Array, responseId: PackageId = PackageId.NORESPONSEID, callbackFun = null) {
        LobbyManager.getInstance().sendData(requestId, data, responseId, callbackFun);
    }

    checkSocketConnect() { }

    async onReconnect() {
        let token = tools.getToken();
        if (!token) token = common.TOKEN;
        let gameID = GameManager.getInstance().getGameID();
        if (!common.ISH5DIRECT) {
            this._loginLogic.onTokenGame(token, gameID, 1, () => {
                director.emit("hideNetNode");
                if (this._gameFrame && this._gameFrame.dealReConnectSuccess) {
                    ggLogger.log("==================游戏重连成功============");
                    director.emit("clearNetData");
                    this._gameFrame.dealReConnectSuccess();
                }
            });
        } else {
            this._loginLogic.onTokenH5Game(token, gameID, 1, () => {
                director.emit("hideNetNode");
                if (this._gameFrame && this._gameFrame.dealReConnectSuccess) {
                    ggLogger.log("==================游戏重连成功============");
                    director.emit("clearNetData");
                    this._gameFrame.dealReConnectSuccess();
                }
            });
        }
    }


    bindingNetCallback(mainID: number, callbackFun) {
        OneSocket.getInstance().bindingNetCallback(mainID, callbackFun);
    }

    removeNetCallback(mainID: number) {
        OneSocket.getInstance().removeNetCallback(mainID);
    }

    static getInstance(): RoomManager {
        if (null == this._instance) {
            this._instance = new RoomManager();
        }
        return this._instance;
    }

    static destroyInstance() {
        if (this._instance) {
            delete this._instance;
            this._instance = null;
        }
    }
}