// declare const protobuf:any;
/**登祟pb信息 */
export class WebPbData {
    public static _instance: WebPbData = null!;

    private pb = null!;

    constructor() { }

    public static getInstance(): WebPbData {
        if (this._instance === null) {
            this._instance = new WebPbData();
        }
        return this._instance;
    }

    public static destroyInstance(): void {
        if (this._instance) {
            delete this._instance;
            this._instance = null;
        }
    }

    public setLobbyPb(pb) {
        this.pb = pb;
    }

    public getLobbyPb() {
        return this.pb;
    }
}
