import { _decorator, Component, Node, Label, Tween, Vec3, EventTouch, Color, Sprite } from 'cc';
import { i18n_language } from '../i18n/LanguageData';
const { ccclass, property } = _decorator;

@ccclass('MsgBox')
export class MsgBox extends Component {
    @property(Node)
    private msgLabel: Node | null = null;

    @property(Node)
    private sureBtn: Node | null = null;

    @property(Node)
    private cancelBtn: Node | null = null;

    @property(Node)
    private msgBg: Node | null = null;

    private _callback: ((result: number) => void) | null = null;

    protected onLoad(): void {
        if (i18n_language == "ar") this.cancelBtn.getComponent(Sprite).color = Color.WHITE;
    }

    setMsg(msgText: string, callback: ((result: number) => void) | null = null, btnType: number = 1) {
        if (this.msgLabel) {
            const labelComponent = this.msgLabel.getComponent(Label);
            if (labelComponent) {
                labelComponent.string = msgText;
            }
        }

        this._callback = callback;


        if (btnType === 1 && this.sureBtn && this.cancelBtn) {
            const sureBtnPos = this.sureBtn.getPosition();
            this.sureBtn.setPosition(new Vec3(0, sureBtnPos.y, sureBtnPos.z));
            this.cancelBtn.active = false;
        }

        if (this.msgBg) {
            this.msgBg.setScale(new Vec3(0, 0, 0));
            new Tween(this.msgBg)
                .to(0.3, { scale: new Vec3(1, 1, 1) }, { easing: 'backOut' })
                .start();
        }
    }

    onSureBtnClick(event: EventTouch) {
        event.propagationStopped = true;

        if (this._callback) {
            this._callback(2);
        }

        if (this.msgBg) {
            new Tween(this.msgBg)
                .to(0.3, { scale: new Vec3(0, 0, 0) })
                .call(() => {
                    this.node.destroy();
                })
                .start();
        }
    }

    onCancelBtnClick(event: EventTouch) {
        event.propagationStopped = true;
        if (this._callback) {
            this._callback(1);
        }

        if (this.msgBg) {
            new Tween(this.msgBg)
                .to(0.3, { scale: new Vec3(0, 0, 0) })
                .call(() => {
                    this.node.destroy();
                })
                .start();
        }
    }

    onCloseBtnClick(event: EventTouch) {
        event.propagationStopped = true;

        if (this.msgBg) {
            new Tween(this.msgBg)
                .to(0.3, { scale: new Vec3(0, 0, 0) })
                .call(() => {
                    this.node.destroy();
                })
                .start();
        }
    }
}
