
import { ggLogger } from 'db://gg-hot-update/scripts/hotupdate/GGLogger';
import { GameFrame } from '../../Lobby/src/base/GameFrame';
import { tools } from '../../Lobby/src/tools/tools';
//import { AuthRequestHelper } from '../../Lobby/src/tools/AuthRequestHelper';

declare const protobuf: any;

export class GameTempLogic extends GameFrame {
    private pb: any = null;
    public gameName: string = "";
    protected gameUI: any = null;
    private slotMgr: any = null;
    private slotConfig: any = null;
    constructor(gameUI, msgIdList, pbTextAsset, slotMgr, slotConfig) {
        super(gameUI, { seatCount: 1, msgIdList: msgIdList });
        this.gameUI = gameUI;
        if (pbTextAsset) this.pb = protobuf.parse(pbTextAsset);
        this.gameName = slotConfig.curBundleName;
        this.slotMgr = slotMgr;
        this.slotConfig = slotConfig;
    }
    requestBetGradeSc() {
        if (this.isTest) {
            return this.getScreenData();
        } else {
            return this.decodeMgr(this.pb, "ResponseScreen", tools.screeninfo) ?? { info: { BetGrade: [] } };
        }
    }
    //玩家押注请求 
    requestBet(BetGold: number) {
        if (!this.isTest) {
            let buf = this.encodeMgr(this.pb, 'RequestBet', {
                BetGradeId: this.slotMgr.curBetIndex + 1,
                BetGold: BetGold,
                Level: this.slotMgr.difficultLevel,
                Rows: this.slotMgr.gameRow,
            });
            //this.roomFrame.sendData(this.slotConfig.messageIds.MsgRequstBet, buf);
            /*AuthRequestHelper.buddyBallsIndex((data) => {
                this.dealGameMessage(data);
            });*/
            const requestId = crypto.randomUUID();
            window.parent.postMessage(
                { source: "buddyball", type: "GetBall", requestId },
                window.location.origin
            );
            return;
        }
        ggLogger.log("requestBet");
        let data = this.getResponseBetData();
        this.dealGameMessage(data);
    }
    async dealGameMessage(msg) {
        if (this.isTest) {
            await this.slotMgr.sleep(0.1);
            let msgID = msg["msgId"];
            
            if (msgID == this.slotConfig.messageIds.MsgResponseBet) {
                let info = msg.data;
                await this.gameUI.responseBetData(info);
            }
        } else {
            this.gameUI.responseBetData(msg);
        }
    }

    dealReConnectSuccess() {
        ggLogger.log(`${this.slotConfig.curBundleName}  reconnect success`);
    }
    dealGetPayGold(userGold: number) {
    }

    //**********************************测试数据方法  start********************************** */
    public isTest: boolean = false;//是否为测试
    private getScreenData() {
        const data = {
            BetGrade: [
                { Id: 1, Gold: 50 },
                { Id: 2, Gold: 100 },
                { Id: 3, Gold: 200 },
                { Id: 4, Gold: 300 },
                { Id: 5, Gold: 500 },
                { Id: 6, Gold: 1000 },
                { Id: 7, Gold: 1500 },
                { Id: 8, Gold: 2000 },
                { Id: 9, Gold: 3000 },
                { Id: 10, Gold: 5000 }
            ]
        };
        return data;
    }

    private getResponseBetData() {
        const data = {
            NewGold: 19545453,
            CommonAwardScore: 10000,
            Mul: this.slotMgr.getRandomMultipleData(),
            data:{location: 8},
            code: 0,
        }
        let msg = {
            data: data,
            msgId: this.slotConfig.messageIds.MsgResponseBet,
        }
        return msg;
    }
    //**********************************以上测试数据方法  end********************************** */
}