import { director } from "cc";
import { ggLogger } from "db://gg-hot-update/scripts/hotupdate/GGLogger";
import { tools } from "../../tools/tools";
import SocketBuffer from "./SocketBuffer";

export default class SocketPack {
    public sendKey: number = 0;
    public recvKey: number = 0;
    private headLength: number = 10;
    private maxPackageSize: number = 16384;

    public getHeadLen(): number {
        return this.headLength;
    }

    /**合并数据包 */
    public pack(msg: SocketBuffer): Uint8Array {
        const buffer = new ArrayBuffer(this.headLength + msg.getData().length);
        const dataView = new DataView(buffer);
        let offset = 0;

        dataView.setUint32(offset, msg.getMsgId(), true);
        offset += 4;

        if (this.headLength === 22) {
            dataView.setUint32(offset, msg.getUserId(), true);
            offset += 4;
            msg.setUserConnId(Number(dataView.getBigInt64(offset, true)));
            offset += 8;
        }

        dataView.setUint8(offset, msg.getEncryptType());
        offset += 1;
        let data = msg.getData();
        let checkCode: number = 0;
        if (msg.getEncryptType() == 2 || msg.getEncryptType() == 6) {
            [data, checkCode] = this.mapSendOx(data);
        }
        if (msg.getEncryptType() == 6 || msg.getEncryptType() == 4) {
            data = this.xorSendOx(data);
        }

        dataView.setUint8(offset, checkCode);
        offset += 1;
        dataView.setUint32(offset, msg.getMsgLen(), true);
        offset += 4;

        const result = new Uint8Array(buffer);
        result.set(data, offset);

        return result;
    }

    /**分解数据包 */
    public unpack(data: ArrayBuffer): SocketBuffer {
        const result = new Uint8Array(data);
        const dataView = new DataView(result.buffer);
        let offset = 0;
        let msg: SocketBuffer = new SocketBuffer();
        msg.setMsgId(dataView.getUint32(offset, true));
        offset += 4;

        if (this.headLength === 22) {
            msg.setUserId(dataView.getUint32(offset, true));
            offset += 4;
            msg.setUserConnId(Number(dataView.getBigInt64(offset, true)));
            offset += 8;
        }

        msg.setEncryptType(dataView.getUint8(offset));
        offset += 1;
        msg.setCheckCode(dataView.getUint8(offset));
        offset += 1;
        msg.setMsgLen(dataView.getUint32(offset, true));
        offset += 4;

        if (msg.getMsgLen() > this.maxPackageSize) {
            ggLogger.error("Packet too large包太长");
            return null;
        }
        msg.setData(result.slice(offset));
        //解密数据转化为Uint8Array
        const decrypted = this.dataDecrypt(msg);
        if (!decrypted) {
            director.emit("deelDataFail", msg.getMsgId());
            ggLogger.warn(`unpack: 解密失败，msgId=${msg.getMsgId()}`);
            return null;
        }

        return decrypted;
    }

    public dataDecrypt(msg: SocketBuffer): SocketBuffer {
        let data = msg.getData();
        if (msg.getEncryptType() == 6 || msg.getEncryptType() == 4) {
            data = this.xorReceiveOx(data);
        }
        if (msg.getEncryptType() == 2 || msg.getEncryptType() == 6) {
            const mapped = this.mapReceiveOx(data, msg.getCheckCode());
            data = mapped;
        }

        msg.setData(data);
        return msg;
    }

    // 发送包映射
    public mapSendOx(data: Uint8Array): [Uint8Array, number] {
        let checkCode = 0;
        const mappedData = new Uint8Array(data.length);
        for (let i = 0; i < data.length; i++) {
            checkCode = (checkCode + data[i]) & 0xFF; // 保持8位溢出
            mappedData[i] = tools.mapSend[data[i]];
        }
        // 取反加一，计算补码
        checkCode = (~checkCode + 1) & 0xFF;
        return [mappedData, checkCode];
    }

    // 接受包映射
    public mapReceiveOx(data: Uint8Array, checkCode: number): Uint8Array | null {
        let calculatedCheckCode = 0;
        const mappedData = new Uint8Array(data.length);
        for (let i = 0; i < data.length; i++) {
            const vl = tools.mapReceive[data[i]]; // 使用接收映射
            mappedData[i] = vl; // 更新数据
            calculatedCheckCode = (calculatedCheckCode + vl) & 0xFF; // 重新计算校验码
        }
        // 取补码
        calculatedCheckCode = (~calculatedCheckCode + 1) & 0xFF;
        return mappedData; // 返回解密后的数据
    }
    //异或发送加密
    public xorSendOx(data: Uint8Array): Uint8Array {
        for (let i = 0; i < data.length; i++) {
            data[i] ^= this.sendKey;
            this.sendKey = (this.sendKey * i + 0x70) % 0xFF;
        }
        return data;
    }
    //异或接收解密
    public xorReceiveOx(data: Uint8Array): Uint8Array {
        for (let i = 0; i < data.length; i++) {
            data[i] ^= this.recvKey;
            this.recvKey = (this.recvKey * i + 0x70) % 0xFF;
        }
        return data;
    }
}
