import { PackageId } from '../common/PackageId';
import { LobbyManager } from '../data/LobbyManager';
import { ProtoMgr } from '../data/ProtoMgr';
import { RoomManager } from '../data/RoomManager';
import { BaseLogic } from '../logic/BaseLogic';
import { OneSocket } from '../net/OneSocket';
import SocketBuffer from '../net/protocol/SocketBuffer';
import { tools } from '../tools/tools';

/**游戏里逻辑层的基类，负责处理游戏逻辑，包括游戏状态，玩家信息，游戏数据等 */
export abstract class GameFrame {
    protected gameUI: any = null;
    protected roomFrame = RoomManager.getInstance();
    private _logicInfo: any = null;
    private _lobbyLogic: BaseLogic = new BaseLogic();
    private _isReConnectting: boolean = false;

    private _seatOffset = 0;
    private _seatNO: number = 0;

    public get isReConnectting() {
        return this._isReConnectting;
    }
    public set isReConnectting(bRec: boolean) {
        this._isReConnectting = bRec;
    }

    // 构造函数，初始化游戏UI和逻辑信息
    constructor(...params: any) {
        this.gameUI = params[0];
        this._logicInfo = params[1];
        if (this._logicInfo.playInfo) {
            this._seatOffset = 0;
        } else {
            this.roomFrame.appointFrame(this);
            if (this._logicInfo.seatOffset) {
                this._seatOffset = this._logicInfo.seatOffset;
            } else {
                this._seatOffset = -this.getMySeatNO() + 1;
            }
            this.bindingGameMsgCallback();
        }
    }
    // 绑定游戏消息回调，遍历消息ID列表并为每个消息ID绑定处理函数
    private bindingGameMsgCallback() {
        if (this._logicInfo.msgIdList) {
            for (const key in this._logicInfo.msgIdList) {
                const msgID = this._logicInfo.msgIdList[key];
                this.roomFrame.bindingNetCallback(msgID, this.dealGameMessage.bind(this));
            }
        }
    }

    // 移除游戏消息回调，遍历消息ID列表并移除每个消息ID的回调函数
    removeGameMsgCallback() {
        if (this._logicInfo.msgIdList) {
            for (const key in this._logicInfo.msgIdList) {
                const msgID = this._logicInfo.msgIdList[key];
                this.roomFrame.removeNetCallback(msgID);
            }
        }
    }

    requestLeaveRoom() {
        this._lobbyLogic.sendData(PackageId.MsgRequstLeaveRoom, null);
        this.gameUI.onLeaveRoom();
    }


    requestChangeTable() {
        //没有消息体
        // let data = ProtoMgr.getInstance().encodeLobbyFrameMgr("RequestEnterRoom", {
        //     user: user
        // });
        this._lobbyLogic.sendData(PackageId.MsgRequstChangeTable, null);
    }

    // 获取当前用户的ID
    getMyUserID() {
        // return this.roomFrame.myInfo.userID;
        return tools.myInfo.userID;
    }

    // 获取游戏UI
    getGameUI() {
        return this.gameUI;
    }

    //返回用户所有信息
    getGameUserInfo() {
        return tools.myInfo;
    }

    // 获取当前用户的用户名
    getMyUserName() {
        return tools.myInfo.userName;
    }

    // 获取当前用户的金币数量
    getMyUserGold() {
        return tools.myInfo.userGold;
    }

    // 设置当前用户的金币数量
    setMyUserGold(num) {
        tools.myInfo.userGold = num;
    }

    // 获取当前用户的头像ID
    getMyAvataID() {
        return tools.myInfo.userAvataUrl;
    }

    // 获取当前用户的头像URL
    getMyAvataUrl() {
        return tools.myInfo.userAvataUrl;
    }

    // 获取房间信息
    getRoomInfo() {
        return this.roomFrame.getRoomInfo();
    }

    // 获取vip流水信息
    getBetScore() {
        return tools.myInfo.betScore;
    }

     getBetVip() {
        return tools.myInfo.VipPoint;
    }

    // 私有方法，返回大厅
    backLobby() {
        this.roomFrame.clear();
        this.gameUI.backLobby(null);
    }
    //返回登陆
    backLogin() {
        this.roomFrame.clear();
        this.gameUI.backLogin(null);
    }

    // 比赛场大结算
    onMatchGameEnd() { }

    // 编码消息管理器
    encodeMgr(pb, msgName, msgBody?): Uint8Array {
        return ProtoMgr.getInstance().encodeMgr(pb, msgName, msgBody);
    }

    // 解码消息管理器
    decodeMgr(pb, msgName, msgBuf: Uint8Array): any {
        return ProtoMgr.getInstance().decodeMgr(pb, msgName, msgBuf);
    }

    // 处理游戏显示
    onGameShow() {
        this.roomFrame.checkSocketConnect();
    }

    // 请求用户金币
    requestWealth() {
        let msg = new SocketBuffer(PackageId.MsgResponseWealth);
        let buf = OneSocket.getInstance().packData.pack(msg);
        LobbyManager.getInstance().sendData(PackageId.MsgRequestWealth, buf);
    }

    // 获取当前用户的座位号
    getMySeatNO() {
        return this._seatNO;
    }

    // 设置当前用户的座位号
    setMySeatNO(seatID: number) {
        this._seatNO = seatID;
    }

    // 解码游戏消息
    abstract dealGameMessage(obj: any);
    // 处理重连成功
    abstract dealReConnectSuccess();
    // 处理获取金币
    abstract dealGetPayGold(userGold: number);
}
