class m_slotMgr {

    public gm: ComManage = null;
    public gameLogic: any = null;
    public betGrade: { Id: number; Gold: number }[] = [];
    public myInfo: MyInfo = null;
    public userMoney: number = 0;
    public userMoneyNew: number = 0;
    public betGradeScData: any = null;
    public betList: number[] = [200, 5000, 20000, 50000];
    //难度等级 1 2 3
    public difficultLevel: number = 0;
    //排数 别针排数 8 10 12 14
    public gameRow: number = 0;
    public rowType: number = 0;
    //是否手动
    public isAuto: boolean = false;
    //自动压住剩余次数
    public autoBetCount: number = 0;
    public curBetIndex = 0;
    public curBet = 1;
    public curToggleIndex: number = 1;
    //押注结果
    serverData: any = null;
    rewardID: number = -1;
    //历史记录
    historyData: any = [];
    //历史记录 最大显示个数
    historyMax: number = 6;
    //高倍率 提示界限
    hightMultiple: number = 20;

    public autoOrManualModeIndex: autoOrManualMode = autoOrManualMode.manual;

    public betCounToggleIndex: number = 0

    public GameMainCmp: any = null;

    public initGameManager(logic: any, mainCmp: any) {
        this.clear();
        this.gm = new ComManage();
        this.gm.onclear();
        this.gm.isGame = true;
        this.gm.bundle = slotConfig.curBundleName;;
        this.gm.defaultAudioUrl = "res/audio/";

        this.gameLogic = logic;
        this.GameMainCmp = mainCmp;
        this.myInfo = logic.getGameUserInfo();
        this.userMoney = this.myInfo.userGold;
        this.userMoneyNew = this.myInfo.userGold;
        this.onUpdateMoney();

        /*AuthRequestHelper.buddyBallsIndex((data) => {
            console.log("AuthRequestHelper.buddyBallsIndex success", data);
        }, (error) => {
            console.log("AuthRequestHelper.buddyBallsIndex error", error);
        });*/
        //this.setBetGradeSc();
    }



    /*获取服务器消息*/
    public onListenServerData(msg: any) {
        this.userMoneyNew = 0;
        let data = {
            Mul: {Value: msg.location,Index: GameTempCore.GetMultiIndex(msg.location)}
        }
        // this.userMoney = data.NewGold;
        let multiple = data.Mul ?? null;
        this.serverData = data;
        this.rewardID = multiple.Index ?? 0;
    }

    // 退出游戏的时候， 清空数据
    public clear() {
        this.difficultLevel = 0;
        this.gameRow = 0;
        this.autoBetCount = 0;
        this.isAuto = false;
        this.serverData = null;
        this.historyData = [];
    }

    /*** 更新金币*/
    public onUpdateMoney() {
        // this.gm.emit(slotConfig.eventNames.onEventUpdateUserMoney, this.userMoney);
        this.gm.emit(slotConfig.eventNames.onEventUpdateUserMoney, this.userMoneyNew);
    }

    /** 设置下注列表*/
    public setBetGradeSc() {
        let info = this.gameLogic.requestBetGradeSc();
        this.betGradeScData = info;
        this.betGrade = info?.BetGrade ?? [{ Id: 1, Gold: 1 }, { Id: 2, Gold: 2 }, { Id: 3, Gold: 3 }, { Id: 4, Gold: 5 }];
        const length = this.betGrade.length;
        let index = 0;
        for (let i = 0; i < length; i++) {
            let ele = this.betGrade[i];
            let gold = ele.Gold ?? 0;
            if (gold <= 0) continue;
            // this.betList[index] = ele.Gold * tools.RATE; //根据服务器设置
            this.betList[index] = ele.Gold
            index++;
        }
        this.betGradeScData.MaxBet = this.betList[index];
        this.betGradeScData.MinBet = this.betList[0];
        // console.log("setBetGradeSc = ", info);
        this.reSetMaxBet();
    }

    //随机获取当前的倍率
    public getRandomMultipleData() {
        let multiples = slotConfig.multipleTable["11"]["1"];
        let random = Math.floor(Math.random() * multiples.length);//[0, multiples.length-1]
        random = 5;
        let data = {
            Index: random + 1,
            Value: multiples[random]
        }
        return data;
    }

    // 如果multiples = [5.6, 2.1, 1.1, 1, 0.5, 1, 1.1, 2.1, 5.6],输入5.6 那么indexs = [0,8] 
    public getMultipleIndexes(multiple: number): number[] {
        const multiples = slotConfig.multipleTable[`${this.gameRow}`][`${this.difficultLevel}`];
        const EPS = 0.0001;
        return multiples.reduce<number[]>((arr, v, i) => {
            if (Math.abs(v - multiple) < EPS) arr.push(i);
            return arr;
        }, []);
    }

    //设置自动投注的次数
    setAutoBetCount(count: number) {
        this.autoBetCount = count;
    }

    //自动投注结束
    isAutoBetOver() {
        return !this.isAuto || this.autoBetCount <= 0;
    }

    //设置自动or手动
    setAutoOrManual(isAuto: boolean) {
        this.isAuto = isAuto;
    }

    setAutoOrManualModel(index) {
        this.autoOrManualModeIndex = index;
    }

    isAtuoMode() {
        return this.autoOrManualModeIndex == autoOrManualMode.auto;
    }

    //设置别针排数
    setGameRow(Row: any) {
        if (Row != this.gameRow) {
            // ggLogger.log("setGameRow111111");
            this.gameRow = Row;
            this.rowType = slotConfig.rowList.indexOf(Row);
            this.gm.emit(slotConfig.eventNames.changeGameRow);
        }
    }

    //设置难度
    setDifficultLevel(level: number = 1) {
        if (level != this.difficultLevel) {
            this.difficultLevel = level;
            this.gm.emit(slotConfig.eventNames.changeGameDifficultLevel);
        }
    }

    //设置最大投注
    public setMaxBet() {
        this.curBet = this.betGradeScData.MaxBet ?? 5000;
    }

    //设置最小投注
    public setMinBet() {
        this.curBet = this.betGradeScData.MinBet ?? 100;
    }

    //能够下注最大值 能够下10局
    public reSetMaxBet() {
        for (let i = this.betList.length - 1; i >= 0; i--) {
            let bet = this.betList[i];
            if (bet * 10 <= this.userMoneyNew) {
                this.curBetIndex = i;
                break;
            }
        }
        this.setCurBet(this.curBetIndex);
    }

    /**设置当前下注金额 */
    public setCurBet(index: number = 0) {
        this.curBetIndex = index;
        this.curBet = this.betList[this.curBetIndex];
    }

    //表现为1200->12,1288->12.88
    public setMoneyFormat(money: number) {
        const yuan = tools.convertCentsToYuan(money);
        const num = Number(yuan);
        return `${Number(num.toFixed(2))}`;
    }

    //1200->12.00,1288->12.88
    public convertCentsToYuan(money: number) {
        return tools.convertCentsToYuan(money);
    }

    // 比如 0.20显示为0.2  0.21显示0.21   0.227显示0.22  1.30显示1.3 1.00显示1
    public formatValue(value: number): string {
        // 1. 向下截断到 2 位小数（不是四舍五入）
        const truncated = Math.floor(value * 100) / 100;
        // 2. 转成字符串（最多 2 位小数）
        let str = truncated.toFixed(2);
        // 3. 去掉末尾的 0 和可能剩余的小数点
        str = str.replace(/\.?0+$/, '');
        return str;
    }

    //是否存在或者为0的时候再次赋值
    safeKey(v: any, value: any) {
        return (v === undefined || v === null || v === 0) ? value : v;
    }

    /*** 是否有效*/
    isVaild(target_: any) {
        if (target_ == undefined || target_ == null) {
            return false;
        }
        if (Array.isArray(target_)) {
            return target_.length > 0;
        } else {
            let keys = Object.keys(target_);
            let isVaild = keys.length > 0;
            return isVaild;
        }
    }

    /**声音相关 */
    public playMusic(name: string, isLoop: boolean = true, volume: number = 1) {
        //this.gm.stopMusic();
        //this.gm.playMusic(name, isLoop, volume);
    }
    public playEffect(name: string, isLoop: boolean = false, volume: number = 1) {
        this.gm.playEffect(name, isLoop, volume);
    }
    public stopEffect(name: string) {
        //this.gm.stopEffect(name);
    }
    public stopMusic(name: string = "") {
        //this.gm.stopMusic();
    }
    public pauseMusic(name: string = "") {
        //this.gm.pauseMusic();
    }
    public resumeMusic() {
        //this.gm.pauseMusic();
    }

    // 休眠函数 
    public sleep(time: number) {
        return new Promise((resolve, reject) => {
            setTimeout(() => {
                resolve(1);
            }, time * 1000)
        });
    }
}
export const slotMgr = new m_slotMgr();