import { ggLogger } from "db://gg-hot-update/scripts/hotupdate/GGLogger";
import TimerManager from "../cmd/TimerManager";

type GameAsyncCallback = (next: Function, params: any, queueParams?: any) => void;

export interface GameAsyncTask {

    uuid: string,
    callbacks: GameAsyncCallback[],
    isValid: boolean,
    params?: any,
    /** 上个任务执行完成传入的参数 */
    lastParams?: any
}


/** 流程异步队列 */
export class GameAsyncQueue {

    private _tag: string = "[ GameAsyncQueue ]: ";
    private _count: number = 1;
    public getUUid() {
        return this._tag + "count: " + this._count++;
    }
    private TaskList: GameAsyncTask[] = [];
    public complete: Function = null;
    private curentUUid: string = "";
    private curentTask: GameAsyncTask = null;
    private yieldTask: string[] = [];
    private _QueueParams: any = null;
    /** 
     * 增加队列参数 可用来在任务中相互传值 
     *  注: 数据可能在任务中被修改 谨慎添加 
     *  任务处理中第三个参数即可处理 
     *  */
    public addQueueParams(params: any) {
        this._QueueParams = params;
    }

    public getQueueParams() {
        return this._QueueParams;
    }

    /** 放入一个异步任务 */
    public push(task: GameAsyncCallback, params?: any) {

        let uuid = this.getUUid();
        let GameTask: GameAsyncTask = {
            uuid: uuid,
            callbacks: [task],
            isValid: true,
            params: params
        };
        this.TaskList.push(GameTask);
        return uuid;
    }

    public getRunningParams() {
        if (this.curentTask) {
            return this.curentTask.params;
        } else {
            return null;
        }
    }

    public isRunning() {
        let running = true;
        if (this.curentTask) {
            running = true;
        } else {
            running = false;
        }
        return running;
    }

    /** 跳过当前任务， 直接进行下一任务 */
    public step() {
        if (this.isRunning()) {
            this.next(this.curentTask.uuid);
        }
    }

    /** 队列是否已经运行完成 */
    public stop() {
        if (this.TaskList.length > 0) {
            return false;
        }
        if (this.isRunning()) {
            return false;
        }
        return true;
    }

    /** 一次性放入多个任务 */
    public pushMulti(params: any, ...tasks: GameAsyncCallback[]) {
        let uuid = this.getUUid();
        let GameTask: GameAsyncTask = {
            uuid: uuid,
            callbacks: tasks,
            isValid: true,
            params: params
        };
        this.TaskList.push(GameTask);
        return uuid;
    }

    private next(uuid, lastParams?: any) {
        if (this.curentUUid == uuid) {
            this.run(lastParams);
        } else {
            // cc.log("重复",this.curentTask);
            ggLogger.warn("next  任务重复运行, uuid: ", uuid);
        }

    }

    /** 延时一个任务 单位  s */
    public yieldTime(time: number) {
        let parSecond = time;
        this.push((next: Function, params: any, lastParams?: any) => {
            let second = params.parSecond;
            let uuid = TimerManager.inst().addTimeCallBack(second, () => {
                next && next(this.curentUUid, lastParams);
            });
            this.yieldTask.push("" + uuid);
        }, { parSecond: parSecond, des: "GameAsyncQueue.yieldTime" });
    }

    public run(lastParams?: any) {

        let task = this.TaskList.shift();
        if (task) {
            let uuid = task.uuid;
            this.curentUUid = uuid;
            let params = task.params;
            let callbacks = task.callbacks;
            this.curentTask = task;
            if (callbacks.length == 1) {

                let fun = callbacks[0];
                fun && fun(this.next.bind(this, uuid, lastParams), params, this._QueueParams);
            } else {
                let __promis = [];
                for (let i = 0; i < callbacks.length; i++) {
                    let singleCall = callbacks[i];
                    __promis.push(new Promise((resolve, reject) => {

                        singleCall && singleCall(resolve, params, this._QueueParams);
                    }));
                }
                Promise.all(__promis).then(() => {
                    this.next(uuid, lastParams);
                })
            }

        } else {
            this.curentTask = null;
            this.curentUUid = "";
            this.complete && this.complete();
        }
    }

    public static countTimeFun(count: number, complete: Function) {
        return () => {
            count--;
            if (count == 0) {
                complete && complete();
            }
        }
    }

    /** 直接清空一个队列 */
    public clear() {
        this.curentTask = null;
        this.curentUUid = null;
        this.TaskList.length = 0;
        this.complete = null;
        this._QueueParams = null;
        for (let i = 0; i < this.yieldTask.length; i++) {
            let uid = parseInt(this.yieldTask[i]);
            TimerManager.inst().removeTimeCallBack(uid);
        }
        this.yieldTask.length = 0;
    }
}
