import JSEncrypt from "jsencrypt";
import { config } from "../common/config";
import { OneSocket } from "../net/OneSocket";
import { tools } from "./tools";

/**验证码 */
export class Validate {
    // 发送验证信息
    static async sendValidate() {
        // 生成随机的发送和接收密钥
        const sendKey: number = tools.random(0, 255);
        const receiveKey: number = tools.random(0, 255);

        const validate = {
            SendKey: sendKey,
            ReceiveKey: receiveKey
        };

        OneSocket.getInstance().packData.sendKey = sendKey;
        OneSocket.getInstance().packData.recvKey = receiveKey;

        const publicKey = this.convertBase64ToPem(config.PublicKey);
        const validateDataString = JSON.stringify(validate);
        const encrypted = this.rsaEncrypt(validateDataString, publicKey);
        return encrypted;
    }

    /**
     * 将 Base64 编码的公钥转换为 PEM 格式
     */
    static convertBase64ToPem(base64Key: string): string {
        const formattedKey = base64Key.match(/.{1,64}/g)?.join("\n") || base64Key;
        return `-----BEGIN PUBLIC KEY-----\n${formattedKey}\n-----END PUBLIC KEY-----`;
    }

    static rsaEncrypt(data: string, publicKeyPem: string): string {
        const encryptor = new JSEncrypt();
        encryptor.setPublicKey(publicKeyPem);
        const encrypted = encryptor.encrypt(data);
        if (!encrypted) throw new Error("RSA encryption failed");
        return encrypted;
    }
}
