import { _decorator, AssetManager, Component, director, Game, game } from "cc";
import { AudioManager } from "../tools/AudioManager";

const { ccclass, property } = _decorator;
@ccclass
export abstract class BaseUI extends Component {
    onLoad() {
        game.off(Game.EVENT_HIDE, this.onGameHide);
        game.off(Game.EVENT_SHOW, this.onGameShow);
        game.on(Game.EVENT_HIDE, this.onGameHide);
        game.on(Game.EVENT_SHOW, this.onGameShow);
    }

    onEnable() { }

    start() { }

    update(dt: number) { }

    lateUpdate(dt: number) { }

    onDisable() {
        this.unscheduleAllCallbacks();
    }

    onDestroy() {
        this.unscheduleAllCallbacks();
        game.off(Game.EVENT_HIDE, this.onGameHide);
        game.off(Game.EVENT_SHOW, this.onGameShow);
    }

    onGameHide() {
        director.emit("onGameHideEvent", this);
    }

    onGameShow() {
        director.emit("onGameShowEvent", this);
    }

    playBtnClickEffect(name: string, bundle?: string | AssetManager.Bundle, loop: boolean = false) {
        if (AudioManager.instance) {
            AudioManager.instance.playEffect(name, bundle, loop);
        }
    }
}
