import { director } from "cc";
import { ggLogger } from "db://gg-hot-update/scripts/hotupdate/GGLogger";
import TimerManager from "../cmd/TimerManager";
import { PackageId } from "../common/PackageId";
import { common } from "../common/common";
import { config } from "../common/config";
import { i18n_t } from "../i18n/LanguageData";
import { AudioManager } from "../tools/AudioManager";
import { ui } from "../ui/ui";
import { BaseSocket } from "./BaseSocket";
import SocketPack from "./protocol/SocketPack";
import { Socket } from "./websocket/Socket";

export class OneSocket extends BaseSocket {
    private static _instance: OneSocket = null;
    private _socket: Socket = null;
    private _data = null;
    private _reconnectCnt: number = 0;
    private _stopMessage = false;
    private _timeout: number = 0;
    public packData = new SocketPack();

    constructor() {
        super();
        //网络错误改变场景
        director.on("networkError", () => {
            if (!this.isConnected()) {
                AudioManager.instance?.setMusicVolume(0);
                AudioManager.instance?.playMusic("");
                ui.changeScene("Lobby", "LoginScene");
                ui.isShowNetworkError = false;
            }
        }, this);
        //清除游戏网络
        director.on("clearGameNet", () => {
            this.clearGameNetCallbacks();
        }, this);
        //处理数据错误
        director.on("deelDataFail", (data) => {
            this.clearGameNetCallbacks();
            this.deelDataFail(data);
        }, this);
    }

    sendData(responseId: PackageId, data: ArrayBuffer, callbackFun = null) {
        // this.log("[OneSocket] sendData==>", `responseId= ${responseId},isConnect=${this.isConnected()}`);
        if (callbackFun) {
            this.bindingNetCallback(responseId, callbackFun);
        }

        if (this.isConnected()) {
            this.send(data);
        } else {
            this._data = data;
            this.connect();
        }
    }

    connect() {
        this.clearSocket();
        this._socket = new Socket(this, "sk-" + Date.now());
        let ws = config.ws.head;
        let addr = config.ws.addr;
        let port = config.ws.port;
        this._socket.connect(ws, addr, port);
    }

    onReConnected() {
        // 重连成功后，清理可能导致问题的游戏相关回调
        director.emit("roomNetChange", true);
    }

    onNoReConnected() {
        ui.createTips(i18n_t("dycLan.GameServerOffAgainLogin"));
        director.emit("hideNetNode");
    }

    onConnected() {
        this._reconnectCnt = 0;
        this._stopMessage = false;
        common.ISH5CLOSE = false;
        if (this._data) this.send(this._data);
    }

    deelDataFail(msgId: number) {
        if (msgId == PackageId.MsgResHint) {
            director.emit("roomNetChange", false);
            director.emit("clearNetData");
            setTimeout(() => {
                this.onReConnected();  // 100毫秒后触发重连
            }, 100);
        } else {
            director.emit("hideNetNode");
        }
    }

    onMessage(data: ArrayBuffer) {
        if (this._stopMessage) return;

        let obj = this.packData.unpack(data);
        if (!obj) {
            ggLogger.warn("onMessage 解包失败，收到非法数据，跳过处理");
            return;
        }
        const timestamp = Math.floor(Date.now() / 1000);
        if (Math.abs(obj['time'] - timestamp) > 60) {
            return;
        }

        let msgID = obj["msgId"];
        if (msgID == PackageId.MsgHeartbeat) {//心跳包
            return;
        }
        // ggLogger.log("onMessage msgId: " + obj["msgId"], obj["encryptType"]);
        let netCallback = this.getCallbackFun(msgID);
        if (netCallback) {
            netCallback(obj);
        } else {
            director.emit("LobbyMessage", obj);
        }

        director.emit("SocketMessage", { bResult: true, msg: "" });
    }

    onError() { }

    onHeartbeat() {
        this._socket.startHeartbeat();
    }

    onClosed() {
        this._reconnectCnt++;//断线重连次数
        if (this._reconnectCnt == 5) {//5次返回到登陆界面
            ui.showNetworkError();
        }
    }

    send(data: ArrayBuffer) {
        this._socket.send(data);
    }

    clearSocket() {
        if (this._socket) {
            this._socket.close();
            delete this._socket;
            this._socket = null;
        }
    }

    close(code?: number, reason?: string) {
        if (this._socket) {
            this._socket.close(code, reason);
        }
    }

    isConnected(): boolean {
        if (this._socket) {
            return this._socket.isConnected();
        }
        return false;
    }

    stopMessage() {
        this._stopMessage = true;
    }

    recoverMessage() {
        if (this._socket) this._stopMessage = false;
    }

    disconnectStop() {
        this.clearSocket();
    }

    setAutoReconnect(enabled: boolean) {
        if (this._socket) {
            this._socket.setAutoReconnect(enabled);
        }
    }

    retryConnectManually() {
        if (this._socket) {
            this._socket.retryConnectManually();
        }
    }

    isValidateSucc() {
        return new Promise((resolve, reject) => {
            TimerManager.inst().removeTimeCallBack(this._timeout);
            this._timeout = TimerManager.inst().addAlwayTimeCallBack(0.02, () => {
                if (this.isConnected()) {
                    TimerManager.inst().removeTimeCallBack(this._timeout);
                    resolve(null);
                }
            }, this)
        })
    }

    static getInstance(): OneSocket {
        if (null == this._instance) {
            this._instance = new OneSocket();
        }
        return this._instance;
    }

    static destroyInstance() {
        if (this._instance) {
            this._instance.disconnectStop();
            delete this._instance;
            this._instance = null;
        }
    }
}