import { UIOpacity,tween,_decorator, CircleCollider2D, Collider2D, Component, Contact2DType, IPhysics2DContact, Node, RigidBody2D, Sprite, UITransform } from 'cc';
import { PlinkoCirclePlayer } from './PlinkoCirclePlayer';
import { GameTempCore } from './PlinkoCore';
import { ggLogger } from 'db://gg-hot-update/scripts/hotupdate/GGLogger';
import { MotionTrail } from '../../Lobby/src/cmd/MotionTrail';

const { ccclass, property } = _decorator;

@ccclass('PlinkoPile')
export class PlinkoPile extends Component {

    private pileEffect: Node | null = null;

    canEffect: boolean = true;
    public rowSize: number = 8;
    private contactBound = false;
    private colliderInited = false;


    //行列
    public colIndex:number = 0;
    public rowIndex:number = 0;

    private rigidBody: RigidBody2D | null = null;

    protected onLoad(): void {
        this.pileEffect = this.node.getChildByName("effect");
    }

    public initPile(row: number,colIndex:number,rowIndex:number) {
        this.rowSize = row;
        this.colIndex = colIndex;
        this.rowIndex = rowIndex;

        const rowType = GameTempCore.slotConfig.rowList.indexOf(row);

        //const spriteFrameList = GameTempCore.slotMgr.GameMainCmp.pileSpritFrameList;
        //this.getComponent(Sprite)!.spriteFrame = spriteFrameList[rowType];

        if (!this.colliderInited) {
            /*const radius = this.getComponent(UITransform)!.width * 0.5 - 1;
            this.getComponents(CircleCollider2D).forEach(c => {
                c.radius = radius;
                c.apply();
            });*/
            this.colliderInited = true;
        }

        this.pileEffect = this.node.getChildByName("effect");
        const scales = [1, 0.8, 0.6, 0.5];
        //this.pileEffect!.setScale(scales[rowType], scales[rowType], 1);
    }

    public enablePilePhysics(enable: boolean) {

        if (!this.rigidBody) {
            this.rigidBody = this.getComponent(RigidBody2D);
        }
        this.rigidBody!.enabled = enable;

        this.getComponents(Collider2D).forEach(c => {
            c.enabled = enable;
            if (enable && !this.contactBound) {
                c.on(Contact2DType.BEGIN_CONTACT, this.onBeginContact, this);
                this.contactBound = true;
            }
        });

        this.pileEffect!.active = false;
        this.canEffect = enable;
    }

    async onBeginContact(selfCollider: Collider2D, otherCollider: Collider2D, contact: IPhysics2DContact) {
        if (!this.canEffect || !this.pileEffect) return;

        this.canEffect = false;

        //selfCollider.restitution = Math.random() * 0.1+0.1;
        //selfCollider.friction = Math.random() * 0.3 + 0.3;

        const player = otherCollider.getComponent(PlinkoCirclePlayer);
        if (!player) return;

        const trailChildNode = otherCollider.node.getChildByName('trail');
        if (trailChildNode) {
            trailChildNode.active = true;
            const motionTrail = trailChildNode.getComponent(MotionTrail);
            if (motionTrail) {
                motionTrail.ensureRenderData();
                motionTrail.refresh();
            }
        }

        this.pileEffect.active = true;
        let bgOpacity = this.pileEffect.getComponent(UIOpacity)
        bgOpacity.opacity = 255;
        tween(bgOpacity).to(0.3, { opacity: 0 }).start();

        GameTempCore.slotMgr.GameMainCmp.gameProcess.playEffect_plinko_collide();

        this.scheduleOnce(() => {
            this.canEffect = true;
        }, 0.3);

    }

    public async ChangeLight()
    {
        this.pileEffect.active = true;
        let bgOpacity = this.pileEffect.getComponent(UIOpacity)
        bgOpacity.opacity = 255;
        tween(bgOpacity).to(0.3, { opacity: 0 }).start();

        GameTempCore.slotMgr.GameMainCmp.gameProcess.playEffect_plinko_collide();

        this.scheduleOnce(() => {
            this.canEffect = true;
        }, 0.3);
    }
}
