    private handleWindowMessage = (event: MessageEvent) => {
        if (event.origin !== window.location.origin) return;
        const payload = event.data;
        if (!payload || payload.source !== "game-on-web") return;

        switch (payload.type) {
        case "GetBallResponse":
        // payload.data 就是后端 `/BuddyBalls/play` 的数据
        // payload.requestId 与你发出的请求对应
        // hydrateBuddyBallsState(payload.data);
            ggLogger.log("GetBallResponse", payload);
            this.responseBetData(payload.data);
            this.ballCount--;
            this.setBallCount(this.ballCount);
            break;
        case "GetBallCountResponse":
        // payload.data 就是后端 `/BuddyBalls/index` 的数据
        // payload.requestId 与你发出的请求对应
        // hydrateBuddyBallsState(payload.data);
            ggLogger.log("GetBallCountResponse", payload);
            this.ballCount = payload.data.data.balls;
            this.setBallCount(payload.data.data.balls);
            break;
        case "GetBallError":
            ggLogger.log("GetBallError", payload);
            break;
        case "ViewwportSize":
            ggLogger.log("ViewwportSize", event.data);
            GameConfig.ScreenWidth = event.data.width;
            GameConfig.ScreenHeight = event.data.height;
            //this.node.parent.setScale(GameConfig.ScreenWidth / 375, GameConfig.ScreenHeight / 525, 1);
            break;
        }
    };

