    private GetTrail(): Node {
        const curNode = instantiate(this.trailObj);
        curNode.active = false;
        const opacity = curNode.getComponent(UIOpacity);
        if (opacity) {
            opacity.opacity = 255;
        }
        return curNode;
    }

    
    private RecycleTrail(curNode:Node) {
        curNode.active = false;
        const opacity = curNode.getComponent(UIOpacity);
        if (opacity) {
            opacity.opacity = 0;
        }
        if (this.spawnPoint) {
            curNode.setWorldPosition(this.spawnPoint.worldPosition);
        }
    }

    //生成虚拟球
    private spawnVirtualBall() {
        if (!this.node || !this.spawnPoint) return;

        const virtualBallNode = this.GetVirtualBall();
        if (!virtualBallNode) return;
        virtualBallNode.setParent(this.virtualPool);
        virtualBallNode.getComponent(RigidBody2D).linearVelocity = new Vec2(0, 0);
                // ===== 随机起始点 =====
        let x = Math.random()*30-15;

        // ===== 设置位置 =====
        // this.spawnPoint.y = this.spawnPointOrginalPositon.y - slotMgr.rowType * 5;
        virtualBallNode.setPosition(x, this.spawnPoint.y, this.spawnPoint.z);
        // 基础节点设置
        virtualBallNode.name = "PlinkoVirtualBall";
        virtualBallNode.active = true;
    }

    private GetVirtualBall(): Node {
        for(let i = 0; i < this.virtualPool.children.length; i++) {
            if (!this.virtualPool.children[i].active) {
                return this.virtualPool.children[i];
            }
        }
        return instantiate(this.VirtualBall);
    }

    private RecycleVirtualBall(curNode:Node) {
        curNode.active = false;
    }

    // 生成球
    private spawnCirclePlayer(data?: any) {
        if (!this.node || !this.spawnPoint) return;

        const circleNode = this.GetTrail();
        if (!circleNode) return;

        this.circlePlayerNode = circleNode;
        // 基础节点设置（先挂父节点，再设置世界坐标，避免首次实例化因坐标系切换导致拖尾跳变/被清空）
        circleNode.setParent(this.trailPool);
        circleNode.setWorldPosition(this.spawnPoint.worldPosition);
        circleNode.name = "PlinkoCirclePlayer";
        //circleNode.setSiblingIndex(this.spawnPoint.getSiblingIndex());
        circleNode.active = true;

        const trailNode = circleNode.getChildByName('trail');
        if (trailNode) {
            trailNode.active = false;
            const motionTrail = trailNode.getComponent(MotionTrail);
            if (motionTrail) {
                const tryEnableTrail = () => {
                    if (!trailNode.isValid || !circleNode.isValid) return;
                    if (!motionTrail.spriteFrame || !motionTrail.spriteFrame.texture) {
                        this.scheduleOnce(tryEnableTrail, 0);
                        return;
                    }
                    trailNode.active = true;
                    motionTrail.enabled = true;
                    motionTrail.isActive = true;
                    motionTrail.ensureRenderData();
                    motionTrail.refresh();
                };
                this.scheduleOnce(tryEnableTrail, 0);

                if (this.isFirstBall) {
                    this.isFirstBall = false;
                    this.gameProcess.setIsFirstBall(circleNode, true);
                    this.scheduleOnce(() => {
                        motionTrail.ensureRenderData();
                        motionTrail.refresh();
                    }, 0.2);
                    this.scheduleOnce(() => {
                        motionTrail.ensureRenderData();
                        motionTrail.refresh();
                    }, 1.0);
                }
            }
        }

        
        // ===== 计算范围 =====

        // console.log("rewardId:", slotMgr.rewardID, "spawnX:", x);
        this.gameProcess.setCirclePlayerInfo(circleNode);

        this.CreateVirtual(3);
    }

