    //生成奖励项并自动滑动
    public spawnRewardAndScroll(index:number) {
        const value = GameTempCore.MultiList[index]*0.01;
        if(value< 0.0001)
            return; 
        let childInd = GameTempCore.MultiColor[index];
        let child = this.rewardGroup.getChildByName(childInd.toString());
        if (!child) return;
        let newChild = instantiate(child);
        this.rewardGroup.addChild(newChild);
        newChild.active = true;
        newChild.getChildByName("label").getComponent(Label).string = "+" + value.toString() + " USDT";
        this.scrollPar.getComponent(ScrollView).scrollToLeft(0.3);

        let op = this.angleLight.getComponent(UIOpacity);
        op.opacity = 255;
        tween(op).delay(0).to(0.5, { opacity: 0 }).start();
    }


    private getPileLayoutInfo() {
        const curLayer = this.gameProcess.getCurBallRowLayer();
        if (!curLayer) return null;

        const pileGroup = curLayer.getChildByName("PileGroup");
        const firstPileGroup = pileGroup?.getChildByName("3");
        if (!firstPileGroup || firstPileGroup.children.length < 2) return null;

        let piles = firstPileGroup.children;

        let pileWidth = piles[0].getComponent(UITransform)?.width ?? 0;
        let distance = piles[1].x - piles[0].x;
        let radius = GameTempCore.slotConfig.circlePlayerRadus[slotMgr.rowType];

        return { pileWidth, distance, radius };
    }

    private calcStartX(pox1: number, pox2: number, pox3: number, pox4: number, centerX: number) {
        let x = this.randomIntOrHalf(pox1, pox4);
        const specialId = [
            0, 1, 2, 3,
            slotMgr.gameRow - 3, slotMgr.gameRow - 2, slotMgr.gameRow - 1, slotMgr.gameRow,
        ];
        let isEdgeReward = specialId.includes(slotMgr.rewardID);
        if (isEdgeReward) {
            const isLeft = slotMgr.rewardID <= slotMgr.gameRow * 0.5;
            x = isLeft ? this.randomIntOrHalf(pox1, pox2) : this.randomIntOrHalf(pox3, pox4);

            if (slotMgr.rowType == 3) {
                x = isLeft ? x - 6 : x + 6;
            }
        }
        return x;
    }

    randomIntOrHalf(min: number, max: number): number {
        const start = min * 2;
        const end = max * 2;
        const r = Math.floor(Math.random() * (end - start + 1)) + start;
        return r / 2;
    }

