    /**置灰 按钮文字 可点击 */
    public async setGrayNode2(node: Node, isGray: boolean = true) {
        let path = `res/meterial/textureGray`;
        let meterialGray = await tools.loadMaterial(node, path, this.bundleName);
        var list = tools.getNodeList(node);
        for (var i = 0; i < list.length; i++) {
            var sprite = list[i].getComponent(Sprite);
            var label = list[i].getComponent(Label);
            let material = isGray ? meterialGray : null;
            if (sprite && sprite.isValid) {
                sprite.customMaterial = material;
            }
            if (label && label.isValid) {
                label.customMaterial = material;
            }
        }
    }

