import { ggLogger } from "db://gg-hot-update/scripts/hotupdate/GGLogger";

export abstract class BaseSocket {
    private _callbackFunList = {};


    constructor() { }

    private getCallbackFunKey(mainID: number): string {
        return `${mainID}`;
    }
    bindingNetCallback(mainID: number, callbackFun) {
        this._callbackFunList[this.getCallbackFunKey(mainID)] = callbackFun;
    }
    removeNetCallback(mainID: number) {
        let key: string = this.getCallbackFunKey(mainID);
        if (this._callbackFunList[key]) {
            delete this._callbackFunList[key];
        }
    }
    getCallbackFun(mainID: number): any {
        let key: string = this.getCallbackFunKey(mainID);
        let fun = this._callbackFunList[key];
        if (fun) {
            return fun;
        }
        return null;
    }

    /**
     * 清理所有网络回调函数
     * 用于重连后确保状态干净
     */
    clearAllNetCallbacks() {
        this._callbackFunList = {};
    }

    /**
     * 清理游戏相关的网络回调（保留大厅相关回调）
     * 用于重连后避免游戏状态混乱
     */
    clearGameNetCallbacks() {
        // 这里可以添加逻辑，只清理游戏相关的回调
        // 暂时清理所有，后续可以根据需要细化
        const keysToKeep = []; // 可以添加需要保留的回调key
        const newCallbackList = {};

        keysToKeep.forEach(key => {
            if (this._callbackFunList[key]) {
                newCallbackList[key] = this._callbackFunList[key];
            }
        });

        this._callbackFunList = newCallbackList;
    }

    log(socketName: string, message: string, level: 'log' | 'warn' | 'error' = 'log') {
        const tag = `[${socketName}]`;
        const full = `${tag} ${message}`;
        switch (level) {
            case 'warn': ggLogger.warn(full); break;
            case 'error': ggLogger.error(full); break;
            default: ggLogger.log(full);
        }
    }
    abstract onNoReConnected();
    abstract onReConnected();
    abstract onConnected();
    abstract onMessage(data);
    abstract onError();
    abstract onClosed();
    abstract connect(callbackFun);
    abstract send(data);
    abstract close(code?: number, reason?: string);
    abstract isConnected(): boolean;

}